const DEV = process.env.NODE_ENV !== 'production';
// App version — single source of truth is package.json ("version": "26.1.0"); APP_VERSION derives from it.
// Display = v{major}.{minor zero-padded to 3} (+ .{patch} if non-zero): 26.1.0 -> "v26.001", 25.676.0 -> "v25.676".
// Bump on every change (Ben's rule): `npm version minor` -> next v26 is v26.002, v26.003, …
const APP_VERSION = (() => { try {
  const v = JSON.parse(readFileSync(new URL('./package.json', import.meta.url), 'utf8')).version || '0.0.0';
  const [maj, min, pat] = v.split('.');
  return 'v' + maj + '.' + String(min || '0').padStart(3, '0') + (pat && pat !== '0' ? '.' + pat : '');
} catch { return 'v0'; } })();

// Replace the value of a top-level `let/const/var NAME = <literal>;` by balancing brackets.
function replaceGlobal(html, name, jsonText) {
  const m = html.match(new RegExp('(?:const|let|var)\\s+' + name + '\\s*=\\s*([\\[{])'));
  if (!m) throw new Error(`global ${name} not found`);
  const start = m.index + m[0].length - 1;
  const open = html[start], close = open === '[' ? ']' : '}';
  let depth = 0, i = start, inStr = false, esc = false, q = '';
  for (; i < html.length; i++) {
    const ch = html[i];
    if (inStr) { if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === q) inStr = false; }
    else if (ch === '"' || ch === "'") { inStr = true; q = ch; }
    else if (ch === open) depth++;
    else if (ch === close) { depth--; if (depth === 0) { i++; break; } }
  }
  // Harden inline-script injection (H2): a baked DB string containing "</script>" (or a raw U+2028/U+2029 line
  // separator) would otherwise break out of the inline <script> and inject HTML into every staff page load. The
  // injected value is JSON, which only emits these characters INSIDE string values, so unicode-escaping them keeps
  // the decoded value byte-identical while making break-out impossible.
  const safe = String(jsonText).replace(/</g, '\\u003c').replace(/>/g, '\\u003e').replace(/\u2028/g, '\\u2028').replace(/\u2029/g, '\\u2029');
  return html.slice(0, start) + safe + html.slice(i);
}

// Latest change across the ETL-fed SOURCE data that gets BAKED into the page (and is otherwise frozen for an
// open tab): sales, inventory/products, on-order/inbound, Flexport. Deliberately EXCLUDES user-edited tables
// (forecast_inputs, purchase_orders, deposits) — their updated_at bumps on the user's own edits, which would
// otherwise force a reload on every edit. Drives EXTRACT_TS + the client's data-freshness auto-reload.
async function freshness() {
  const SRC = { sales_actuals: 'loaded_at', products: 'updated_at', inbound_shipments: 'updated_at', flexport_shipments: 'updated_at' };
  try {
    const have = (await pool.query(`SELECT table_name, column_name FROM information_schema.columns
      WHERE table_schema='planner' AND table_name=ANY($1) AND column_name=ANY($2)`,
      [Object.keys(SRC), [...new Set(Object.values(SRC))]])).rows;
    const parts = Object.keys(SRC).filter(t => have.some(r => r.table_name === t && r.column_name === SRC[t]))
      .map(t => `SELECT max(${SRC[t]}) ts FROM planner.${t}`);
    if (!parts.length) return null;
    const { rows } = await pool.query(`SELECT max(ts) AS ts FROM (${parts.join(' UNION ALL ')}) x`);
    return rows[0].ts ? new Date(rows[0].ts).toISOString() : null;
  } catch (e) { return null; }
}
// 60s-cached freshness for the frequently-polled /api/version (avoids re-scanning on every client poll).
let _freshCache = { at: 0, val: null };
async function freshnessCached() {
  const now = Date.now();
  if (now - _freshCache.at < 60000) return _freshCache.val;
  _freshCache = { at: now, val: await freshness() };
  return _freshCache.val;
}

// The plan's subcategory rows are driven by AVAILABILITY (v_product_availability), not just sales history — so an
// available-but-never-sold subcategory (e.g. a Non-Core line only sold in one market) still shows in every market
// it's available. Sales history (category_sales_summary) fills the month cells where it exists. SKUs/subcats with no
// category/subcategory (or the view's 'Unknown') roll up under a synthetic "Undefined sub category" (the client
// sorts it to the top). (Ben, v26.833.)
const UNDEF_SUBCAT = 'Undefined sub category';
function _normCat(v) { const t = (v == null ? '' : String(v).trim()); return (t === '' || t === 'Unknown') ? UNDEF_SUBCAT : t; }
// Non-SKUs / data artefacts that must never appear in the planner (Ben: GIFTWRAP-BOX is not a real SKU). Excluded at the
// data-load queries below. The complete fix is removing them from the PIM; this is a hard guard so they can't leak through.
const NON_SKUS = ['GIFTWRAP-BOX'];
const NON_SKU_LIST = NON_SKUS.map(s => `'${String(s).replace(/'/g, "''")}'`).join(',');
async function buildDATA() {
  const [salesR, availR] = await Promise.all([
    pool.query(`SELECT category c, subcategory s, country co, channel ch,
                       is_excluded_category x, to_char(month,'YYYY_MM') ym, units::int u, revenue::float r
                FROM planner.category_sales_summary WHERE subcategory IS NOT NULL`),
    // one row per (category, subcategory, country, channel) that has ≥1 AVAILABLE SKU in planning scope
    pool.query(`SELECT DISTINCT p.category c, p.subcategory s, upper(a.country) co, a.channel ch
                FROM planner.v_product_availability a JOIN planner.products p ON p.sku = a.sku
                WHERE a.is_available AND p.in_planning_scope AND p.sku NOT IN (${NON_SKU_LIST})`),
  ]);
  const byKey = {};
  for (const row of salesR.rows) {
    const c = _normCat(row.c), s = _normCat(row.s), k = c + '|' + s + '|' + row.co + '|' + row.ch;
    if (!byKey[k]) byKey[k] = { c, s, co: row.co, ch: row.ch, x: row.x, m: {} };
    byKey[k].m[row.ym] = [row.u, row.r];
  }
  for (const row of availR.rows) {   // available but unsold → add the row with an empty history so it still shows
    const c = _normCat(row.c), s = _normCat(row.s), k = c + '|' + s + '|' + row.co + '|' + row.ch;
    if (!byKey[k]) byKey[k] = { c, s, co: row.co, ch: row.ch, x: false, m: {} };
  }
  return Object.values(byKey);
}

// value_raw is the raw IV string the user typed: a growth decimal ("0.3"), an absolute
// (">=4"), or an apostrophe-prefixed literal ("'2"). FC_CURRENT bakes the *encoded number*
// that FC_SEED -> IV decodes back to that string (the .0001 sentinel marks small literals).
// This mirrors buildSavePayload()'s save-encoding exactly so the artefact round-trips unchanged.
function encodeRaw(raw) {
  if (raw == null) return null;
  const s = String(raw);
  if (s.charAt(0) === "'") {
    const n = parseInt(s.slice(1), 10);
    if (!isNaN(n)) return n >= 4 ? n : (n + 0.0001);
  }
  const f = parseFloat(s);
  return isNaN(f) ? null : f;
}

async function buildFC_CURRENT() {
  const { rows } = await pool.query(`
    SELECT subcategory s, country co, channel ch, to_char(month,'YYYY_MM') ym, value_raw
    FROM planner.forecast_inputs`);
  const out = {};
  for (const row of rows) {
    const v = encodeRaw(row.value_raw);
    if (v == null) continue;
    const k = row.s + '|' + row.co + '|' + row.ch;
    if (!out[k]) out[k] = {};
    out[k][row.ym] = v;
  }
  return out;
}

// SKU-level forecast: rebuild FC_OUTPUTS {"sku|warehouse|channel":{ym:units}} from
// planner.forecast_outputs (the editable SKU plan). Mirrors the baked global's shape.
async function buildFC_OUTPUTS() {
  const { rows } = await pool.query(`
    SELECT sku, warehouse wh, channel ch, to_char(month,'YYYY_MM') ym, units::int u
    FROM planner.forecast_outputs`);
  const out = {};
  for (const row of rows) {
    const k = row.sku + '|' + row.wh + '|' + row.ch;
    if (!out[k]) out[k] = {};
    out[k][row.ym] = row.u;
  }
  return out;
}

// _SKU_RAW: the keystone SKU global. Three parts (matches the baked shape exactly):
//   p {sku:{n,s,c,ti,cs,av,disc,lch,inv,oo}} - master (planning-scope SKUs)
//   s {"sku|COUNTRY|CHANNEL":{ym:units}}      - sales history (all SKUs)
//   i {"sku|warehouse":[{ref,qty,eta,type}]}  - open inbound shipments
// av (channel-availability string e.g. "dfb") derived from v_product_availability;
// oo (on-order) derived from outstanding inbound — both fill gaps the baked snapshot lacked.
async function buildSKURAW() {
  const [prods, pcs, inv, avail, oo, sales, inbound, openpo] = await Promise.all([
    pool.query(`SELECT p.sku, p.product_name n,
                       coalesce(nullif(btrim(p.subcategory),''),'Undefined sub category') s,
                       coalesce(nullif(btrim(p.category),''),'Undefined sub category') c,
                       p.market_tier ti, p.core_seasonal cs, coalesce(sl.release_window,'') rw,
                       nullif(trim(p.replacement_sku),'') rep,
                       coalesce(nullif(trim(p.variant_image_url_final),''), nullif(trim(p.colour_swatch_url),'')) img,   -- variant image, falling back to the colour swatch when blank
                       nullif(trim(p.colour_swatch_url),'') sw,   -- colour swatch URL — client-side fallback when the variant image URL 404s
                       upper(coalesce(nullif(btrim(p.status),''),'')) st,
                       upper(coalesce(nullif(btrim(p.variant_type),''),'MASTER')) vt   -- MASTER | SET (blank ⇒ MASTER); SETS feature identifies build-on-fly set SKUs
                FROM planner.products p LEFT JOIN planner.v_sku_attrs sl ON sl.sku=p.sku WHERE p.in_planning_scope AND p.sku NOT IN (${NON_SKU_LIST})`),
    // Launch + discontinue dates per country, from planner.products (Ben's single source of truth).
    // Values are already ISO text on products, so pass through; the artifact compares them as strings.
    pool.query(`SELECT sku, co, lch, disc FROM (
                  SELECT sku, 'uk' co, coalesce(nullif(launch_date_uk_final,''), nullif(launch_date_uk,'')) lch, nullif(discontinue_date_final,'') disc FROM planner.products WHERE in_planning_scope
                  UNION ALL
                  SELECT sku, 'us', nullif(launch_date_us,''), nullif(discontinue_date_final,'') FROM planner.products WHERE in_planning_scope
                  UNION ALL
                  SELECT sku, 'eu', nullif(launch_date_eu,''), nullif(discontinue_date_final,'') FROM planner.products WHERE in_planning_scope
                  UNION ALL
                  SELECT sku, 'au', coalesce(nullif(launch_date_au_final,''), nullif(launch_date_au,'')), nullif(discontinue_date_au_final,'') FROM planner.products WHERE in_planning_scope
                  UNION ALL
                  SELECT sku, 'ca', nullif(launch_date_ca_retail,''), nullif(discontinue_date_ca,'') FROM planner.products WHERE in_planning_scope
                ) x WHERE lch IS NOT NULL OR disc IS NOT NULL`),
    pool.query(`SELECT sku, warehouse wh, available::int qty FROM planner.v_product_inventory`),
    pool.query(`SELECT sku, lower(country) co,
                       string_agg(CASE channel WHEN 'DTC' THEN 'd' WHEN 'FBA' THEN 'f' WHEN 'B2B' THEN 'b' WHEN 'TIK' THEN 't' END,
                                  '' ORDER BY CASE channel WHEN 'DTC' THEN 1 WHEN 'FBA' THEN 2 ELSE 3 END)
                         FILTER (WHERE is_available) av
                FROM planner.v_product_availability GROUP BY sku, country`),
    // On-order = confirmed inbound (inbound_shipments) + open/planning POs not yet in that feed, deduped by PO
    // reference so a PO isn't double-counted once it syncs through to inbound. PO → warehouse: country_code (or
    // the branch's country) + fba/3pl from the branch name.
    pool.query(`SELECT sku, wh, sum(oo)::int oo FROM (
                  SELECT sku, destination_warehouse wh, (quantity - coalesce(received_quantity,0)) oo
                    FROM planner.inbound_shipments WHERE coalesce(received_quantity,0) < quantity
                  UNION ALL
                  SELECT l.sku,
                    lower(coalesce(nullif(po.country_code,''), b.country_code)) || '_' ||
                      (CASE WHEN po.branch ILIKE '%fba%' THEN 'fba' ELSE '3pl' END) wh,
                    l.qty oo
                    FROM planner.purchase_order_lines l
                    JOIN planner.purchase_orders po ON po.po = l.po
                    LEFT JOIN planner.branches b ON b.name = po.branch
                    WHERE coalesce(l.qty,0) > 0
                      AND coalesce(po.status,'') NOT ILIKE '%complete%'
                      AND po.master_po IS NULL   -- child POs are consolidated into a master; the master (real on-order PO) carries the summed lines, so count it not them
                      AND coalesce(nullif(po.country_code,''), b.country_code) IN ('UK','US','EU','AU','CA')
                      AND NOT EXISTS (SELECT 1 FROM planner.inbound_shipments i WHERE i.reference = po.po)
                ) z WHERE wh IS NOT NULL GROUP BY sku, wh`),
    pool.query(`SELECT sku, country co, channel ch, to_char(month,'YYYY_MM') ym, units::int u
                FROM planner.sales_actuals`),
    pool.query(`SELECT i.sku, i.destination_warehouse wh, i.reference ref, i.quantity::int qty,
                       to_char(i.estimated_delivery_date,'YYYY-MM-DD') eta, i.source_type type,
                       coalesce(su.name,'') supplier,
                       -- PO-grid (into-stock) date, used as the fallback when estimated_delivery_date is in the past:
                       -- shipment arrival/landing (shipment-date authority), else PO landing override, else the
                       -- calculated landing (prod_end + 7 ship + branch sea transit) — same basis as the SUPPLY PO view.
                       to_char(coalesce(sh.arrival_date, sh.delivery_date, sh.landing_date, po.landing_date_overide,
                                 (coalesce(po.end_production_overide,
                                    CASE WHEN po.start_production IS NOT NULL AND su.production_days IS NOT NULL
                                         THEN (po.start_production + (su.production_days||' days')::interval)::date END)
                                  + interval '7 days' + (b.sea_lead_time_days||' days')::interval)::date),'YYYY-MM-DD') po_eta
                FROM planner.inbound_shipments i
                LEFT JOIN planner.purchase_orders po ON po.po = i.reference
                LEFT JOIN planner.suppliers su ON su.id = po.supplier_id
                LEFT JOIN planner.branches b ON b.name = po.branch
                LEFT JOIN planner.shipments sh ON sh.shipment_ref = po.shipment_ref
                WHERE coalesce(i.received_quantity,0) < i.quantity
                ORDER BY i.estimated_delivery_date`),
    // Open POs counted in on-order but NOT yet in the inbound feed — shown as "on order / not shipped" line items
    // so the PLAN inbound list reconciles with the on-order total. Same warehouse mapping + dedup as the oo query.
    pool.query(`SELECT l.sku,
                  lower(coalesce(nullif(po.country_code,''), b.country_code)) || '_' ||
                    (CASE WHEN po.branch ILIKE '%fba%' THEN 'fba' ELSE '3pl' END) wh,
                  po.po ref, l.qty::int qty, coalesce(po.status,'') status, coalesce(s.name,'') supplier,
                  -- estimated landing (delivery to warehouse), same calc as the SUPPLY PO view for an
                  -- unshipped PO: prod_end (override ▸ start + supplier days) + 7 (ship) + branch sea transit.
                  to_char((coalesce(po.end_production_overide,
                             CASE WHEN po.start_production IS NOT NULL AND s.production_days IS NOT NULL
                                  THEN (po.start_production + (s.production_days||' days')::interval)::date END)
                           + interval '7 days' + (b.sea_lead_time_days||' days')::interval)::date,'YYYY-MM-DD') eta
                FROM planner.purchase_order_lines l
                JOIN planner.purchase_orders po ON po.po = l.po
                LEFT JOIN planner.branches b ON b.name = po.branch
                LEFT JOIN planner.suppliers s ON s.id = po.supplier_id
                WHERE coalesce(l.qty,0) > 0
                  AND coalesce(po.status,'') NOT ILIKE '%complete%'
                  AND coalesce(nullif(po.country_code,''), b.country_code) IN ('UK','US','EU','AU','CA')
                  AND NOT EXISTS (SELECT 1 FROM planner.inbound_shipments i WHERE i.reference = po.po)`),
  ]);
  const p = {};
  for (const r of prods.rows)
    p[r.sku] = { n: r.n, s: r.s, c: r.c, ti: r.ti, cs: r.cs === 'Seasonal' ? 'S' : 'C',
                 csf: r.cs || '', // full core/seasonal classification (Core | Seasonal | Non-Core) for the BUY filter
                 rw: r.rw || '',  // release window (season) — shown on the BUY/FBA/Transfer grid after Type
                 rep: r.rep || '',  // replacement_sku (predecessor) — new SKU inherits its sales history as the forecast basis
                 img: r.img || '',  // variant_image_url_final — DEMAND plan optional variant-image thumbnail
                 sw: r.sw || '',    // colour swatch URL — client falls back to this if the variant image 404s
                 st: r.st || '',    // products.status (ACTIVE/…) — for the Key-Accounts "active only" SKU picker
                 vt: r.vt || 'MASTER',   // MASTER | SET — SETS feature (build-on-fly sets)
                 av: {}, disc: {}, lch: {}, inv: {}, oo: {} };
  for (const r of avail.rows) if (p[r.sku] && r.av) p[r.sku].av[r.co] = r.av;
  for (const r of pcs.rows) if (p[r.sku]) { if (r.lch) p[r.sku].lch[r.co] = r.lch; if (r.disc) p[r.sku].disc[r.co] = r.disc; }
  for (const r of inv.rows) if (p[r.sku]) p[r.sku].inv[r.wh] = r.qty;
  for (const r of oo.rows) if (p[r.sku] && r.oo > 0) p[r.sku].oo[r.wh] = r.oo;

  const s = {};
  for (const r of sales.rows) {
    const k = r.sku + '|' + r.co + '|' + r.ch;
    (s[k] || (s[k] = {}))[r.ym] = r.u;
  }
  const i = {};
  for (const r of inbound.rows) {
    const k = r.sku + '|' + r.wh;
    (i[k] || (i[k] = [])).push({ ref: r.ref || '', qty: r.qty || 0, eta: r.eta || null, poEta: r.po_eta || null, type: r.type || 'supplier_china', supplier: r.supplier || '' });
  }
  // Open POs not yet in the inbound feed — same key shape as `i`, tagged so the UI can label them "on order".
  const oi = {};
  for (const r of openpo.rows) {
    if (!r.wh) continue;
    const k = r.sku + '|' + r.wh;
    (oi[k] || (oi[k] = [])).push({ ref: r.ref || '', qty: r.qty || 0, eta: r.eta || null, type: 'open_po', status: r.status || '', supplier: r.supplier || '' });
  }
  return { p, s, i, oi };
}

// _SA_EXTRA: OUT-OF-SCOPE SKUs (NOT in_planning_scope, i.e. discontinued/dropped) that STILL carry
// stock or unreceived inbound. _SKU_RAW.p is planning-scope only, so the Stock Availability report
// couldn't see these. Same entry shape as p, tagged {oos:true}. Inbound (_SKU_RAW.i) and open-PO
// (_SKU_RAW.oi) maps are already built without a scope filter, so those SKUs' arrivals are present —
// we only need to supply the product meta + SOH + launch/disc here.
async function buildSAEXTRA() {
  const [prods, inv, pcs, inbSkus, poSkus] = await Promise.all([
    pool.query(`SELECT sku, product_name n, subcategory s, category c, market_tier ti, core_seasonal cs
                FROM planner.products WHERE NOT in_planning_scope AND sku NOT IN (${NON_SKU_LIST})`),
    pool.query(`SELECT sku, warehouse wh, available::int qty FROM planner.v_product_inventory WHERE available <> 0`),
    pool.query(`SELECT sku, co, lch, disc FROM (
                  SELECT sku, 'uk' co, coalesce(nullif(launch_date_uk_final,''), nullif(launch_date_uk,'')) lch, nullif(discontinue_date_final,'') disc FROM planner.products WHERE NOT in_planning_scope
                  UNION ALL
                  SELECT sku, 'us', nullif(launch_date_us,''), nullif(discontinue_date_final,'') FROM planner.products WHERE NOT in_planning_scope
                  UNION ALL
                  SELECT sku, 'eu', nullif(launch_date_eu,''), nullif(discontinue_date_final,'') FROM planner.products WHERE NOT in_planning_scope
                  UNION ALL
                  SELECT sku, 'au', coalesce(nullif(launch_date_au_final,''), nullif(launch_date_au,'')), nullif(discontinue_date_au_final,'') FROM planner.products WHERE NOT in_planning_scope
                  UNION ALL
                  SELECT sku, 'ca', nullif(launch_date_ca_retail,''), nullif(discontinue_date_ca,'') FROM planner.products WHERE NOT in_planning_scope
                ) x WHERE lch IS NOT NULL OR disc IS NOT NULL`),
    pool.query(`SELECT DISTINCT sku FROM planner.inbound_shipments WHERE coalesce(received_quantity,0) < quantity`),
    pool.query(`SELECT DISTINCT l.sku FROM planner.purchase_order_lines l
                  JOIN planner.purchase_orders po ON po.po = l.po
                  WHERE coalesce(l.qty,0) > 0 AND coalesce(po.status,'') NOT ILIKE '%complete%'`),
  ]);
  const signal = new Set();   // only keep out-of-scope SKUs that still have a reason to appear
  for (const r of inv.rows) signal.add(r.sku);
  for (const r of inbSkus.rows) signal.add(r.sku);
  for (const r of poSkus.rows) signal.add(r.sku);
  const p = {};
  for (const r of prods.rows) {
    if (!signal.has(r.sku)) continue;
    p[r.sku] = { n: r.n, s: r.s, c: r.c, ti: r.ti, cs: r.cs === 'Seasonal' ? 'S' : 'C',
                 csf: r.cs || '', rep: r.rep || '', av: {}, disc: {}, lch: {}, inv: {}, oo: {}, oos: true };
  }
  for (const r of inv.rows) if (p[r.sku]) p[r.sku].inv[r.wh] = r.qty;
  for (const r of pcs.rows) if (p[r.sku]) { if (r.lch) p[r.sku].lch[r.co] = r.lch; if (r.disc) p[r.sku].disc[r.co] = r.disc; }
  return p;
}

// Category metadata: {category:{a:active, g:grouping}}
async function buildCATS_META() {
  const { rows } = await pool.query(`SELECT category, is_active, grouping FROM planner.categories`);
  const o = {};
  for (const r of rows) o[r.category] = { a: r.is_active, g: r.grouping };
  return o;
}

// Subcategory metadata: {subcategory:{a:active, s:seasonal, c:category}}
async function buildSUBS_META() {
  const { rows } = await pool.query(`SELECT subcategory, is_active, is_seasonal, category FROM planner.subcategories`);
  const o = {};
  for (const r of rows) o[r.subcategory] = { a: r.is_active, s: r.is_seasonal, c: r.category };
  return o;
}

// BI free-text forecast rules (active only): [{id,subcat,countries,channels,month,year,text}]
async function buildBI_RULES() {
  const { rows } = await pool.query(
    `SELECT id, airtable_id, subcategory, countries, channels, rule_text, month, year
     FROM planner.bi_rules WHERE active ORDER BY id`);
  return rows.map(r => ({
    id: r.airtable_id || String(r.id), subcat: r.subcategory,
    countries: r.countries || ['ALL'], channels: r.channels || ['ALL'],
    month: r.month ?? null, year: r.year ?? null, text: r.rule_text,
  }));
}

// (Removed dead fn extractBaked — v26.759; unused bootstrap remnant, no callers.)
// (Removed BAKED_FM — `fm` now comes from products.fba_transfer_min_units_* in buildPROD_CONST, not a baked map.)

// PROD_CONST: per-SKU buy constants for the BUY view. {sku:{cp,moq,supp,lt,t3,tf,fm,l3}}
//   cp/moq/supp -> products; lt -> 3PL->FBA transfer weeks; l3[co] -> china_to_{co} (resolved
//   total lead time); t3[co]/tf[co] -> target cover for {co}_3pl / {co}_fba (category default,
//   per-SKU override wins); fm[co] -> baked (not in Supabase). Live so lead/cover/moq stay current.
async function buildPROD_CONST() {
  // Every buy param comes from the authoritative planner.products columns. (Was: cover re-derived from
  // category_target_cover BY CATEGORY — which fell to a default for the 101 null-category SKUs; and fm from a
  // stale baked map.) cp/moq/supp/lt/l3 as before; t3[co]/tf[co] <- target_cover_weeks_{co}_{3pl,fba} (default 4);
  // fm[co] <- fba_transfer_min_units_{co} (default 2); supp <- main_supplier_final. Some cover cells are text
  // ("15, 15") so take the first number. Verified vs live: 0 change for categorised SKUs; fixes the null-category ones.
  const { rows } = await pool.query(`SELECT sku,
      coalesce(nullif(case_pack_size,0)::int, nullif(carton_qty,'')::numeric::int) cp, moq,
      coalesce(main_supplier_final, supplier) supp,
      transfer_3pl_to_fba_lead_time_weeks lt,
      china_to_uk_lead_time_weeks l3_uk, china_to_us_lead_time_weeks l3_us, china_to_eu_lead_time_weeks l3_eu,
      china_to_au_lead_time_weeks l3_au, china_to_ca_lead_time_weeks l3_ca,
      target_cover_weeks_uk_3pl t3_uk, target_cover_weeks_us_3pl t3_us, target_cover_weeks_eu_3pl t3_eu, target_cover_weeks_au_3pl t3_au,
      target_cover_weeks_uk_fba tf_uk, target_cover_weeks_us_fba tf_us, target_cover_weeks_eu_fba tf_eu, target_cover_weeks_au_fba tf_au, target_cover_weeks_ca_fba tf_ca,
      fba_transfer_min_units_uk fm_uk, fba_transfer_min_units_us fm_us, fba_transfer_min_units_eu fm_eu, fba_transfer_min_units_au fm_au, fba_transfer_min_units_ca fm_ca
    FROM planner.products WHERE in_planning_scope AND sku NOT IN (${NON_SKU_LIST})`);
  const num1 = v => { if (v == null) return null; const m = String(v).match(/-?\d+(\.\d+)?/); return m ? Number(m[0]) : null; };
  // Supplier expedited production weeks (for Buy 3PL Urgent Air/Sea). Blank/no-supplier → default 6 weeks (Ben).
  const supEx = {}; try { (await pool.query(`SELECT name, expedited_production_weeks x FROM planner.suppliers`)).rows.forEach(r => { if (r.name != null && r.x != null) supEx[r.name] = Number(r.x); }); } catch (e) {}
  const out = {};
  for (const p of rows) {
    const t3 = {}, tf = {}, l3 = {}, fm = {};
    for (const co of ['uk', 'us', 'eu', 'au', 'ca']) {
      if (p['l3_' + co] != null) l3[co] = Math.round(Number(p['l3_' + co]));
      if (co !== 'ca') t3[co] = num1(p['t3_' + co]) ?? 4;   // no CA 3PL warehouse
      tf[co] = num1(p['tf_' + co]) ?? 4;
      fm[co] = num1(p['fm_' + co]) ?? 2;
    }
    out[p.sku] = { cp: p.cp ?? null, moq: p.moq ?? 1, supp: p.supp ?? null, lt: p.lt != null ? Number(p.lt) : 2, exped: (p.supp != null && supEx[p.supp] != null) ? supEx[p.supp] : 6, t3, tf, fm, l3 };
  }
  return out;
}
// Branch freight lead times per market (days) for Buy 3PL Urgent Air/Sea. Air ~7d everywhere; sea varies by market.
async function buildBRANCH_FREIGHT() {
  const o = {};
  try { (await pool.query(`SELECT lower(country_code) co, min(air_lead_time_days) air, min(sea_lead_time_days) sea
    FROM planner.branches WHERE country_code IS NOT NULL GROUP BY 1`)).rows.forEach(r => {
    if (['uk','us','eu','au','ca'].includes(r.co)) o[r.co] = { air: r.air != null ? Number(r.air) : 7, sea: r.sea != null ? Number(r.sea) : 42 };
  }); } catch (e) {}
  return o;
}

// Inter-market (3PL→3PL) transfer lead times (weeks) per lane, for the Rebalance / Urgent transfer classes.
// Shape: { UK:{US:6,EU:2,AU:8}, US:{UK:6,EU:6,AU:8,CA:2}, … }. A missing lane = we don't transfer that way.
async function buildTRANSFER_LEADS() {
  const o = {};
  try { (await pool.query(`SELECT upper(from_market) f, upper(to_market) t, weeks FROM planner.transfer_lead_times`)).rows
    .forEach(r => { (o[r.f] || (o[r.f] = {}))[r.t] = Number(r.weeks); }); } catch (e) {}
  return o;
}

// FBA carton dims for the FBA Transfer Upload (box L/W/H/weight per region) + units-per-box.
async function buildFBADIMS() {
  // Carton dims/weights for the FBA Transfer download. Source = planner.products (live-updated from Airtable
  // SKU_CHILD via n8n) — the source of truth. Order per unit: [length, width, height, weight]. cm / kg.
  const { rows } = await pool.query(`SELECT sku, carton_qty cp,
    uk_carton_length,uk_carton_width,uk_carton_height,uk_carton_weight,
    us_carton_length,us_carton_width,us_carton_height,us_carton_weight
    FROM planner.products WHERE coalesce(uk_carton_length, us_carton_length) IS NOT NULL AND sku NOT IN (${NON_SKU_LIST})`);
  const o = {};
  for (const r of rows) o[r.sku] = { cp: r.cp,
    u: [r.uk_carton_length, r.uk_carton_width, r.uk_carton_height, r.uk_carton_weight],
    s: [r.us_carton_length, r.us_carton_width, r.us_carton_height, r.us_carton_weight] };
  return o;
}

const app = express();
// Per-request context so any 500 catch can name its route in the logs (a swallowed error once hid a 5-day dead
// Cash Flow — the alert could only name /api/index). log500(e) reads the current req via AsyncLocalStorage, so it
// works even in helpers that don't have `req` in scope (e.g. patch()). Call log500(e) before every res.status(500).
const _reqStore = new AsyncLocalStorage();
function log500(e) { try { const s = _reqStore.getStore(); const r = s && s.req;
  console.error('[500] ' + ((r && r.method) || '?') + ' ' + ((r && (r.originalUrl || r.url)) || '?') + ' — ' + ((e && e.stack) || (e && e.message) || e)); } catch (_) { /* logging must never throw */ } }
app.use((req, res, next) => _reqStore.run({ req }, next));   // wrap every request so log500 can find it
app.use(express.json({ limit: '25mb' }));   // 25mb: document/invoice uploads arrive as base64 JSON (~33% inflation). NOTE for Diviyaj: Vercel serverless caps the request body at ~4.5MB regardless — large doc uploads need direct-to-storage (Supabase signed URL) on live; this limit only helps local/self-hosted.
// Supplier-entered money fields can arrive with thousands separators / currency symbols (e.g. "3,262.35" or
// "$1,200"). Strip everything but digits/dot/minus, then validate — returns a clean numeric string, or null if
// it isn't a number. Guarantees a stray comma never reaches a ::numeric cast (which 500'd the PO/cashflow
// queries when a supplier typed "3,262.35" for PO-55AUWK3). SQL twin: SAFE_NUM_SQL below.
function sanitiseMoney(v) { const s = String(v == null ? '' : v).replace(/[^0-9.\-]/g, ''); return /^-?[0-9]+(\.[0-9]+)?$/.test(s) ? s : null; }
// Same rule in SQL for casting a stored text value → numeric safely (garbage → NULL, never an error).
const SAFE_NUM_SQL = col => `(CASE WHEN regexp_replace(coalesce(${col},''),'[^0-9.-]','','g') ~ '^-?[0-9]+(\\.[0-9]+)?$' THEN regexp_replace(${col},'[^0-9.-]','','g')::numeric END)`;

// gzip large JSON responses (built-in zlib — no dependency). The PO grid payload is ~3.6MB of JSON;
// gzip cuts it ~10x over the wire. Only kicks in when the client accepts gzip and the body is worth it.
app.use((req, res, next) => {
  const accepts = /\bgzip\b/.test(req.headers['accept-encoding'] || '');
  const origJson = res.json.bind(res);
  res.json = (obj) => {
    let str; try { str = JSON.stringify(obj); } catch (e) { return origJson(obj); }
    if (!accepts || str.length < 1400) return origJson(obj);   // small bodies: not worth the CPU
    zlib.gzip(str, (err, buf) => {
      if (err) { res.setHeader('Content-Type', 'application/json; charset=utf-8'); return res.end(str); }
      res.setHeader('Content-Encoding', 'gzip');
      res.setHeader('Content-Type', 'application/json; charset=utf-8');
      res.setHeader('Vary', 'Accept-Encoding');
      res.end(buf);
    });
    return res;
  };
  next();
});

// Access gate — only active when PLANNER_KEY is set (production). Localhost (no env var)
// stays open and identical to what you see now. Key accepted via ?key= (stored in a cookie)
// or x-planner-key header. Anything else gets a minimal key prompt.
const GATE = process.env.PLANNER_KEY;
function cookieVal(req, name) {
  const m = (req.headers.cookie || '').match(new RegExp('(?:^|; )' + name + '=([^;]+)'));
  return m ? decodeURIComponent(m[1]) : null;
}
app.use((req, res, next) => {
  // Supplier portal has its own magic-link/session auth — it must NOT require the planner key.
  if (req.path === '/portal' || req.path === '/portal-view.js' || req.path === '/api/version' || req.path.startsWith('/api/portal/')) return next();   // /api/version: public probe (version + data ts only) for the auto-update poll, incl. the portal
  if (!GATE) return next();                       // open locally
  if (req.path.startsWith('/api/')) {             // APIs: header or cookie
    if (req.get('x-planner-key') === GATE || cookieVal(req, 'pk') === GATE) return next();
    return res.status(401).json({ error: 'unauthorised' });
  }
  const supplied = req.query.key || cookieVal(req, 'pk');
  if (supplied === GATE) {
    if (req.query.key) res.setHeader('Set-Cookie', `pk=${encodeURIComponent(GATE)}; Path=/; Max-Age=2592000; SameSite=Lax`);
    return next();
  }
  res.set('content-type', 'text/html').send(`<!doctype html><meta charset=utf8><title>Dock & Bay — Demand Planner</title><style>body{font-family:system-ui;background:#0f172a;color:#e2e8f0;display:flex;min-height:100vh;align-items:center;justify-content:center;margin:0}form{background:#1e293b;padding:36px 40px;border-radius:14px;box-shadow:0 10px 40px rgba(0,0,0,.4);text-align:center}h1{font-size:15px;letter-spacing:.18em;text-transform:uppercase;color:#94a3b8;margin:0 0 4px}h2{font-size:20px;margin:0 0 22px}input{padding:10px 12px;border-radius:8px;border:1px solid #334155;background:#0f172a;color:#fff;width:200px;text-align:center}button{margin-left:8px;padding:10px 18px;border:0;border-radius:8px;background:#2563eb;color:#fff;font-weight:600;cursor:pointer}</style><form method=get><h1>Dock &amp; Bay</h1><h2>Demand Planner</h2><input name=key type=password placeholder="Access key" autofocus><button>Enter</button></form>`);
});

// ── Edit-permission guard (access control, phase 4) ──────────────────────────────────────────────
// Blocks write requests from users lacking the relevant grant. LIVE-ONLY: with no auth-proxy email
// (sandbox/local) permsFor().live is false → every request passes, so this never bites in the sandbox.
// Reads (GET/HEAD) are always open. Never gated here: the supplier portal (/api/portal/* — its own
// magic-link auth), SCENARIO (open to all), /api/me, /api/ai, and the permissions API (self-checks admin).
const CONFIG_WRITE = [   // config reference-data writes — editable by anyone with SUPPLY *or* DEMAND edit
  /^\/api\/supply\/tax-rate\//, /^\/api\/supply\/freight-upsert$/,
  /^\/api\/supply\/freight-pallets$/, /^\/api\/supply\/air-rate\//,
  /^\/api\/supply\/duty-upsert$/, /^\/api\/supply\/branch\//, /^\/api\/supply\/supplier\//,
  /^\/api\/supply\/supplier-create$/, /^\/api\/supply\/key-account/, /^\/api\/supply\/batch\//,
  /^\/api\/supply\/batch-create$/, /^\/api\/supply\/production-create$/, /^\/api\/supply\/prod-number\//,
  /^\/api\/supply\/portal-user/, /^\/api\/supply\/manufacturing-bom-(save|delete)$/, /^\/api\/supply\/set-bom-(save|delete|upload)$/,
  /^\/api\/supply\/prepack-map-(save|delete|upload)$/,
  /^\/api\/supply\/manufacturing-accept$/, /^\/api\/supply\/manufacturing-stock$/, /^\/api\/supply\/settings$/,
];
function requiredCap(method, p) {
  if (method === 'GET' || method === 'HEAD' || method === 'OPTIONS') return null;   // reads open to all
  if (p.startsWith('/api/portal/')) return null;             // supplier portal — separate magic-link auth
  if (p.startsWith('/api/scenario/')) return null;           // SCENARIO open to all
  if (p.startsWith('/api/config/permissions')) return null;  // permissions API self-checks admin
  if (p.startsWith('/api/config/channel') || p.startsWith('/api/config/countr')) return null;  // channel registry — reads open; writes self-check admin
  if (p === '/api/me' || p === '/api/ai') return null;       // profile + AI helper (no gated DB write)
  if (p === '/api/save-forecasts' || p === '/api/save-sku-forecasts'
      || p === '/api/demand-actions/state' || p.startsWith('/api/trading-calendar')
      || p.startsWith('/api/price-changes') || p.startsWith('/api/demand-revenue-targets')
      || p.startsWith('/api/buy-complex-rules')
      || p.startsWith('/api/auto-forecast/')
      || p.startsWith('/api/forecast/')) return 'demand';    // DEMAND / forecasting domain
  if (p === '/api/consignee' || p.startsWith('/api/consignee/')) return 'config'; // CONFIG ▸ Consignees
  if (p === '/api/app-settings') return 'config';            // CONFIG ▸ General settings
  if (CONFIG_WRITE.some((re) => re.test(p))) return 'config'; // config reference data → supply OR demand
  if (p.startsWith('/api/product/')) return 'product';        // PRODUCT module writes → 'product' capability
  if (p.startsWith('/api/supply/zalando/')) return null;      // Zalando stock upload / send-file — open to all (no edit rights needed)
  if (p.startsWith('/api/supply/received-pos/')) return null; // n8n system trigger — processes the received-POs feed (acts only on rows n8n wrote)
  if (p.startsWith('/api/klaviyo-bis/')) return null;         // Klaviyo BIS upload — allowed with read-only permission (Ben)
  if (method === 'POST' && p === '/api/supply/quality-doc') return null;   // Quality Control file upload (+ its metafields) — allowed with read-only permission (Ben); delete stays gated
  if (method === 'POST' && (p === '/api/supply/cache/invalidate' || p === '/api/supply/actions/invalidate')) return null;   // clears server caches only — harmless, no data write
  if (method === 'POST' && p === '/api/data-cache/invalidate') return null;   // n8n post-ETL data-cache rebuild trigger (webhook-secret gated in the handler)
  if (p.startsWith('/api/supply/')) return 'supply';          // everything else under supply = SUPPLY feature
  return null;   // unknown non-supply write → fail-open (don't block routes we haven't classified)
}
app.use(async (req, res, next) => {
  try {
    const cap = requiredCap(req.method, req.path);
    if (!cap) return next();
    const me = await permsFor(req);
    if (!me.live) return next();   // sandbox / no auth proxy → full access
    const ok = cap === 'demand' ? (me.demand_edit || me.is_admin)
             : cap === 'supply' ? (me.supply_edit || me.is_admin)
             : cap === 'product' ? (me.product_edit || me.is_admin)
             : cap === 'config' ? (me.supply_edit || me.demand_edit || me.is_admin) : true;   // admins always have edit rights (was missing for demand/supply/config → false "Read-only" on auto-smooth etc.)
    if (ok) return next();
    const label = cap === 'demand' ? 'DEMAND' : cap === 'config' ? 'CONFIG' : cap === 'product' ? 'PRODUCT' : 'SUPPLY';
    return res.status(403).json({ error: 'Read-only access — you don’t have ' + label + ' edit rights. Ask an admin (CONFIG ▸ Permissions).', code: 'readonly', cap });
  } catch (e) { return next(); }   // the guard must never break a request itself
});
// After any supplier-portal WRITE, drop the cached portal bootstraps so the supplier's next load reflects their edit
// (tracking, notes, completion, invoice, cost submit…). Cheap — the map holds one entry per active supplier set.
app.use((req, res, next) => {
  if (req.method === 'POST' && req.path.startsWith('/api/portal/')) {
    res.on('finish', () => { try { if (res.statusCode < 400) { _portalCache.clear(); _portalInflight.clear(); } } catch (e) { /* ignore */ } });
  }
  next();
});

// Short-TTL cache of the built data globals. The build (~12 Supabase queries) is ~85% of a page serve (~870ms);
// it reruns on every load. The source data is ETL-fed (frozen for an open tab anyway), so caching the built
// values for a few seconds coalesces bursts (refresh, multiple tabs, the auto-update reload) → repeat loads skip
// the build. We cache DATA only, NOT the HTML, so DEV live-editing still works (the file is re-read + re-injected
// each request). Invalidated on forecast saves so an edit shows on the next load.
let _dataCache = null, _dataRefresh = null, _bgRefreshing = false;
const DATA_TTL_MS = 600000;   // 10 min — with KV + n8n-triggered invalidation this is just a staleness heartbeat, not the primary refresh.
// ── Shared cross-instance data cache (Vercel KV / Upstash REST) ───────────────────────────────────────────────
// FEATURE-FLAGGED: active only when KV_REST_API_URL + KV_REST_API_TOKEN are set (Vercel prod). When absent (sandbox/
// local) every path falls back to the in-process cache — behaviour identical to before. On Vercel the ~12MB build
// pulled from Supabase is the biggest egress+CPU source and re-runs on every serverless cold start; storing the built
// blob in KV lets cold starts read it from KV (not Supabase), so the Supabase build runs only when data actually
// changes (n8n upload via POST /api/data-cache/invalidate, or a forecast edit). Blob is gzip+base64 + chunked to dodge value limits.
const KV_URL = (process.env.KV_REST_API_URL || '').replace(/\/$/, ''), KV_TOKEN = process.env.KV_REST_API_TOKEN || '';
const KV_ON = !!(KV_URL && KV_TOKEN);
const KV_KEY = 'horizon:data', KV_CHUNK = 900000;   // ~900KB base64 chunks (safely under the ~1MB REST value limit)
async function kvCmd(cmd) {   // Upstash REST: POST base URL with a JSON command array → { result }
  const r = await fetch(KV_URL, { method: 'POST', headers: { Authorization: 'Bearer ' + KV_TOKEN, 'Content-Type': 'application/json' }, body: JSON.stringify(cmd) });
  if (!r.ok) throw new Error('KV ' + r.status);
  return (await r.json()).result;
}
async function kvWriteBlob(vals) {   // store the built 14-tuple as gzip+base64 chunks + a meta record
  const b64 = zlib.gzipSync(Buffer.from(JSON.stringify(vals))).toString('base64');
  const n = Math.ceil(b64.length / KV_CHUNK);
  for (let i = 0; i < n; i++) await kvCmd(['SET', KV_KEY + ':' + i, b64.slice(i * KV_CHUNK, (i + 1) * KV_CHUNK)]);
  await kvCmd(['SET', KV_KEY + ':meta', JSON.stringify({ n, at: Date.now(), len: b64.length })]);
}
async function kvReadBlob() {   // reassemble the blob from KV; null on miss/corruption (caller falls back to Supabase)
  const meta = await kvCmd(['GET', KV_KEY + ':meta']); if (!meta) return null;
  const m = JSON.parse(meta); let b64 = '';
  for (let i = 0; i < m.n; i++) { const c = await kvCmd(['GET', KV_KEY + ':' + i]); if (c == null) return null; b64 += c; }
  let vals; try { vals = JSON.parse(zlib.gunzipSync(Buffer.from(b64, 'base64')).toString()); } catch (e) { return null; }
  return (Array.isArray(vals) && vals.length >= 14) ? vals : null;   // sanity-check shape before trusting it
}
// Build all live data globals (~12-14 Supabase queries) in parallel. Cold this is ~26s on the remote sandbox, so
// we serve the cached build and refresh it in the BACKGROUND when it goes stale (stale-while-revalidate): after
// the boot warm below, a real request never blocks on a cold build. A forecast save nulls _dataCache (lines
// ~768/806) so the very next load rebuilds synchronously — edits show immediately.
// GBP average selling price per subcategory × market, from SKU retail prices (<co>_rt, held in local currency)
// converted to GBP via fx_rates (local-per-GBP). Feeds new-category target smoothing (revenue ÷ ASP → units) where
// there's no sales history to derive an ASP from. A market with no priced SKU is omitted (→ no units for that market).
async function buildCatAspGBP() {
  let fx = {}; try { const fr = (await pool.query(`SELECT value FROM planner.app_settings WHERE key='fx_rates'`)).rows[0];
    const o = fr && fr.value ? JSON.parse(fr.value) : {}; const ys = Object.keys(o).sort(); fx = o[ys[ys.length - 1]] || {}; } catch (e) {}
  const rate = { UK: 1, US: fx.USD || 1.34, EU: fx.EUR || 1.15, AU: fx.AUD || 1.9, CA: fx.CAD || 1.85 };   // local per GBP
  const col = { UK: 'uk_rt', US: 'us_rt', EU: 'eu_rt', AU: 'au_rt', CA: 'ca_rt' };
  const rows = (await pool.query(`SELECT subcategory s, uk_rt, us_rt, eu_rt, au_rt, ca_rt
    FROM planner.products WHERE in_planning_scope AND subcategory IS NOT NULL`)).rows;
  const acc = {};   // subcat -> {mkt:[sumLocal,n]}
  for (const r of rows) { const s = r.s; if (!acc[s]) acc[s] = { UK: [0, 0], US: [0, 0], EU: [0, 0], AU: [0, 0], CA: [0, 0] };
    for (const m in col) { const v = parseFloat(r[col[m]]); if (v > 0) { acc[s][m][0] += v; acc[s][m][1]++; } } }
  const out = {};
  for (const s in acc) { out[s] = {}; for (const m in col) { const a = acc[s][m]; if (a[1] > 0) out[s][m] = Math.round((a[0] / a[1]) / (rate[m] || 1) * 100) / 100; } }
  return out;
}
// #4 locked-forecast-vs-actual — for each COMPLETED past month, the SKU-level forecast from the most recent snapshot
// (planner.forecast_runs + forecasts, level='sku') taken BEFORE that month started. Shown small in the actuals cell
// (subcategory + SKU) so a completed month's actual can be compared to what we had locked heading into it. Empty until
// monthly snapshots accrue (the KPIs "Take forecast snapshot" button / the n8n 14th-of-month job). Keyed to match the
// client plan cells: sub → "SUBCAT|CO|CH|YYYY_MM", sku → "SKU|CO|CH|YYYY_MM".
async function buildLockedFc() {
  const out = { sub: {}, sku: {} };
  try {
    const rows = (await pool.query(`
      WITH completed AS (
        SELECT DISTINCT month FROM planner.forecasts
        WHERE level='sku' AND month < date_trunc('month', current_date)),
      pick AS (   -- for each completed month, the most recent run taken strictly before that month started
        SELECT c.month, (
          SELECT r.id FROM planner.forecast_runs r
          WHERE r.run_at < date_trunc('month', c.month)
            AND EXISTS (SELECT 1 FROM planner.forecasts f2 WHERE f2.run_id=r.id AND f2.level='sku' AND f2.month=c.month)
          ORDER BY r.run_at DESC LIMIT 1) run_id
        FROM completed c)
      SELECT to_char(f.month,'YYYY_MM') ym, upper(f.country) co, f.channel ch, f.subcategory sub, f.sku,
             sum(f.units)::int units
      FROM planner.forecasts f JOIN pick p ON p.run_id=f.run_id AND f.month=p.month
      WHERE f.level='sku' AND p.run_id IS NOT NULL
      GROUP BY 1,2,3,4,5`)).rows;
    for (const r of rows) {
      const suff = '|' + r.co + '|' + r.ch + '|' + r.ym;
      out.sku[r.sku + suff] = r.units;
      const sk = r.sub + suff; out.sub[sk] = (out.sub[sk] || 0) + r.units;
    }
  } catch (e) { /* forecast_runs/forecasts may be absent in some envs → leave empty */ }
  return out;
}
async function _buildDataVals() {
  return Promise.all([
    buildDATA(), buildFC_CURRENT(), buildFC_OUTPUTS(), buildSKURAW(),
    buildCATS_META(), buildSUBS_META(), buildBI_RULES(), buildPROD_CONST(), freshness(), buildFBADIMS(), buildSAEXTRA(), gbpRate(), buildBRANCH_FREIGHT(), buildTRANSFER_LEADS(), buildCatAspGBP(), buildLockedFc(),
  ]);
}
function refreshDataCache() {   // AUTHORITATIVE rebuild from Supabase (single-flight) + push to KV so other instances pick it up
  if (_dataRefresh) return _dataRefresh;
  _dataRefresh = _buildDataVals()
    .then(async (vals) => { _dataCache = { at: Date.now(), vals }; _dataRefresh = null;
      if (KV_ON) { try { await kvWriteBlob(vals); } catch (e) { console.error('[kv] write failed:', e.message); } } return vals; })
    .catch((e) => { _dataRefresh = null; throw e; });
  return _dataRefresh;
}
// Background staleness refresh (fire-and-forget). With KV: re-read the blob from KV (cheap, off-Supabase) to pick up a
// blob another instance rebuilt on invalidate. Without KV: rebuild from Supabase (identical to the old behaviour).
function bgRefresh() {
  if (_bgRefreshing || _dataRefresh) return;
  if (!KV_ON) { refreshDataCache().catch(() => {}); return; }
  _bgRefreshing = true;
  kvReadBlob().then((v) => { if (v) _dataCache = { at: Date.now(), vals: v }; }).catch(() => {}).finally(() => { _bgRefreshing = false; });
}
// The accessor every serve path uses. In-process first; on a cold start, prefer KV (no Supabase); else build once.
async function getDataVals() {
  if (_dataCache) { if (Date.now() - _dataCache.at >= DATA_TTL_MS) bgRefresh(); return _dataCache.vals; }
  if (KV_ON) { try { const v = await kvReadBlob(); if (v) { _dataCache = { at: Date.now(), vals: v }; return v; } } catch (e) { console.error('[kv] read failed:', e.message); } }
  return await refreshDataCache();   // KV miss / not configured → authoritative Supabase build (also writes KV)
}
// Called on data change (n8n upload endpoint + forecast edits): drop the local copy and rebuild+repush to KV in the
// background so every instance converges. Fire-and-forget so a forecast save isn't blocked on the ~12MB rebuild.
function invalidateDataCache() { _dataCache = null; refreshDataCache().catch((e) => console.error('[cache] rebuild failed:', e.message)); }
// Boot warm: on Vercel read the pre-built blob from KV (no Supabase); only build from Supabase if KV is empty/off.
(async () => { try { if (KV_ON) { const v = await kvReadBlob(); if (v) { _dataCache = { at: Date.now(), vals: v }; return; } } await refreshDataCache(); } catch (e) { /* first real request will retry */ } })();
// DEMAND ▸ Trends ▸ Panel 3 (Plan sanity). Compares next-year forecast_outputs against the like-for-like 2024-26
// actual band per category × market, then runs the rule set (R1 over-plan, R2 under-plan, R3 step change, R6 zero
// plan on live range; "no plan" ≠ "plan is low"). Units only, read-only. Cutoff = last complete month (current partial
// excluded). Plan window = same Jan-to-cutoff months, next year. forecast_outputs warehouse prefix → market.
const _TRENDS_CFG = { r1: 1.5, r2: 0.7, r3lo: 0.5, r3hi: 2.0 };   // thresholds (tunable after a cycle)
const _TRENDS_TTL = 10 * 60 * 1000;   // 10-minute server cache (data changes at most daily via n8n); busted by ?refresh=1
const _trendsCache = new Map();       // key -> { at, data }
let _trMeta = null, _trMetaAt = 0;    // cached cutoff/plan-year (avoids a max(month) round-trip per request)
async function _trendsMeta() {
  if (_trMeta && Date.now() - _trMetaAt < _TRENDS_TTL) return _trMeta;
  const cut = (await pool.query(`SELECT extract(month from max(month))::int mm, extract(year from max(month))::int yy FROM planner.sales_actuals`)).rows[0];
  _trMeta = { cutoffNum: Math.max(1, (cut.mm || 1) - 1), planYear: (cut.yy || 2026) + 1 }; _trMetaAt = Date.now();
  return _trMeta;
}
async function _trendsCached(key, refresh, build) {
  const now = Date.now(), hit = _trendsCache.get(key);
  if (!refresh && hit && (now - hit.at) < _TRENDS_TTL) return hit.data;
  const data = await build(); _trendsCache.set(key, { at: now, data }); return data;
}
// Shared Trends query params: from/to month range (clamped to [1, cutoff]; like-for-like across years) + grain
// (category | subcategory). catExpr = the parent category (always returned, for group/active filtering); lblExpr = the
// row label (subcategory when drilling down). Null category/subcategory → 'Unmapped'.
function _trendsWin(req, cutoffNum) {
  const cl = (v, d) => { const n = parseInt(v, 10); return (Number.isFinite(n) && n >= 1 && n <= 12) ? Math.min(n, cutoffNum) : d; };
  let from = cl(req.query.from, 1), to = cl(req.query.to, cutoffNum);
  if (from > to) { const t = from; from = to; to = t; }
  const grain = (req.query.grain === 'subcategory') ? 'subcategory' : 'category';
  const catExpr = `coalesce(nullif(btrim(p.category),''),'Unmapped')`;
  const lblExpr = grain === 'subcategory' ? `coalesce(nullif(btrim(p.subcategory),''),'Unmapped')` : catExpr;
  return { from, to, grain, catExpr, lblExpr };
}
app.get('/api/demand/trends/plan-sanity', async (req, res) => {
  try {
    const { cutoffNum, planYear } = await _trendsMeta();
    const W = _trendsWin(req, cutoffNum);
    const out = await _trendsCached('ps|' + W.grain + '|' + W.from + '|' + W.to, req.query.refresh === '1', async () => {
    const SEP = String.fromCharCode(31);
    const [actR, planR, priorR, availR] = await Promise.all([
      pool.query(`SELECT ${W.catExpr} category, ${W.lblExpr} label, sa.country market, extract(year from sa.month)::int yr, sum(sa.units)::numeric units
        FROM planner.sales_actuals sa JOIN planner.products p ON p.sku=sa.sku
        WHERE extract(month from sa.month) BETWEEN $1 AND $2 AND extract(year from sa.month) BETWEEN 2024 AND 2026 GROUP BY 1,2,3,4`, [W.from, W.to]),
      pool.query(`SELECT ${W.catExpr} category, ${W.lblExpr} label, upper(split_part(fo.warehouse,'_',1)) market, sum(fo.units)::numeric units
        FROM planner.forecast_outputs fo JOIN planner.products p ON p.sku=fo.sku
        WHERE extract(month from fo.month) BETWEEN $1 AND $2 AND extract(year from fo.month) = $3 GROUP BY 1,2,3`, [W.from, W.to, planYear]),
      pool.query(`SELECT ${W.catExpr} category, ${W.lblExpr} label, upper(split_part(fo.warehouse,'_',1)) market, sum(fo.units)::numeric units
        FROM planner.forecast_outputs fo JOIN planner.products p ON p.sku=fo.sku
        WHERE extract(month from fo.month) BETWEEN $1 AND $2 AND extract(year from fo.month) = $3 GROUP BY 1,2,3`, [W.from, W.to, planYear - 1]),   // prior-year plan → R5
      pool.query(`SELECT DISTINCT ${W.lblExpr} label, v.country market FROM planner.products p JOIN planner.v_product_availability v ON v.sku=p.sku WHERE v.is_available`),   // live label×market → R4
    ]);
    const band = {}, plan = {}, prior = {}, meta = {};
    for (const r of actR.rows) { const k = [r.category, r.label, r.market].join(SEP); (band[k] = band[k] || {})[r.yr] = Number(r.units) || 0; meta[k] = { category: r.category, label: r.label, market: r.market }; }
    for (const r of planR.rows) { const k = [r.category, r.label, r.market].join(SEP); plan[k] = Number(r.units) || 0; meta[k] = meta[k] || { category: r.category, label: r.label, market: r.market }; }
    for (const r of priorR.rows) prior[[r.category, r.label, r.market].join(SEP)] = Number(r.units) || 0;
    const availSet = new Set(availR.rows.map(r => r.label + SEP + r.market));
    const C = _TRENDS_CFG, rows = [];
    for (const k of new Set([...Object.keys(band), ...Object.keys(plan)])) {
      const m = meta[k], category = m.category, label = m.label, market = m.market;
      const b = band[k] || {}, a24 = b[2024] || 0, a25 = b[2025] || 0, a26 = b[2026] || 0;
      const latest = a26, bandLow = Math.min(a24, a25, a26), bandHigh = Math.max(a24, a25, a26);
      const hasPlan = (k in plan), pl = plan[k] || 0, rules = []; let status = 'OK';
      if (!hasPlan) { if (latest <= 0) continue; rules.push('R6'); status = 'No plan'; }
      else {
        if (bandHigh > 0 && pl > C.r1 * bandHigh) rules.push('R1');
        if (latest > 0 && pl < C.r2 * latest) rules.push('R2');
        if (latest > 0) { const ratio = pl / latest; if (ratio < C.r3lo || ratio > C.r3hi) rules.push('R3'); }
        if (pl > 0 && !availSet.has(label + SEP + market)) rules.push('R4');   // dead range: plan units but no live SKUs in this market
        const pp = prior[k]; if (pl > 0 && pp != null && pp > 0 && Math.round(pp) === Math.round(pl)) rules.push('R5');   // stale copy: identical to the prior-year plan
        if (pl === 0 && latest > 0) rules.push('R6');
        const hard = rules.some(x => x === 'R3' || x === 'R4' || x === 'R5');
        status = hard ? 'Blocked' : (rules.length ? 'Review' : 'OK');
      }
      rows.push({ category, label, market, plan: pl, hasPlan, a2024: a24, a2025: a25, a2026: a26, latest, bandLow, bandHigh, planVsLatest: latest > 0 ? pl / latest : null, rules, status });
    }
    rows.sort((x, y) => { const o = { Blocked: 0, 'No plan': 1, Review: 2, OK: 3 }; return (o[x.status] - o[y.status]) || (y.plan - x.plan); });
    return { cutoffMonth: cutoffNum, planYear, from: W.from, to: W.to, grain: W.grain, cfg: C, rows };
    });
    res.json(out);
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// DEMAND ▸ Trends ▸ Panel 2 (Multi-year trend). Per category × market, Jan-to-cutoff for 2024/25/26. Headline =
// gap-to-peak (not YoY). Trend class + plan_next (2027). Suspect-month heuristic (units <40% trailing-3mo avg AND
// >30% of the usual SKUs recorded zero) marks likely stockouts and EXCLUDES them, like-for-like, from the growth rates.
app.get('/api/demand/trends/multi-year', async (req, res) => {
  try {
    const { cutoffNum, planYear } = await _trendsMeta();
    const W = _trendsWin(req, cutoffNum);
    const out = await _trendsCached('my|' + W.grain + '|' + W.from + '|' + W.to, req.query.refresh === '1', async () => {
    const [mR, planR] = await Promise.all([
      pool.query(`SELECT ${W.catExpr} category, ${W.lblExpr} label, sa.country market, extract(year from sa.month)::int yr, extract(month from sa.month)::int mo,
          sum(sa.units)::numeric units, count(DISTINCT sa.sku) FILTER (WHERE sa.units>0) active
        FROM planner.sales_actuals sa JOIN planner.products p ON p.sku=sa.sku
        WHERE extract(month from sa.month) BETWEEN $1 AND $2 AND extract(year from sa.month) BETWEEN 2024 AND 2026 GROUP BY 1,2,3,4,5`, [W.from, W.to]),
      pool.query(`SELECT ${W.catExpr} category, ${W.lblExpr} label, upper(split_part(fo.warehouse,'_',1)) market, sum(fo.units)::numeric units
        FROM planner.forecast_outputs fo JOIN planner.products p ON p.sku=fo.sku
        WHERE extract(month from fo.month) BETWEEN $1 AND $2 AND extract(year from fo.month) = $3 GROUP BY 1,2,3`, [W.from, W.to, planYear]),
    ]);
    const M = {}, plan = {}, meta = {};
    for (const r of mR.rows) { const k = [r.category, r.label, r.market].join(String.fromCharCode(31)); (M[k] = M[k] || {}); (M[k][r.yr] = M[k][r.yr] || {}); M[k][r.yr][r.mo] = { u: Number(r.units) || 0, a: Number(r.active) || 0 }; meta[k] = { category: r.category, label: r.label, market: r.market }; }
    for (const r of planR.rows) plan[[r.category, r.label, r.market].join(String.fromCharCode(31))] = Number(r.units) || 0;
    const rows = [];
    for (const k of Object.keys(M)) {
      const mt = meta[k], category = mt.category, label = mt.label, market = mt.market, mm = M[k];
      const yrTot = (y) => { let t = 0; const o = mm[y] || {}; for (let m = W.from; m <= W.to; m++) t += (o[m] && o[m].u) || 0; return t; };
      const a24 = yrTot(2024), a25 = yrTot(2025), a26 = yrTot(2026);
      let maxActive = 0; for (const y of Object.keys(mm)) for (const m of Object.keys(mm[y])) maxActive = Math.max(maxActive, mm[y][m].a);
      const suspect = [], o26 = mm[2026] || {};
      for (let m = W.from; m <= W.to; m++) {
        const cur = (o26[m] && o26[m].u) || 0, act = (o26[m] && o26[m].a) || 0, tv = [];
        for (let d = 1; d <= 3; d++) { let ym = m - d, yy = 2026; if (ym < 1) { ym += 12; yy = 2025; } const src = mm[yy] && mm[yy][ym]; if (src) tv.push(src.u); }
        const tavg = tv.length ? tv.reduce((a, b) => a + b, 0) / tv.length : 0, zeroPct = maxActive > 0 ? (1 - act / maxActive) : 0;
        if (tavg > 0 && cur < 0.4 * tavg && zeroPct > 0.3) suspect.push(m);
      }
      const sus = new Set(suspect), adj = (y) => { let t = 0; const o = mm[y] || {}; for (let m = W.from; m <= W.to; m++) { if (sus.has(m)) continue; t += (o[m] && o[m].u) || 0; } return t; };
      const j = { 2024: adj(2024), 2025: adj(2025), 2026: adj(2026) };
      const peakYear = [2024, 2025, 2026].reduce((p, y) => j[y] > j[p] ? y : p, 2024), peakVal = j[peakYear];
      const yoy = j[2025] > 0 ? (j[2026] / j[2025] - 1) : null, gapToPeak = peakVal > 0 ? (j[2026] / peakVal - 1) : null;
      const pl = (k in plan) ? plan[k] : null, planVsPeak = (pl != null && peakVal > 0) ? (pl / peakVal - 1) : null;
      let cls; if (peakVal > 0 && j[2026] < 0.25 * peakVal) cls = 'Collapsed'; else if (peakYear === 2026) cls = 'New high';
      else if (j[2024] > j[2025] && j[2025] > j[2026]) cls = 'Two-season fall'; else if (j[2026] < j[2025]) cls = 'Declining';
      else if (j[2026] > j[2025] && j[2026] < peakVal) cls = 'Recovering'; else cls = 'Recovering';
      // Seasonal shape (expand-row): monthly units by year over the window + the peak month per year (has it moved?).
      const monthly = {}, peakMonth = {};
      for (const y of [2024, 2025, 2026]) { const arr = []; let pm = 0, pv = -1; for (let mo = W.from; mo <= W.to; mo++) { const u = (mm[y] && mm[y][mo] && mm[y][mo].u) || 0; arr.push(Math.round(u)); if (u > pv) { pv = u; pm = mo; } } monthly[y] = arr; peakMonth[y] = arr.length ? pm : null; }
      const pkShare = j[2026] > 0 ? Math.round((Math.max.apply(null, monthly[2026]) / j[2026]) * 100) / 100 : null;
      rows.push({ category, label, market, a2024: a24, a2025: a25, a2026: a26, peakYear, yoy, gapToPeak, planNext: pl, planVsPeak, cls, suspectMonths: suspect, suspectCount: suspect.length, monthly, peakMonth, peakShare: pkShare, from: W.from, to: W.to });
    }
    rows.sort((x, y) => { const gx = x.gapToPeak == null ? 99 : x.gapToPeak, gy = y.gapToPeak == null ? 99 : y.gapToPeak; return gx - gy; });
    return { cutoffMonth: cutoffNum, planYear, from: W.from, to: W.to, grain: W.grain, rows };
    });
    res.json(out);
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// DEMAND ▸ Trends ▸ Panel 1 (Channel mix). House benchmark per market = total FBA / (DTC+FBA), rolling 12 months to
// cutoff (B2B excluded). Per category: FBA share, gap vs benchmark, headroom units. Stockout confound computed at
// SKU-month grain: pct_sku_months_no_fba = share of SKU-months where a SKU sold DTC but recorded zero FBA (then a read).
app.get('/api/demand/trends/channel-mix', async (req, res) => {
  try {
    const W = _trendsWin(req, 12);   // channel mix is rolling-12; only the grain (category|subcategory) applies here
    const out = await _trendsCached('cm|' + W.grain, req.query.refresh === '1', async () => {
    const r = await pool.query(`
      WITH bounds AS ( SELECT (max(month) - interval '1 month')::date cutoff FROM planner.sales_actuals ),
      win AS ( SELECT cutoff, (cutoff - interval '11 months')::date start FROM bounds ),
      sm AS (
        SELECT ${W.catExpr} category, ${W.lblExpr} label, sa.country market, sa.sku, sa.month,
          sum(sa.units) FILTER (WHERE sa.channel='DTC') dtc, sum(sa.units) FILTER (WHERE sa.channel='FBA') fba
        FROM planner.sales_actuals sa JOIN planner.products p ON p.sku=sa.sku CROSS JOIN win
        WHERE sa.month >= win.start AND sa.month <= win.cutoff GROUP BY 1,2,3,4,5 )
      SELECT category, label, market, sum(coalesce(dtc,0))::numeric dtc_units, sum(coalesce(fba,0))::numeric fba_units,
        count(*) FILTER (WHERE coalesce(dtc,0)>0) dtc_skumonths,
        count(*) FILTER (WHERE coalesce(dtc,0)>0 AND coalesce(fba,0)=0) nofba_skumonths
      FROM sm GROUP BY 1,2,3`);
    const perMkt = {};
    for (const x of r.rows) { const m = x.market; (perMkt[m] = perMkt[m] || { dtc: 0, fba: 0 }); perMkt[m].dtc += Number(x.dtc_units) || 0; perMkt[m].fba += Number(x.fba_units) || 0; }
    const bench = {}; for (const m of Object.keys(perMkt)) { const d = perMkt[m].dtc, f = perMkt[m].fba; bench[m] = (d + f) > 0 ? f / (d + f) : 0; }
    const rows = [];
    for (const x of r.rows) {
      const dtc = Number(x.dtc_units) || 0, fba = Number(x.fba_units) || 0, b = bench[x.market] || 0;
      const share = (dtc + fba) > 0 ? fba / (dtc + fba) : 0, gapPp = share - b;
      const headroom = (b < 1) ? Math.max(0, dtc * b / (1 - b) - fba) : 0;
      const dm = Number(x.dtc_skumonths) || 0, nf = Number(x.nofba_skumonths) || 0, coverage = dm > 0 ? nf / dm : null;
      let read; if (gapPp < 0) { read = (coverage != null && coverage > 0.25) ? 'Stocking gap' : (coverage != null && coverage < 0.15) ? 'Demand gap' : 'Investigate'; } else read = 'Over-indexed';
      rows.push({ category: x.category, label: x.label, market: x.market, dtc, fba, fbaShare: share, benchmark: b, gapPp, coverage, headroom, read });
    }
    rows.sort((a, c) => c.headroom - a.headroom);
    return { benchmark: bench, grain: W.grain, rows };
    });
    res.json(out);
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// DEMAND ▸ Trends ▸ Type mix. Share of DTC+FBA sales that are SETS vs MASTER (products.variant_type), per category ×
// market, rolling 12 months — compared across markets. setPct = SET / (SET + MASTER). Read-only.
app.get('/api/demand/trends/type-mix', async (req, res) => {
  try {
    const W = _trendsWin(req, 12);
    const out = await _trendsCached('tm|' + W.grain, req.query.refresh === '1', async () => {
      const r = await pool.query(`
        WITH bounds AS ( SELECT (max(month) - interval '1 month')::date cutoff FROM planner.sales_actuals ),
        win AS ( SELECT cutoff, (cutoff - interval '11 months')::date start FROM bounds )
        SELECT ${W.catExpr} category, ${W.lblExpr} label, sa.country market,
          sum(sa.units) FILTER (WHERE p.variant_type='SET' AND sa.channel='DTC')::numeric dtc_set,
          sum(sa.units) FILTER (WHERE p.variant_type='MASTER' AND sa.channel='DTC')::numeric dtc_master,
          sum(sa.units) FILTER (WHERE sa.channel='DTC')::numeric dtc_total,
          sum(sa.units) FILTER (WHERE p.variant_type='SET' AND sa.channel='FBA')::numeric fba_set,
          sum(sa.units) FILTER (WHERE p.variant_type='MASTER' AND sa.channel='FBA')::numeric fba_master,
          sum(sa.units) FILTER (WHERE sa.channel='FBA')::numeric fba_total,
          sum(sa.units)::numeric total_units
        FROM planner.sales_actuals sa JOIN planner.products p ON p.sku=sa.sku CROSS JOIN win
        WHERE sa.channel IN ('DTC','FBA') AND sa.month >= win.start AND sa.month <= win.cutoff GROUP BY 1,2,3`);
      const rows = r.rows.map(x => {
        const ds = Number(x.dtc_set) || 0, dm = Number(x.dtc_master) || 0, dsm = ds + dm;
        const fs = Number(x.fba_set) || 0, fm = Number(x.fba_master) || 0, fsm = fs + fm;
        return { category: x.category, label: x.label, market: x.market, total: Number(x.total_units) || 0,
          dtcSet: ds, dtcMaster: dm, dtcTotal: Number(x.dtc_total) || 0, dtcSetPct: dsm > 0 ? ds / dsm : null,
          fbaSet: fs, fbaMaster: fm, fbaTotal: Number(x.fba_total) || 0, fbaSetPct: fsm > 0 ? fs / fsm : null }; });
      return { grain: W.grain, rows };
    });
    res.json(out);
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
