// ── DEMAND ▸ Analysis ▸ Stock cover — weeks-of-cover per warehouse per month from the monthly inventory snapshots ──
// SOH value (cost-weighted, end-of-month = latest snapshot in the month) ÷ weekly demand value (trailing-3-mo actual
// sales, cost-weighted). The client maps each warehouse to the sales channels it fulfils and shows the 18-month trend
// vs an editable target (weeks). Value(£)-weighted so it ties to working capital / cash flow. Report-only.
app.get('/api/demand/stock-cover', async (_req, res) => {
  try {
    const soh = (await pool.query(`
      WITH latest AS (
        SELECT DISTINCT ON (warehouse, sku, date_trunc('month', snapshot_date))
          warehouse, sku, date_trunc('month', snapshot_date) mon, available
        FROM planner.inventory_snapshots
        ORDER BY warehouse, sku, date_trunc('month', snapshot_date), snapshot_date DESC)
      SELECT l.warehouse wh, to_char(l.mon, 'YYYY-MM') ym,
             round(sum(l.available * coalesce(p.cost, 0))::numeric, 2) soh_val,
             round(sum(l.available * coalesce(p.cost, 0)) FILTER (WHERE
               (CASE upper(split_part(l.warehouse,'_',1)) WHEN 'AU' THEN p.discontinue_date_au_final WHEN 'CA' THEN p.discontinue_date_ca ELSE p.discontinue_date_final END) ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}'
               AND (CASE upper(split_part(l.warehouse,'_',1)) WHEN 'AU' THEN p.discontinue_date_au_final WHEN 'CA' THEN p.discontinue_date_ca ELSE p.discontinue_date_final END)::date < (l.mon - interval '4 months')
             )::numeric, 2) disc_val
      FROM latest l JOIN planner.products p ON p.sku = l.sku
      GROUP BY 1, 2`)).rows;
    const dem = (await pool.query(`
      SELECT upper(sa.country) co, sa.channel ch, to_char(sa.month, 'YYYY-MM') ym,
             round(sum(sa.units * coalesce(p.cost, 0))::numeric, 2) dem_val
      FROM planner.sales_actuals sa JOIN planner.products p ON p.sku = sa.sku
      GROUP BY 1, 2, 3`)).rows;
    let target = 12; try { const r = (await pool.query(`SELECT value FROM planner.app_settings WHERE key='stock_cover_target_wks'`)).rows[0]; if (r && Number(r.value) > 0) target = Number(r.value); } catch (e) {}
    res.json({ soh, dem, target });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
app.post('/api/demand/stock-cover/target', async (req, res) => {
  const v = Number((req.body || {}).target); if (!(v > 0)) return res.status(400).json({ error: 'target must be > 0' });
  try { await pool.query(`INSERT INTO planner.app_settings(key, value) VALUES('stock_cover_target_wks',$1)
    ON CONFLICT (key) DO UPDATE SET value=excluded.value`, [String(v)]); res.json({ ok: true, target: v }); }
  catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// ── DEMAND ▸ Inputs ▸ Backtest — upload a Cin7 stock-valuation export as a dated inventory snapshot ──
// Body: { snapshot_date:'YYYY-MM-DD', filename, data_base64 }. Parses Branch/Category/Code/SOH, maps branch→warehouse
// (same _INV_BRANCH_MAP as production), aggregates per (warehouse,sku), upserts into inventory_snapshots.
app.post('/api/demand/inventory-upload', async (req, res) => {
  try {
    const b = req.body || {};
    const date = String(b.snapshot_date || '').slice(0, 10);
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return res.status(400).json({ error: 'snapshot_date (YYYY-MM-DD) required' });
    if (!b.data_base64) return res.status(400).json({ error: 'data_base64 (the Cin7 export) required' });
    const buf = Buffer.from(String(b.data_base64).replace(/^data:[^;]+;base64,/, ''), 'base64');
    const isCsv = /\.csv$/i.test(b.filename || '') || /csv/i.test(b.content_type || '');
    const raw = [];
    if (isCsv) {
      const lines = buf.toString('utf8').replace(/^﻿/, '').split(/\r?\n/).filter(l => l.trim());
      for (let i = 1; i < lines.length; i++) { const c = lines[i].split(','); raw.push([c[0], c[1], c[2], c[3]]); }
    } else {
      const ExcelJS = (await import('exceljs')).default; const wb = new ExcelJS.Workbook(); await wb.xlsx.load(buf);
      const ws = wb.worksheets[0]; if (!ws) return res.status(400).json({ error: 'empty workbook' });
      ws.eachRow({ includeEmpty: false }, (r, rn) => { if (rn === 1) return; const g = i => { const v = r.getCell(i).value; return (v && v.text) ? v.text : v; }; raw.push([g(1), g(2), g(3), g(4)]); });
    }
    const agg = {}, skipped = {};
    for (const r of raw) {
      let br = r[0], sku = r[2], q = Number(r[3]);
      if (br == null || sku == null || !Number.isFinite(q)) continue;
      br = String(br).trim(); sku = String(sku).trim();
      if (br === 'Grand Total' || sku === '' || sku === 'Grand Total') continue;
      const wh = _INV_BRANCH_MAP[br];
      if (wh === undefined) { skipped['unmapped: ' + br] = (skipped['unmapped: ' + br] || 0) + 1; continue; }
      if (wh === null) { skipped['excluded: ' + br] = (skipped['excluded: ' + br] || 0) + 1; continue; }
      const k = wh + '\t' + sku; agg[k] = (agg[k] || 0) + q;
    }
    const keys = Object.keys(agg);
    if (!keys.length) return res.json({ ok: false, error: 'No mappable rows found — expected Branch / Category / Code / SOH columns.', skipped });
    const client = await pool.connect(); let units = 0;
    try {
      await client.query('BEGIN');
      for (let i = 0; i < keys.length; i += 400) {
        const slice = keys.slice(i, i + 400), params = [], tuples = [];
        slice.forEach(k => { const t = k.split('\t'); params.push(t[1], t[0], date, agg[k]); const o = params.length; tuples.push(`($${o - 3},$${o - 2},$${o - 1},$${o},'cin7_upload')`); units += agg[k]; });
        await client.query(`INSERT INTO planner.inventory_snapshots (sku, warehouse, snapshot_date, available, source) VALUES ${tuples.join(',')}
          ON CONFLICT (sku, warehouse, snapshot_date) DO UPDATE SET available=EXCLUDED.available, source=EXCLUDED.source`, params);
      }
      await client.query('COMMIT');
    } catch (e) { await client.query('ROLLBACK').catch(() => {}); throw e; } finally { client.release(); }
    const whs = [...new Set(keys.map(k => k.split('\t')[0]))].sort();
    const dates = (await pool.query(`SELECT to_char(snapshot_date,'YYYY-MM-DD') d, count(*)::int n, sum(available)::int u FROM planner.inventory_snapshots GROUP BY 1 ORDER BY 1`)).rows;
    res.json({ ok: true, date, rows: keys.length, units, warehouses: whs, skipped, dates });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Inverse normal CDF (Acklam) — service level fraction → Z. Lets any service level be used (not just a fixed set).
function _normInv(p) { if (!(p > 0)) return -100; if (p >= 1) return 100;
  const a = [-3.969683028665376e1, 2.209460984245205e2, -2.759285104469687e2, 1.38357751867269e2, -3.066479806614716e1, 2.506628277459239];
  const b = [-5.447609879822406e1, 1.615858368580409e2, -1.556989798598866e2, 6.680131188771972e1, -1.328068155288572e1];
  const c = [-7.784894002430293e-3, -3.223964580411365e-1, -2.400758277161838, -2.549732539343734, 4.374664141464968, 2.938163982698783];
  const d = [7.784695709041462e-3, 3.224671290700398e-1, 2.445134137142996, 3.754408661907416];
  const pl = 0.02425, ph = 1 - pl; let q, r;
  if (p < pl) { q = Math.sqrt(-2 * Math.log(p)); return (((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) / ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1); }
  if (p <= ph) { q = p - 0.5; r = q * q; return (((((a[0] * r + a[1]) * r + a[2]) * r + a[3]) * r + a[4]) * r + a[5]) * q / (((((b[0] * r + b[1]) * r + b[2]) * r + b[3]) * r + b[4]) * r + 1); }
  q = Math.sqrt(-2 * Math.log(1 - p)); return -(((((c[0] * q + c[1]) * q + c[2]) * q + c[3]) * q + c[4]) * q + c[5]) / ((((d[0] * q + d[1]) * q + d[2]) * q + d[3]) * q + 1);
}
// ── DEMAND ▸ Inputs ▸ Backtest — per market×pool historical cover vs demand + service-level options/recommendation ──
// Query: from/to (YYYY-MM window), target (service-level baseline for the status flag). Config (risk levels + CV
// thresholds) in app_settings.ssm_backtest_cfg. Each risk option carries a WHAT-IF replay (empStockoutMonths) on the window.
app.get('/api/demand/ssm-backtest', async (req, res) => {
  try {
    const q0 = req.query || {};
    const from = /^\d{4}-\d{2}$/.test(String(q0.from || '')) ? q0.from : null;
    const to = /^\d{4}-\d{2}$/.test(String(q0.to || '')) ? q0.to : null;
    let cfg = { slLow: 99, slMed: 95, slHigh: 90, cvMed: 0.45, cvHi: 0.7, halfLifeMo: 6 };   // halfLifeMo=0 → equal weight
    try { const cr = (await pool.query(`SELECT value FROM planner.app_settings WHERE key='ssm_backtest_cfg'`)).rows[0]; if (cr && cr.value) { const o = JSON.parse(cr.value); ['slLow', 'slMed', 'slHigh', 'cvMed', 'cvHi'].forEach(k => { const v = Number(o[k]); if (Number.isFinite(v) && v > 0) cfg[k] = v; }); if (Number.isFinite(Number(o.halfLifeMo)) && Number(o.halfLifeMo) >= 0) cfg.halfLifeMo = Number(o.halfLifeMo); } } catch (e) {}
    const target = (() => { const t = Number(q0.target); return Number.isFinite(t) && t >= 50 && t < 100 ? t : cfg.slMed; })();
    const inWin = m => (!from || m >= from) && (!to || m <= to);
    const sohRows = (await pool.query(`SELECT to_char(snapshot_date,'YYYY-MM') m, upper(split_part(warehouse,'_',1)) co,
        CASE WHEN warehouse LIKE '%fba' THEN 'FBA' ELSE '3PL' END pool, sum(available)::float oh
      FROM planner.inventory_snapshots GROUP BY 1,2,3`)).rows.filter(r => inWin(r.m));
    const demRows = (await pool.query(`SELECT to_char(month,'YYYY-MM') m, upper(country) co,
        CASE WHEN channel='FBA' THEN 'FBA' ELSE '3PL' END pool, sum(units)::float u
      FROM planner.sales_actuals GROUP BY 1,2,3`)).rows;
    const lead = {};
    (await pool.query(`SELECT 'UK' co, avg(china_to_uk_lead_time_weeks) l FROM planner.products WHERE in_planning_scope
      UNION ALL SELECT 'US', avg(china_to_us_lead_time_weeks) FROM planner.products WHERE in_planning_scope
      UNION ALL SELECT 'EU', avg(china_to_eu_lead_time_weeks) FROM planner.products WHERE in_planning_scope
      UNION ALL SELECT 'AU', avg(china_to_au_lead_time_weeks) FROM planner.products WHERE in_planning_scope`)).rows
      .forEach(r => { lead[r.co] = Number(r.l) || 9; });
    const cost = {};   // demand-weighted avg unit cost per market (for the £ working-capital estimate)
    try { (await pool.query(`SELECT upper(sa.country) co, sum(sa.units*coalesce(p.cost,0))/nullif(sum(sa.units),0) c
        FROM planner.sales_actuals sa JOIN planner.products p ON p.sku=sa.sku WHERE coalesce(p.cost,0)>0 GROUP BY 1`)).rows
      .forEach(r => { cost[r.co] = Number(r.c) || 0; }); } catch (e) {}
    const dm = {}; demRows.forEach(r => { dm[r.co + '|' + r.pool + '|' + r.m] = r.u; });
    const g = {};   // co|pool -> {covers:[], dem:[]}
    sohRows.forEach(r => { const k = r.co + '|' + r.pool; const d = dm[k + '|' + r.m]; if (d == null || !(d > 0)) return;
      (g[k] || (g[k] = { covers: [], dem: [], months: [] })); const wk = d / 4.33; const cov = r.oh / wk;
      g[k].covers.push(cov); g[k].dem.push(d); g[k].months.push(r.m); });
    const Zof = sl => _normInv(sl / 100);
    const out = [];
    Object.keys(g).sort().forEach(k => { const [co, pool] = k.split('|'); const o = g[k]; const n = o.covers.length; if (!n) return;
      const avgCov = o.covers.reduce((a, b) => a + b, 0) / n, minCov = Math.min.apply(null, o.covers), maxCov = Math.max.apply(null, o.covers);
      // Recency-weighted demand stats — exponential decay by months from the latest snapshot (half-life = cfg.halfLifeMo;
      // 0 → equal weight). So the recommendation tracks RECENT demand behaviour (mix shifts, and eventually SSM-driven buys).
      const idxOf = m => (+m.slice(0, 4)) * 12 + (+m.slice(5, 7)), maxIdx = Math.max.apply(null, o.months.map(idxOf));
      const wt = o.months.map(m => cfg.halfLifeMo > 0 ? Math.pow(0.5, (maxIdx - idxOf(m)) / cfg.halfLifeMo) : 1);
      const W = wt.reduce((a, b) => a + b, 0) || 1;
      const dMean = o.dem.reduce((a, x, i) => a + wt[i] * x, 0) / W, wkMean = dMean / 4.33;
      const dVar = o.dem.reduce((a, x, i) => a + wt[i] * (x - dMean) * (x - dMean), 0) / W, dSd = Math.sqrt(dVar), cv = dMean > 0 ? dSd / dMean : 0;
      const Lw = lead[co] || 9, cycle = 4, capW = pool === 'FBA' ? 8 : 52, cu = cost[co] || 0;
      // safety weeks = Z·CV·√(L)·√4.33 + review cycle — matches ssmCoverWeeks' cover shape. estGbp = avg units held × unit cost.
      // WHAT-IF replay: safety units = Z·σ_monthly·√(lead months); a "stockout month" = a month whose demand surprise beat that buffer.
      const empStock = sl => { const su = Zof(sl) * dSd * Math.sqrt(Lw / 4.33); return o.dem.filter(x => (x - dMean) > su).length; };
      const mk = sl => { let cw = Math.round(Zof(sl) * cv * Math.sqrt(Lw) * 2.081 + cycle); cw = Math.max(1, Math.min(cw, capW)); const au = Math.round(cw * wkMean);
        return { sl: Math.round(sl * 10) / 10, coverWks: cw, avgUnits: au, estGbp: Math.round(au * cu), stockoutPct: Math.round((100 - sl) * 10) / 10, empStockoutMonths: empStock(sl) }; };
      const RISK = {}; RISK[cfg.slLow] = 'Low risk (safe)'; RISK[cfg.slMed] = 'Medium'; RISK[cfg.slHigh] = 'High risk (tight)';
      const riskOptions = [cfg.slLow, cfg.slMed, cfg.slHigh].map(sl => { const x = mk(sl); x.level = RISK[sl] || (sl + '%'); return x; });
      const suggestedSl = cv >= cfg.cvHi ? cfg.slLow : cv >= cfg.cvMed ? cfg.slMed : cfg.slHigh;
      const recOpt = mk(suggestedSl), tgtOpt = mk(target);
      const overstockMonths = o.covers.filter(c => c > 2 * tgtOpt.coverWks).length;
      const flag = avgCov > tgtOpt.coverWks * 1.5 ? 'overstocked' : (minCov < tgtOpt.coverWks ? 'tight' : 'ok');
      out.push({ co, pool, months: n, from: o.months[0], to: o.months[n - 1], avgCover: Math.round(avgCov * 10) / 10, minCover: Math.round(minCov * 10) / 10, maxCover: Math.round(maxCov * 10) / 10,
        weeklyDemand: Math.round(wkMean), cv: Math.round(cv * 100) / 100, leadWks: Math.round(Lw * 10) / 10, unitCost: Math.round(cu * 100) / 100, overstockMonths, riskOptions, suggestedSl: Math.round(suggestedSl * 10) / 10, recSl: Math.round(suggestedSl * 10) / 10, recCoverWks: recOpt.coverWks, targetSl: target, targetCoverWks: tgtOpt.coverWks, flag }); });
    const dates = (await pool.query(`SELECT to_char(snapshot_date,'YYYY-MM-DD') d FROM planner.inventory_snapshots GROUP BY 1 ORDER BY 1`)).rows.map(r => r.d);
    res.json({ ok: true, rows: out, snapshotDates: dates, cfg, window: { from, to }, target });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
