// Same-origin image proxy — lets the barcode-label PNG export embed a remote swatch without tainting the
// canvas. Read-only fetch of a public image URL; must be registered before the generic :section route.
app.get('/api/supply/img', async (req, res) => {
  try {
    const u = String(req.query.url || '');
    if (!/^https?:\/\//i.test(u)) return res.status(400).end();
    const r = await fetch(u);
    if (!r.ok) return res.status(502).end();
    res.setHeader('content-type', r.headers.get('content-type') || 'image/jpeg');
    res.setHeader('cache-control', 'public, max-age=86400');
    res.end(Buffer.from(await r.arrayBuffer()));
  } catch (e) { log500(e); res.status(500).end(); }
});

// Static brand asset for the carton/inner labels — the Global Recycled Standard logo (same-origin so it can be
// embedded into the rasterised label PNG without tainting the canvas).
app.get('/api/supply/asset/:name', (req, res) => {
  const files = { grs: ['grs-logo.png', 'image/png'], db: ['db-logo.png', 'image/png'],
    'gotham-book': ['gotham-book.ttf', 'font/ttf'], 'gotham-bold': ['gotham-bold.ttf', 'font/ttf'] };
  const a = files[req.params.name]; if (!a) return res.status(404).end();
  try { res.setHeader('content-type', a[1]); res.setHeader('cache-control', 'public, max-age=86400');
    res.end(readFileSync(new URL('./supply/assets/' + a[0], import.meta.url))); }
  catch (e) { res.status(404).end(); }
});

// Label rows for the supplier-portal barcode downloads — for one PO's SKUs (?po=) or a whole production's SKUs
// scoped to a supplier via supplier_multiple_all (?prod=&supplier=). MASTER variants only, barcode present.
app.get('/api/supply/label-data', async (req, res) => {
  try {
    const { po, prod, supplier, skus, batch } = req.query;
    let where, params;
    if (skus) { where = 'sl.sku = ANY($1)'; params = [String(skus).split(',').map(s => s.trim()).filter(Boolean)]; }
    else if (po) { where = 'sl.sku IN (SELECT sku FROM planner.purchase_order_lines WHERE po=$1)'; params = [po]; }
    else if (prod) {
      where = "sl.sku IN (SELECT DISTINCT l.sku FROM planner.purchase_order_lines l JOIN planner.purchase_orders po ON po.po=l.po WHERE po.prod_no=$1)";
      params = [prod];
      if (supplier) { where += " AND coalesce(p.supplier_multiple_all,'') ILIKE '%'||$2||'%'"; params.push(supplier); }
    } else if (batch) {
      where = "sl.sku IN (SELECT DISTINCT l.sku FROM planner.purchase_order_lines l JOIN planner.purchase_orders po ON po.po=l.po WHERE po.batch_id=$1)";
      params = [batch];
      if (supplier) { where += " AND coalesce(p.supplier_multiple_all,'') ILIKE '%'||$2||'%'"; params.push(supplier); }
    } else return res.status(400).json({ error: 'po, prod or batch required' });
    const rows = (await pool.query(`
      SELECT sl.sku, sl.barcode_sku_name, sl.barcode_carton_name, sl.barcode_inner_name,
        sl.size, coalesce(p.size_short, sl.size_short, '') size_short, sl.category, coalesce(nullif(p.carton_qty::text,''), sl.carton_qty::text) carton_qty,
        sl.product_barcode, sl.carton_barcode, sl.inner_barcode, sl.grs_material, coalesce(p.colour_swatch_url, sl.swatch_url) swatch_url, coalesce(p.size_long,'') size_long, coalesce((SELECT s.code FROM planner.suppliers s WHERE lower(s.name)=lower(p.main_supplier_final) LIMIT 1),'') supplier_code,
        sl.uk_carton_l, sl.uk_carton_w, sl.uk_carton_h, sl.uk_carton_wt,
        coalesce(p.supplier_multiple_all,'') supplier_multiple, p.uk_rt, p.us_rt, p.eu_rt, coalesce(p.product_name,'') product_name
      FROM planner.v_sku_attrs sl LEFT JOIN planner.products p ON p.sku=sl.sku
      WHERE ${where}
        AND coalesce(sl.variant_type,'') NOT ILIKE 'set'
        AND coalesce(sl.product_barcode, sl.carton_barcode, sl.inner_barcode) IS NOT NULL
      ORDER BY sl.sku`, params)).rows;
    // Stamp batch + production date on each row (from ?batch, else the PO's batch_id) → label prints BATCH / DATE.
    let batchCode = batch || null;
    if (!batchCode && po) { try { batchCode = (await pool.query(`SELECT batch_id FROM planner.purchase_orders WHERE po=$1`, [po])).rows[0]?.batch_id || null; } catch (e) {} }
    if (batchCode) {
      let bd = null;
      try { bd = (await pool.query(`SELECT to_char(batch_date,'YYYY-MM-DD') d FROM planner.batches WHERE batch=$1`, [batchCode])).rows[0]?.d || null; } catch (e) {}
      rows.forEach(r => { r.batch = batchCode; r.batch_date = bd; });
    }
    res.json(rows);
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});

// SUG-0012 — PO-grid SKU filter: return the PO refs whose order-plan lines contain ANY of the given SKUs
// (comma/space separated → OR search, partial-match via ILIKE). The grid intersects this with its other filters.
app.get('/api/supply/pos-by-sku', async (req, res) => {
  const toks = String(req.query.q || '').split(/[\s,]+/).map(s => s.trim()).filter(Boolean).slice(0, 200);
  if (!toks.length) return res.json({ pos: [] });
  try {
    const conds = toks.map((_, i) => `l.sku ILIKE '%'||$${i + 1}||'%'`).join(' OR ');
    const pos = (await pool.query(`SELECT DISTINCT l.po FROM planner.purchase_order_lines l WHERE ${conds}`, toks)).rows.map(r => r.po);
    res.json({ pos });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// ── ERP integration (Cin7 ▸ Fulfil migration) ──────────────────────────────────────────────────────────
// Which ERP the app targets + (for Fulfil) which environment, both from CONFIG ▸ General settings (app_settings).
// Fulfil API keys/subdomains live in the server env, one pair per environment. Nothing here calls Fulfil yet —
// this just resolves the active config + reports whether keys are present (the PO push wiring comes next).
function fulfilConfigFor(env) {
  env = (env === 'live') ? 'live' : 'sandbox';
  const P = 'FULFIL_' + env.toUpperCase() + '_';
  const subdomain = (process.env[P + 'SUBDOMAIN'] || '').trim();
  const apiKey = (process.env[P + 'API_KEY'] || '').trim();
  return { env, subdomain, apiKey, base: subdomain ? ('https://' + subdomain + '.fulfil.io/api/v2') : '', configured: !!(subdomain && apiKey) };
}
async function activeErp() { try { const r = (await pool.query(`SELECT value FROM planner.app_settings WHERE key='erp_integration'`)).rows[0]; return (r && r.value === 'fulfil') ? 'fulfil' : 'cin7'; } catch (e) { return 'cin7'; } }
async function activeFulfilEnv() { try { const r = (await pool.query(`SELECT value FROM planner.app_settings WHERE key='fulfil_env'`)).rows[0]; return (r && r.value === 'live') ? 'live' : 'sandbox'; } catch (e) { return 'sandbox'; } }
// PO archive cutoff (CONFIG ▸ Admin ▸ General). Returns the production number below which COMPLETE POs are archived
// (hidden from the admin PO grid + Order Plan by default), or null when archiving is off. Never affects the supplier
// portal or cashflow. app_settings key 'po_archive_before_prod'.
async function poArchiveCutoff() {
  try { const r = (await pool.query(`SELECT value FROM planner.app_settings WHERE key='po_archive_before_prod'`)).rows[0];
    const n = r ? parseInt(r.value, 10) : NaN; return (Number.isFinite(n) && n > 0) ? n : null; }
  catch (e) { return null; }
}
// SQL fragment: TRUE when a row is archived (complete + numeric prod_no below the cutoff). `alias` = the table/subquery
// alias exposing status + prod_no. Non-numeric/blank prod_no → never archived. Bind the cutoff as the given $param.
const archivedSql = (alias, param) =>
  `${alias}.status ILIKE '%complete%' AND (CASE WHEN coalesce(${alias}.prod_no,'') ~ '^[0-9]+$' THEN ${alias}.prod_no::int ELSE 999999 END) < ${param}`;
// Status for CONFIG ▸ General settings — active ERP, Fulfil env, and whether the env keys are configured (no live call).
app.get('/api/supply/erp-status', async (req, res) => {
  try { res.json({ erp: await activeErp(), fulfil_env: await activeFulfilEnv(),
    fulfil: { sandbox: fulfilConfigFor('sandbox').configured, live: fulfilConfigFor('live').configured } }); }
  catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// ===================== Fulfil ERP client (v2 REST / Tryton model API) =====================
// Targets Fulfil when Active ERP = Fulfil, mirroring the Cin7 push process (dates + line items, create-if-absent).
// ⚠ FIELD MAPPING BELOW IS UNVERIFIED — confirm against the Fulfil SANDBOX on the first run, then adjust.
// Safety: with no keys set (FULFIL_<ENV>_SUBDOMAIN/_API_KEY) every op throws NO_FULFIL_CFG and NOTHING sends.
// The line/create push is a DRY-RUN for now (builds + returns the intended payload, does not POST a blind live
// create) until the mapping is validated on the sandbox — then FULFIL_LINES_SEND flips it to a real write.
const FULFIL_LINES_SEND = false;   // flip true once the create/line payload is verified against the sandbox catalog
const FULFIL_MAP = {
  poModel: 'purchase.purchase', lineModel: 'purchase.line', partyModel: 'party.party',
  productModel: 'product.product', whModel: 'stock.location', currencyModel: 'currency.currency',
  ref: 'reference',                 // PO number field on purchase.purchase  (verified: reference exists, search_read ok)
  party: 'party',                   // supplier party (id) — REQUIRED to create a PO
  company: 'company',               // company (id) — sandbox has one: id 1 (Dock & Bay Ltd)
  currency: 'currency',             // currency (id) — resolved by ISO code (sandbox: USD=143)
  warehouse: 'warehouse',           // receiving warehouse (id) — resolved by code (ILG/IFULFILLMENT/G10/COGHLANS)
  deliveryDate: 'delivery_date',    // planner completion date maps here — set per line (verify on first real push)
  linesField: 'lines',              // one2many on purchase.purchase; created inline via Tryton ["create",[...]]
  line: { product: 'product', productCode: 'code', qty: 'quantity', price: 'unit_price', desc: 'description', deliveryDate: 'delivery_date' },
  // Defaults discovered read-only from the sandbox (2026-07): single company, USD currency present.
  // Warehouse defaults to ILG unless the PO's destination maps to one of the codes above.
  defaultCompany: 1, defaultWarehouseCode: 'ILG',
};
async function fulfilFetch(method, path, body) {
  const cfg = fulfilConfigFor(await activeFulfilEnv());
  if (!cfg.configured) { const e = new Error('Fulfil ' + cfg.env + ' API not configured (set FULFIL_' + cfg.env.toUpperCase() + '_SUBDOMAIN + FULFIL_' + cfg.env.toUpperCase() + '_API_KEY). No write performed.'); e.code = 'NO_FULFIL_CFG'; throw e; }
  const r = await fetch(cfg.base + path, { method, headers: { 'X-API-KEY': cfg.apiKey, 'Content-Type': 'application/json' }, body: body != null ? JSON.stringify(body) : undefined });
  const t = await r.text().catch(() => ''); let j = null; try { j = t ? JSON.parse(t) : null; } catch (e) {}
  if (!r.ok) { const e = new Error('Fulfil ' + r.status + ': ' + String(t).slice(0, 300)); e.status = r.status; throw e; }
  return j;
}
// find a Fulfil purchase order id by its reference (PO number); null if not present
async function fulfilFindPO(reference) {
  const rows = await fulfilFetch('PUT', '/model/' + FULFIL_MAP.poModel + '/search_read', [[[FULFIL_MAP.ref, '=', reference]], 0, 1, null, ['id', FULFIL_MAP.ref]]);
  return (Array.isArray(rows) && rows[0]) ? rows[0].id : null;
}
// update the delivery date on an existing Fulfil PO (a date alone can't create a PO — absent → report missing)
async function fulfilSyncDate(po, completion) {
  const iso = String(completion).slice(0, 10);
  const id = await fulfilFindPO(po);
  if (!id) return { ok: false, missing: true, error: 'PO ' + po + ' is not in Fulfil yet — push its lines first (create), then the date.' };
  await fulfilFetch('PUT', '/model/' + FULFIL_MAP.poModel + '/' + id, { [FULFIL_MAP.deliveryDate]: iso });
  return { ok: true, fulfil_id: id, deliveryDate: iso };
}
// ── Read-only resolvers: map planner values → Fulfil object ids (verifiable against the sandbox now) ──
async function fulfilSearchOne(model, domain, fields) {
  const rows = await fulfilFetch('PUT', '/model/' + model + '/search_read', [domain, 0, 1, null, fields || ['id']]);
  return (Array.isArray(rows) && rows[0]) || null;
}
async function fulfilResolveParty(name) {
  if (!name) return null;
  const r = await fulfilSearchOne(FULFIL_MAP.partyModel, [['name', '=', name]], ['id', 'name']);
  return r ? r.id : null;
}
async function fulfilResolveCurrency(code) {
  const r = await fulfilSearchOne(FULFIL_MAP.currencyModel, [['code', '=', String(code || 'USD').toUpperCase()]], ['id', 'code']);
  return r ? r.id : null;
}
async function fulfilResolveWarehouse(code) {
  const r = await fulfilSearchOne(FULFIL_MAP.whModel, [['type', '=', 'warehouse'], ['code', '=', code]], ['id', 'code']);
  return r ? r.id : null;
}
// SKU → product id (by product code). Returns a map of found codes; missing codes are reported by the caller.
async function fulfilResolveProducts(skus) {
  const uniq = Array.from(new Set(skus.filter(Boolean)));
  const out = {};
  if (!uniq.length) return out;
  const rows = await fulfilFetch('PUT', '/model/' + FULFIL_MAP.productModel + '/search_read', [[['code', 'in', uniq]], 0, uniq.length, null, ['id', 'code']]);
  (rows || []).forEach(r => { if (r && r.code != null) out[String(r.code)] = r.id; });
  return out;
}
// push line items (SKU / qty / price) + delivery date to Fulfil; create the PO if absent. Gathers the SAME planner
// data the Cin7 push uses. Resolves supplier/currency/warehouse/products to Fulfil ids first (read-only) and aborts
// with a clear message if any are missing — so a create is never attempted with an unresolved SKU/supplier.
// DRY-RUN until FULFIL_LINES_SEND=true (returns the resolved payload for review); then it performs the real write.
async function fulfilPushLines(po, completion) {
  const lines = (await pool.query(`SELECT l.sku, l.qty,
      coalesce((SELECT c.final_cost FROM planner.portal_line_costs c WHERE c.po=l.po AND c.sku=l.sku AND c.final_cost IS NOT NULL AND c.confirmed_at IS NOT NULL), l.cost_price) price
    FROM planner.purchase_order_lines l WHERE l.po=$1 AND coalesce(l.qty,0)>0 ORDER BY l.sku`, [po])).rows;
  const poRow = (await pool.query(`SELECT coalesce(po.supplier_name,'') supplier, coalesce(po.branch,'') warehouse,
      nullif(trim(coalesce(b.fulfil_id,'')),'') branch_fulfil_id
    FROM planner.purchase_orders po LEFT JOIN planner.branches b ON b.name=po.branch WHERE po.po=$1`, [po])).rows[0] || {};
  const supName = poRow.supplier || '';
  const supRow = (await pool.query(`SELECT coalesce(default_currency,'USD') c, nullif(trim(coalesce(fulfil_id,'')),'') fulfil_id FROM planner.suppliers WHERE name=$1`, [supName])).rows[0] || {};
  const curCode = supRow.c || 'USD';
  if (!lines.length) return { ok: false, error: 'PO ' + po + ' has no line quantities to push.' };

  const fulfilId = await fulfilFindPO(po);                          // needs keys; throws NO_FULFIL_CFG when absent
  // Prefer the Fulfil party id stored on the supplier record (planner.suppliers.fulfil_id, manual entry) — this is the
  // authoritative link and skips the name-lookup API call. Note: it's env-specific (sandbox party id ≠ live id), so it
  // must be re-entered at go-live. Falls back to a name search when the field is blank.
  const storedPartyId = /^\d+$/.test(String(supRow.fulfil_id || '')) ? parseInt(supRow.fulfil_id, 10) : null;
  const partyId = storedPartyId || (await fulfilResolveParty(supName));
  const currencyId = await fulfilResolveCurrency(curCode);
  // Warehouse: prefer the Fulfil stock.location id stored on the branch (planner.branches.fulfil_id) — the authoritative
  // link (branch names don't match Fulfil codes 1:1). Else try to match by code. No silent default: an unresolved
  // branch is flagged in the pre-flight so it never writes to the wrong warehouse.
  const storedWhId = /^\d+$/.test(String(poRow.branch_fulfil_id || '')) ? parseInt(poRow.branch_fulfil_id, 10) : null;
  const whCode = String(poRow.warehouse || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  const warehouseId = storedWhId || (whCode ? await fulfilResolveWarehouse(whCode) : null);
  const prodMap = await fulfilResolveProducts(lines.map(l => l.sku));
  const missingSkus = lines.map(l => l.sku).filter(s => !(String(s) in prodMap));

  // Pre-flight resolution report — surfaces exactly what's missing before any write.
  const resolution = { supplier: supName, party_id: partyId, party_source: storedPartyId ? 'suppliers.fulfil_id' : 'name-lookup', currency: curCode, currency_id: currencyId,
    branch: poRow.warehouse || '', warehouse_id: warehouseId, warehouse_source: storedWhId ? 'branches.fulfil_id' : (warehouseId ? 'code-match' : 'unresolved'),
    products_found: Object.keys(prodMap).length, products_total: lines.length, missing_skus: missingSkus };
  const problems = [];
  if (!fulfilId && !partyId) problems.push('supplier "' + supName + '" is not a party in Fulfil (create it / import suppliers first)');
  if (!currencyId) problems.push('currency ' + curCode + ' not found in Fulfil');
  if (!warehouseId) problems.push('branch "' + (poRow.warehouse || '') + '" has no Fulfil warehouse — set its Fulfil ERP ID in CONFIG ▸ Branches');
  if (missingSkus.length) problems.push(missingSkus.length + ' SKU(s) not in Fulfil catalog: ' + missingSkus.slice(0, 8).join(', ') + (missingSkus.length > 8 ? '…' : ''));

  const lineDicts = lines.map(l => ({
    [FULFIL_MAP.line.product]: prodMap[String(l.sku)] || null,
    [FULFIL_MAP.line.qty]: Number(l.qty) || 0,
    [FULFIL_MAP.line.price]: l.price == null ? null : Number(l.price),
    [FULFIL_MAP.line.deliveryDate]: completion ? String(completion).slice(0, 10) : null,
  }));
  const headerPayload = {
    [FULFIL_MAP.ref]: po, [FULFIL_MAP.party]: partyId, [FULFIL_MAP.company]: FULFIL_MAP.defaultCompany,
    [FULFIL_MAP.currency]: currencyId, [FULFIL_MAP.warehouse]: warehouseId,
    [FULFIL_MAP.linesField]: [['create', lineDicts]],
  };

  if (!FULFIL_LINES_SEND) {
    return { ok: problems.length === 0, dry_run: true,
      note: problems.length ? 'Not ready to push — resolve the issues below (usually: import the catalog/supplier into the Fulfil sandbox), then re-run.' : 'All references resolved. Flip FULFIL_LINES_SEND=true to perform the real ' + (fulfilId ? 'update' : 'create') + '.',
      action: fulfilId ? 'update' : 'create', fulfil_id: fulfilId, resolution, problems, would_send: headerPayload };
  }
  if (problems.length) { const e = new Error('Fulfil push blocked: ' + problems.join('; ')); e.code = 'FULFIL_UNRESOLVED'; throw e; }

  if (fulfilId) {
    // UPDATE: replace the existing PO's lines and refresh the delivery date. (delete existing + create fresh)
    const existing = await fulfilFetch('PUT', '/model/' + FULFIL_MAP.lineModel + '/search_read', [[['purchase', '=', fulfilId]], 0, 500, null, ['id']]);
    const ids = (existing || []).map(r => r.id);
    if (ids.length) await fulfilFetch('PUT', '/model/' + FULFIL_MAP.poModel + '/' + fulfilId, { [FULFIL_MAP.linesField]: [['delete', ids]] });
    await fulfilFetch('PUT', '/model/' + FULFIL_MAP.poModel + '/' + fulfilId, { [FULFIL_MAP.linesField]: [['create', lineDicts]] });
    return { ok: true, action: 'update', fulfil_id: fulfilId, lines: lineDicts.length, resolution };
  }
  // CREATE: Fulfil v2 create → POST list of dicts, returns created ids.
  const created = await fulfilFetch('POST', '/model/' + FULFIL_MAP.poModel, [headerPayload]);
  const newId = Array.isArray(created) ? created[0] : (created && created.id);
  return { ok: true, action: 'create', fulfil_id: newId, lines: lineDicts.length, resolution };
}
