// ── Escalate a timeline message as an email ─────────────────────────────────────────────────────
// initiator 'supplier' (portal) → routed to a CONFIG-managed internal list by context; link → planner.
// initiator 'internal' (grid)   → that supplier's active portal users;                 link → portal.
const PLANNER_URL = (process.env.PLANNER_URL || 'https://horizon.dockandbay.com').replace(/\/$/, '');
const PORTAL_URL = (process.env.PORTAL_URL || 'https://suppliers.dockandbay.com/portal').replace(/\/$/, '');
function _eh(s) { return String(s == null ? '' : s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c])); }
function _emails(s) { return String(s || '').split(/[,;\s]+/).map(x => x.trim()).filter(x => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(x)); }
function escLink(kind, ref, audience) {
  // Supplier portal deep link — opens the PO (portal PO card defaults to its TIMELINE tab). Shipment/sample
  // portal escalations have no per-record portal view, so fall back to the portal root.
  if (audience === 'portal') return PORTAL_URL + (kind === 'po' ? ('?po=' + encodeURIComponent(ref)) : '');
  if (kind === 'shipment') return PLANNER_URL + '/#/supply/purchase-orders/shipments/' + encodeURIComponent(ref);
  if (kind === 'sample') return PLANNER_URL + '/#/supply/samples';
  return PLANNER_URL + '/#/supply/purchase-orders/plan/' + encodeURIComponent(ref);
}
// Shared Resend sender — the SAME best-effort method the supplier magic-link uses (sendMagicEmail):
// swallow any failure and log it, NEVER throw. Email is best-effort; a Resend hiccup / unverified domain
// must not fail the user's action (that's what made Escalate show "Load failed"). Returns a result object.
// Email log (migration 159): record every send so CONFIG ▸ Email log can show what went out. Defensive — a
// missing table (pre-migration) or any insert error never blocks the actual email.
async function logEmail(m) {
  try {
    await pool.query(`INSERT INTO planner.email_log (resend_id, recipients, subject, kind, ref, status, error, sent_by)
      VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
      [m.resend_id || null, String(m.recipients || '').slice(0, 2000), String(m.subject || '').slice(0, 500),
       m.kind || 'other', m.ref || null, m.status || 'sent', m.error ? String(m.error).slice(0, 500) : null, m.by || null]);
  } catch (e) { /* table absent pre-migration 159, or insert failed — never block the send */ }
}
async function sendResendEmail({ to, subject, html, cc, kind, ref, by, replyTo, attachments }) {
  const list = Array.isArray(to) ? to : [to];
  const cclist = cc ? (Array.isArray(cc) ? cc : [cc]).filter(Boolean) : [];
  const recipients = list.concat(cclist).filter(Boolean).join(', ');
  if (!process.env.RESEND_API_KEY) { console.log('[email] no RESEND_API_KEY — would email ' + list.join(', ') + (cclist.length ? ' (cc ' + cclist.join(', ') + ')' : '') + ' :: ' + subject + ((attachments && attachments.length) ? ' [+' + attachments.length + ' attachment]' : '')); logEmail({ recipients, subject, kind, ref, by, status: 'sandbox' }); return { sandbox: true, sent: 0 }; }
  try {
    const payload = { from: process.env.PORTAL_FROM || 'Dock & Bay <portal@dockandbay.com>', to: list, subject, html };
    if (cclist.length) payload.cc = cclist;
    if (replyTo && /@/.test(String(replyTo))) payload.reply_to = String(replyTo).trim();   // reply goes to the person who triggered it (submitter / escalator / supplier)
    if (attachments && attachments.length) payload.attachments = attachments.map(a => ({ filename: a.filename || 'attachment', content: a.content }));   // Resend: content = base64 string
    const resp = await fetch('https://api.resend.com/emails', { method: 'POST',
      headers: { Authorization: 'Bearer ' + process.env.RESEND_API_KEY, 'Content-Type': 'application/json' },
      body: JSON.stringify(payload) });
    if (!resp.ok) { const t = await resp.text().catch(() => ''); console.error('[email] Resend error ' + resp.status + ': ' + t.slice(0, 200)); logEmail({ recipients, subject, kind, ref, by, status: 'error', error: 'resend ' + resp.status }); return { sent: 0, error: 'resend ' + resp.status }; }
    const rid = await resp.json().then(j => j && j.id).catch(() => null);
    logEmail({ recipients, subject, kind, ref, by, status: 'sent', resend_id: rid });
    return { sent: list.length };
  } catch (e) { console.error('[email] Resend failed:', e.message); logEmail({ recipients, subject, kind, ref, by, status: 'error', error: e.message }); return { sent: 0, error: e.message }; }
}
// Escalation email now goes through the shared best-effort sender (like the magic link) — never throws.
async function escalateSend(r) { return sendResendEmail({ to: r.emails, subject: r.subject, html: r.html, kind: 'escalation', ref: r.ref, replyTo: r.replyTo }); }
// A supplier submitting invoice / completion info should be VISIBLE, not silent: drop an UNREAD timeline note
// on the PO (author_kind='supplier', read_at NULL → shows on the PO timeline + increments the ✉ unread badge).
// Best-effort — never break the submit if the note fails.
function ddMonYy(v) { const m = String(v || '').match(/^(\d{4})-(\d{2})-(\d{2})/); if (!m) return v;
  return m[3] + '-' + ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'][(+m[2]) - 1] + '-' + m[1].slice(2); }
// Signed movement between two ISO dates → "(DELAY of N days)" / "(BROUGHT FORWARD N days)" (blank if unchanged/invalid).
function dateDeltaLabel(oldISO, newISO) {
  const a = String(oldISO || '').slice(0, 10), b = String(newISO || '').slice(0, 10);
  if (!/^\d{4}-\d{2}-\d{2}$/.test(a) || !/^\d{4}-\d{2}-\d{2}$/.test(b)) return '';
  const days = Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 86400000);
  if (!days || isNaN(days)) return '';
  return days > 0 ? '(DELAY of ' + days + ' day' + (days === 1 ? '' : 's') + ')'
                  : '(BROUGHT FORWARD ' + (-days) + ' day' + (-days === 1 ? '' : 's') + ')';
}
async function postSupplierSubmitNote(db, po, kind, value, by) {
  const label = kind === 'invoice_value' ? ('submitted invoice information — value ' + value)
    : kind === 'completion_date' ? ('submitted completion date ' + ddMonYy(value))
    : ('submitted ' + kind);
  try {
    const sid = (await db.query(`SELECT supplier_id FROM planner.purchase_orders WHERE po=$1`, [po])).rows[0]?.supplier_id || null;
    await db.query(`INSERT INTO planner.supplier_notes (po, supplier_id, author_email, author_kind, body) VALUES ($1,$2,$3,'supplier',$4)`,
      [po, sid, by || null, 'Supplier ' + label]);
  } catch (e) { /* timeline note best-effort */ }
}
// Push email when a supplier submits invoice info. Recipients from app_settings.invoice_submit_notify,
// defaulting to zera@ + ben@ when unset. Best-effort (sandbox with no RESEND key just logs).
async function emailInvoiceSubmit(po, value, by) {
  let emails;
  try { const s = (await pool.query(`SELECT value FROM planner.app_settings WHERE key='invoice_submit_notify'`)).rows[0];
    emails = _emails(s ? s.value : ''); } catch (e) { emails = []; }
  if (!emails.length) emails = ['zera@dockandbay.com', 'ben@dockandbay.com'];
  const supName = await poSupplierName(po);   // SUG-0011: name the supplier, not the generic word "Supplier"
  const link = PLANNER_URL + '/#/supply/purchase-orders/plan/' + encodeURIComponent(po);
  const html = '<p><b>' + escHtml(supName) + '</b> submitted <b>invoice information</b> for <b>' + po + '</b>.</p>'
    + '<p>Invoice value: <b>' + value + '</b><br>Submitted by: ' + (by || 'supplier') + '</p>'
    + '<p><a href="' + link + '">Open ' + po + ' in HORIZON</a></p>';
  return sendResendEmail({ to: emails, subject: supName + ' submitted invoice info — ' + po, html, kind: 'invoice-notify', ref: po, replyTo: by });   // reply-to = the supplier who submitted
}
// Dedup the "supplier submitted invoice info" email. A supplier clicking Submit repeatedly re-stages the SAME
// invoice value, which previously fired one email per click (Ben saw 3× for PO-57EULX4). Only email when the
// value is NEW — i.e. it differs from the immediately-previous invoice submission for this PO. (The just-submitted
// row is already committed, so rows[0] = current, rows[1] = previous.)
async function invoiceSubmitIsRepeat(po, _newVal) {
  try {
    const rows = (await pool.query(`SELECT value FROM planner.supplier_submissions
      WHERE po=$1 AND kind='invoice_value' ORDER BY id DESC LIMIT 2`, [po])).rows;
    if (rows.length < 2) return false;   // first-ever invoice submission for this PO → send
    const n = s => { const x = Number(String(s == null ? '' : s).replace(/[^0-9.\-]/g, '')); return isFinite(x) ? x : null; };
    const cur = n(rows[0].value), prev = n(rows[1].value);
    return cur != null && prev != null && Math.abs(cur - prev) < 0.005;   // same amount as last time → repeat click → skip the email
  } catch (e) { return false; }   // on any error, don't suppress — better a duplicate email than a missed one
}
// supplier display name for a PO (falls back to "Supplier" when unknown) — used in supplier-submission emails
async function poSupplierName(po) {
  try { const r = (await pool.query(`SELECT coalesce(nullif(trim(supplier_name),''),'Supplier') n FROM planner.purchase_orders WHERE po=$1`, [po])).rows[0];
    return (r && r.n) || 'Supplier'; } catch (e) { return 'Supplier'; }
}
// Push email when a supplier submits a DOCUMENT for approval (same recipients as invoice submissions).
async function emailDocSubmit(po, filename, by) {
  let emails;
  try { const s = (await pool.query(`SELECT value FROM planner.app_settings WHERE key='invoice_submit_notify'`)).rows[0];
    emails = _emails(s ? s.value : ''); } catch (e) { emails = []; }
  if (!emails.length) emails = ['zera@dockandbay.com', 'ben@dockandbay.com'];
  const supName = await poSupplierName(po);   // SUG-0011: name the supplier
  const link = PLANNER_URL + '/#/supply/purchase-orders/plan/' + encodeURIComponent(po);
  const html = '<p><b>' + escHtml(supName) + '</b> submitted a <b>document for approval</b> on <b>' + po + '</b>.</p>'
    + '<p>Document: <b>' + (filename || 'document') + '</b><br>Submitted by: ' + (by || 'supplier') + '</p>'
    + '<p><a href="' + link + '">Review it on the PO ▸ Documents tab in HORIZON</a></p>';
  return sendResendEmail({ to: emails, subject: supName + ' submitted a document for approval — ' + po, html, kind: 'invoice-notify', ref: po, replyTo: by });   // reply-to = the supplier who submitted
}
// ── Payment-confirmed notification ── a payment "run" (date + supplier) is confirmed once its bank amount +
// currency are applied in the Payments Report. paymentRunDetail rebuilds that run's line detail (same source
// tables + ordering as the report) so the email mirrors the on-screen "copy for email" summary exactly.
function escHtml(s){ return String(s==null?'':s).replace(/[&<>"]/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;' }[c])); }
function fmtMoney2(n){ return Number(n||0).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
async function paymentRunDetail(runDate, supplier) {
  const rows = (await pool.query(`
    SELECT reference, round(amount,2) amount, type, deposit_ref, prod_no FROM (
      SELECT o.po reference, o.pay_completion_assigned amount, 'Completion' type, coalesce(o.deposit_ref,'') deposit_ref, coalesce(o.prod_no,'') prod_no, to_char(o.pay_completion_date,'YYYY-MM-DD') dt, o.supplier_name sup
        FROM planner.purchase_orders o WHERE o.pay_completion_date IS NOT NULL AND coalesce(o.pay_completion_assigned,0)>0
      UNION ALL SELECT o.po, o.pay_balance_1_amount, 'Balance', coalesce(o.deposit_ref,''), coalesce(o.prod_no,''), to_char(o.pay_balance_1_date,'YYYY-MM-DD'), o.supplier_name
        FROM planner.purchase_orders o WHERE o.pay_balance_1_date IS NOT NULL AND coalesce(o.pay_balance_1_amount,0)>0
      UNION ALL SELECT o.po, o.pay_balance_2_amount, 'Balance', coalesce(o.deposit_ref,''), coalesce(o.prod_no,''), to_char(o.pay_balance_2_date,'YYYY-MM-DD'), o.supplier_name
        FROM planner.purchase_orders o WHERE o.pay_balance_2_date IS NOT NULL AND coalesce(o.pay_balance_2_amount,0)>0
      UNION ALL SELECT coalesce(nullif(reference,''),description,''), amount, 'Deposit', '', coalesce(prod_no,''), to_char(date_paid,'YYYY-MM-DD'), supplier_name
        FROM planner.deposits WHERE is_deposit=true AND date_paid IS NOT NULL AND round(coalesce(amount,0))<>0
      UNION ALL SELECT coalesce(nullif(reference,''),description,''), amount, 'Other', '', coalesce(prod_no,''), to_char(date_paid,'YYYY-MM-DD'), supplier_name
        FROM planner.deposits WHERE is_deposit=false AND date_paid IS NOT NULL AND round(coalesce(amount,0))<>0
    ) z WHERE dt=$1 AND lower(trim(sup))=lower(trim($2))
    ORDER BY CASE type WHEN 'Deposit' THEN 0 WHEN 'Completion' THEN 1 WHEN 'Balance' THEN 2 ELSE 3 END`, [runDate, supplier])).rows;
  const total = Math.round(rows.reduce((a, x) => a + Number(x.amount || 0), 0) * 100) / 100;
  const code = (await pool.query(`SELECT s.code FROM planner.suppliers s WHERE lower(trim(s.name))=lower(trim($1)) LIMIT 1`, [supplier])).rows[0]?.code || '';
  return { supplier, supplier_code: code, dt: runDate, total, lines: rows };
}
// Email the supplier's opted-in portal users (receive_payment_notification=true) when a payment is confirmed.
// cc ben@ + accounts@. Amount shown in the bank currency if it isn't USD, else the base USD total. Best-effort.
async function emailPaymentConfirmed(runDate, supplier, bankAmt, bankCcy) {
  const us = (await pool.query(`SELECT lower(email) email, coalesce(contact_name,'') contact_name
     FROM planner.supplier_portal_users
     WHERE receive_payment_notification=true AND active=true AND coalesce(email,'')<>'' AND lower(trim(supplier_name))=lower(trim($1))`, [supplier])).rows;
  const to = Array.from(new Set(us.map(u => u.email)));
  const cc = ['ben@dockandbay.com', 'accounts@dockandbay.com'];
  const run = await paymentRunDetail(runDate, supplier);
  // Amount is shown in the SUPPLIER's currency (suppliers.default_currency in CONFIG), with its symbol.
  const supCcy = (await pool.query(`SELECT upper(coalesce(nullif(default_currency,''),'USD')) c FROM planner.suppliers WHERE lower(trim(name))=lower(trim($1)) LIMIT 1`, [supplier])).rows[0]?.c || 'USD';
  const CCY_SYM = { USD: '$', GBP: '£', EUR: '€', AUD: 'A$', CAD: 'C$', NZD: 'NZ$', CNY: '¥', JPY: '¥', HKD: 'HK$', SGD: 'S$' };
  const sym = CCY_SYM[supCcy] || '';
  const amtNum = fmtMoney2(run.total);
  const payAmt = sym + amtNum + ' ' + supCcy;
  const inv = 'SUPPLIER-PAYMENT-' + (run.supplier_code ? run.supplier_code + '-' : '') + run.dt;
  const cell = 'border:1px solid #cccccc;padding:4px 8px', hcell = cell + ';background:#f2f2f2;text-align:left;font-weight:bold';
  const rowsHtml = run.lines.map(l => `<tr><td style="${cell};text-align:left">${escHtml(l.reference || '')}</td><td style="${cell};text-align:right">${fmtMoney2(l.amount)}</td><td style="${cell}">${escHtml(l.type || '')}</td><td style="${cell}">${escHtml(l.prod_no || '')}</td><td style="${cell}">${escHtml(l.deposit_ref || '')}</td></tr>`).join('');
  const greet = (us.find(u => u.contact_name) || {}).contact_name || supplier;
  const html = `<div style="font-family:Arial,Helvetica,sans-serif;font-size:13px;color:#111">`
    + `<p style="margin:0 0 10px">Dear ${escHtml(greet)},</p>`
    + `<p style="margin:0 0 10px">Please see below details as confirmed for the recent payment made to <b>${escHtml(supplier)}</b> for <b>${escHtml(payAmt)}</b>.</p>`
    + `<p style="margin:0 0 10px"><b>Supplier:</b> ${escHtml(supplier)}<br><b>Payment amount:</b> ${escHtml(payAmt)}<br><b>Payment reference:</b> ${escHtml(inv)}</p>`
    + `<table style="border-collapse:collapse;font-size:13px"><thead><tr><th style="${hcell}">Reference</th><th style="${hcell};text-align:right">Amount</th><th style="${hcell}">Type</th><th style="${hcell}">Production ref</th><th style="${hcell}">Deposit ref</th></tr></thead><tbody>${rowsHtml}</tbody></table></div>`;
  const subject = `Payment ${sym}${amtNum} made to ${supplier}`;
  // Always return a preview (so the sandbox can pop it up for testing); only actually send if someone's opted in.
  const preview = { to, cc, subject, html, recipients: to.length };
  const result = to.length ? await sendResendEmail({ to, cc, subject, html }) : { skipped: 'no opted-in recipients' };
  return { preview, result };
}
async function escalateCore({ initiator, kind, ref, message, user, supplierId, setEscalated, postNote, replyTo }) {
  kind = ['po', 'shipment', 'sample'].includes(kind) ? kind : 'po';
  ref = String(ref || '').trim(); message = String(message || '').trim();
  if (!ref || !message) throw new Error('ref + message required');
  // "Escalate shipment": the flagged message + timeline note is "<user> escalated this shipment".
  if (postNote) message = (user || 'The supplier') + ' escalated this shipment';
  // "Escalate shipment" also raises the shipment's escalated STATUS (filterable on the portal + supply plan).
  // Only real shipments have a shipments row; FOB escalations (kind='po') stay email-only. Non-fatal.
  if (setEscalated && kind === 'shipment') {
    try { await pool.query(`INSERT INTO planner.shipments (shipment_ref, escalated, escalated_at) VALUES ($1, true, now())
      ON CONFLICT (shipment_ref) DO UPDATE SET escalated=true, escalated_at=now(), updated_at=now()`, [ref]); } catch (e) { /* status flag best-effort */ }
  }
  // drop the escalation onto the timeline so both sides see it (shipment thread, or the PO thread for FOB)
  if (postNote) {
    try {
      if (kind === 'shipment') await pool.query(`INSERT INTO planner.shipment_notes (shipment_ref, author_kind, author_email, body) VALUES ($1,'supplier',$2,$3)`, [ref, user || null, message]);
      else if (kind === 'po') { const sid = supplierId || (await pool.query(`SELECT supplier_id FROM planner.purchase_orders WHERE po=$1`, [ref])).rows[0]?.supplier_id;
        await pool.query(`INSERT INTO planner.supplier_notes (po, supplier_id, author_email, author_kind, body) VALUES ($1,$2,$3,'supplier',$4)`, [ref, sid || null, user || null, message]); }
    } catch (e) { /* timeline note best-effort */ }
  }
  let emails = [], audience;
  if (initiator === 'internal') {
    audience = 'portal'; let sid = supplierId;
    if (!sid) {
      if (kind === 'sample') sid = (await pool.query(`SELECT supplier_id FROM planner.sample_requests WHERE ref=$1`, [ref])).rows[0]?.supplier_id;
      else if (kind === 'shipment') sid = (await pool.query(`SELECT po.supplier_id FROM planner.shipments sh JOIN planner.purchase_orders po ON po.po=coalesce(sh.master_po,sh.shipment_ref) WHERE sh.shipment_ref=$1`, [ref])).rows[0]?.supplier_id;
      else sid = (await pool.query(`SELECT supplier_id FROM planner.purchase_orders WHERE po=$1`, [ref])).rows[0]?.supplier_id;
    }
    if (sid) emails = (await pool.query(`SELECT DISTINCT lower(email) e FROM planner.supplier_portal_users WHERE supplier_id=$1 AND active=true AND coalesce(email,'')<>''`, [sid])).rows.map(x => x.e);
  } else {
    audience = 'planner'; let key = 'escalation_supply_chain';
    if (kind === 'sample') {
      // sample "purposes" (multi-select): sales, product, photography, marketing, operations.
      // 'product' = product development → product-dev list; anything else → samples list.
      const hasProduct = (await pool.query(`SELECT ('product' = ANY(coalesce(purpose,'{}'::text[]))) x FROM planner.sample_requests WHERE ref=$1`, [ref])).rows[0]?.x;
      key = hasProduct ? 'escalation_product_dev' : 'escalation_samples';
    } else {
      const branch = kind === 'shipment'
        ? (await pool.query(`SELECT coalesce(po.branch,'') b FROM planner.shipments sh JOIN planner.purchase_orders po ON po.po=coalesce(sh.master_po,sh.shipment_ref) WHERE sh.shipment_ref=$1`, [ref])).rows[0]?.b || ''
        : (await pool.query(`SELECT coalesce(branch,'') b FROM planner.purchase_orders WHERE po=$1`, [ref])).rows[0]?.b || '';
      if (/direct to client|jlew|next/i.test(branch)) key = 'escalation_dtc';
    }
    const s = (await pool.query(`SELECT value FROM planner.app_settings WHERE key=$1`, [key])).rows[0];
    emails = _emails(s ? s.value : '');
  }
  if (!emails.length) return { ok: true, sent: 0, emails: [], note: 'no recipients configured for this route' };
  const link = escLink(kind, ref, audience);
  const subject = 'horizon escalation - ' + ref;
  const kindWord = kind === 'shipment' ? 'shipment' : kind === 'sample' ? 'sample' : 'PO';
  const html = '<p><b>' + _eh(user || 'A user') + '</b> has escalated this message on ' + kindWord + ' <b>' + _eh(ref) + '</b>:</p>'
    + '<blockquote style="border-left:3px solid #cbd5e1;margin:0;padding:4px 12px;color:#334155;white-space:pre-wrap">' + _eh(message) + '</blockquote>'
    + '<p><a href="' + link + '">Open ' + _eh(ref) + ' &rarr;</a></p>';
  const sent = await escalateSend({ emails, subject, html, replyTo });   // reply goes back to whoever escalated
  return { ok: true, sent: sent.sent || 0, emails, sandbox: !!sent.sandbox, emailError: sent.error || null, link };
}
app.post('/api/supply/escalate', async (req, res) => {
  const b = req.body || {};
  try {
    const initiator = b.initiator === 'internal' ? 'internal' : 'supplier';
    const user = initiator === 'internal' ? (shortUser(authUser(req)) || b.user || 'A user') : (b.user || 'The supplier');
    const replyTo = initiator === 'internal' ? authUser(req) : (b.reply_to || b.email || null);   // reply-to = the person who escalated
    res.json(await escalateCore({ initiator, kind: b.kind, ref: b.ref, message: b.message, user, supplierId: b.supplier_id, setEscalated: !!b.set_escalated, postNote: !!b.post_note, replyTo }));
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});

const qp = (sql, vals) => pool.query(sql, vals).then(r => r.rows);   // rows helper for the standalone portal routes
// ── Supplier portal write-backs. supplier_id is trusted here (internal preview = acting-as); the real
// /portal will derive it from the session and call the same logic. Mixed apply-flow:
//   completion_date / invoice_value → STAGED (supplier_submissions, pending) for internal one-click apply
//   tracking / carrier              → applied DIRECTLY to the PO's shipment (+ logged as applied)
//   notes                           → posted immediately (supplier_notes)
// supplier submits an actual cost price AND/OR an amended quantity for one PO line (upsert; blank clears each).
// is_added marks a SKU the supplier added to the order (one not on the original order plan).
app.post('/api/supply/portal-line-cost', async (req, res) => {
  const b = req.body || {};
  if (!b.po || !b.sku) return res.status(400).json({ error: 'po and sku required' });
  try {
    const num = v => (v === '' || v == null) ? null : Number(v);
    const cost = num(b.actual_cost), qty = num(b.amended_qty), added = !!b.is_added;
    await pool.query(`INSERT INTO planner.portal_line_costs (po, sku, actual_cost, amended_qty, is_added, submitted_by, submitted_at)
      VALUES ($1,$2,$3,$4,$5,$6, now())
      ON CONFLICT (po, sku) DO UPDATE SET actual_cost=excluded.actual_cost, amended_qty=excluded.amended_qty,
        is_added=planner.portal_line_costs.is_added OR excluded.is_added, submitted_by=excluded.submitted_by, submitted_at=now()`,
      [b.po, b.sku, cost, qty, added, b.submitted_by || null]);
    res.json({ ok: true });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// supplier removes a SKU they had added to the order (only removes supplier-added rows)
app.post('/api/supply/portal-line-remove', async (req, res) => {
  const b = req.body || {};
  if (!b.po || !b.sku) return res.status(400).json({ error: 'po and sku required' });
  try { await pool.query(`DELETE FROM planner.portal_line_costs WHERE po=$1 AND sku=$2 AND is_added=true`, [b.po, b.sku]); res.json({ ok: true }); }
  catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// SKUs assignable by a supplier (from products.supplier_multiple_all) — for the portal "add SKU" picker
app.get('/api/supply/supplier-skus/:supplier', async (req, res) => {
  try { res.json(await qp(`SELECT sku, coalesce(product_name_final,product_name,'') product_name,
      coalesce(product_ean,'') ean, coalesce(carton_qty::text,'') carton_qty, coalesce(size_long,'') size_long,
      coalesce(colour_long,'') colour, coalesce(release_window,'') release_window
    FROM planner.products WHERE coalesce(supplier_multiple_all,'') ILIKE '%'||$1||'%' AND coalesce(sku,'')<>'' ORDER BY sku`, [req.params.supplier])); }
  catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Internal (PO PLAN) sets the FINAL agreed cost price per line (the value that would push to ERP). Upserts onto
// the same portal_line_costs row so supplier-submitted (actual_cost) and D&B-final (final_cost) sit side by side.
app.post('/api/supply/po-line-final', async (req, res) => {
  const b = req.body || {};
  if (!b.po || !b.sku) return res.status(400).json({ error: 'po and sku required' });
  try {
    const cost = (b.final_cost === '' || b.final_cost == null) ? null : Number(b.final_cost);
    // A D&B-entered final cost IS the agreed price → stamp confirmed_at so the push / ERP verify use it
    // (both coalesce final_cost only WHEN confirmed_at IS NOT NULL). Clearing it leaves confirmed_at as-is
    // (the coalesce ignores a null final_cost anyway and falls back to the plan cost_price).
    await pool.query(`INSERT INTO planner.portal_line_costs (po, sku, final_cost, submitted_at, confirmed_at)
      VALUES ($1,$2,$3::numeric, now(), CASE WHEN $3::numeric IS NULL THEN NULL ELSE now() END)
      ON CONFLICT (po, sku) DO UPDATE SET final_cost=excluded.final_cost,
        confirmed_at = CASE WHEN excluded.final_cost IS NOT NULL THEN now() ELSE planner.portal_line_costs.confirmed_at END`,
      [b.po, b.sku, cost]);
    res.json({ ok: true });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// PO PLAN order plan: D&B accepts a supplier-submitted change (cost / amended qty / added SKU). Confirms the line
// and, if no final price set yet, adopts the supplier's cost as the final. `all:true` accepts every unconfirmed line on the PO.
app.post('/api/supply/po-line-accept', async (req, res) => {
  const b = req.body || {};
  if (!b.po) return res.status(400).json({ error: 'po required' });
  if (!b.all && !b.sku) return res.status(400).json({ error: 'sku or all required' });
  // which portal_line_costs rows are we accepting? a single sku, or all unconfirmed on the PO.
  const scope = b.all
    ? `plc.po=$1 AND (plc.actual_cost IS NOT NULL OR plc.amended_qty IS NOT NULL OR plc.is_added=true) AND (plc.confirmed_at IS NULL OR plc.confirmed_at < plc.submitted_at)`
    : `plc.po=$1 AND plc.sku=$2`;
  const params = b.all ? [b.po] : [b.po, b.sku];
  try {
    // 1) write accepted qty + cost onto EXISTING order-plan lines (qty<>erp_qty / cost<>erp_cost → flags ERP push)
    await pool.query(`UPDATE planner.purchase_order_lines pol SET
        qty = coalesce(round(plc.amended_qty)::int, pol.qty),
        cost_price = coalesce(plc.final_cost, plc.actual_cost, pol.cost_price),
        proposed_at = now(), proposed_by = 'order-plan accept'
      FROM planner.portal_line_costs plc
      WHERE pol.po=plc.po AND pol.sku=plc.sku AND ${scope}`, params);
    // 2) insert supplier-ADDED SKUs that aren't yet order-plan lines (erp_qty=0 → new to ERP)
    await pool.query(`INSERT INTO planner.purchase_order_lines (po_sku, po, sku, qty, erp_qty, cost_price, proposed_at, proposed_by)
      SELECT plc.po||'|'||plc.sku, plc.po, plc.sku, coalesce(round(plc.amended_qty)::int,0), 0,
             coalesce(plc.final_cost, plc.actual_cost), now(), 'order-plan accept'
      FROM planner.portal_line_costs plc
      WHERE ${scope} AND plc.is_added=true
        AND NOT EXISTS (SELECT 1 FROM planner.purchase_order_lines x WHERE x.po=plc.po AND x.sku=plc.sku)`, params);
    // 3) mark the portal lines confirmed; adopt supplier cost as final if none set
    await pool.query(`UPDATE planner.portal_line_costs plc SET confirmed_at=now(), final_cost=coalesce(plc.final_cost, plc.actual_cost) WHERE ${scope}`, params);
    res.json({ ok: true });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// PO PLAN order plan: D&B REJECTS a supplier-submitted change — discard it WITHOUT touching the order-plan line.
// Added-SKU proposals are removed outright; qty/cost amendments are cleared and marked reviewed (confirmed_at=now)
// so they stop showing as pending. `all:true` rejects every unconfirmed change on the PO.
app.post('/api/supply/po-line-reject', async (req, res) => {
  const b = req.body || {};
  if (!b.po) return res.status(400).json({ error: 'po required' });
  if (!b.all && !b.sku) return res.status(400).json({ error: 'sku or all required' });
  const scope = b.all
    ? `po=$1 AND (actual_cost IS NOT NULL OR amended_qty IS NOT NULL OR is_added=true) AND (confirmed_at IS NULL OR confirmed_at < submitted_at)`
    : `po=$1 AND sku=$2`;
  const params = b.all ? [b.po] : [b.po, b.sku];
  try {
    await pool.query(`DELETE FROM planner.portal_line_costs WHERE ${scope} AND is_added=true`, params);
    await pool.query(`UPDATE planner.portal_line_costs SET amended_qty=NULL, actual_cost=NULL, confirmed_at=now() WHERE ${scope}`, params);
    res.json({ ok: true });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
