app.get('/api/product/items', async (_req, res) => {
  try {
    const r = await pool.query(`SELECT i.id, i.ref, coalesce(i.type,'Product Development') type, coalesce(i.season,'') season, coalesce(i.category,'') category,
      coalesce(i.colour_name,'') colour_name, coalesce(i.supplier,'') supplier, coalesce(i.description,'') description, i.status, (i.swatch IS NOT NULL) has_swatch,
      to_char(i.updated_at,'YYYY-MM-DD HH24:MI') updated_at,
      (SELECT count(*) FROM planner.product_dev_sizes s WHERE s.item_id=i.id)::int sizes,
      (SELECT count(*) FROM planner.product_dev_sizes s WHERE s.item_id=i.id AND s.approval_status='approved')::int sizes_approved,
      (SELECT count(*) FROM planner.product_dev_sizes s WHERE s.item_id=i.id AND s.approval_status='approved' AND coalesce(s.mapped_sku,'')='')::int sizes_unmapped,
      -- required components with approval still pending/rejected (per size × component)
      (SELECT count(*) FROM planner.product_dev_size_dimensions sd JOIN planner.product_dev_sizes s ON s.id=sd.size_id WHERE s.item_id=i.id AND sd.dimension='product'   AND sd.required AND coalesce(sd.approval_status,'pending')<>'approved')::int comp_product,
      (SELECT count(*) FROM planner.product_dev_size_dimensions sd JOIN planner.product_dev_sizes s ON s.id=sd.size_id WHERE s.item_id=i.id AND sd.dimension='packaging' AND sd.required AND coalesce(sd.approval_status,'pending')<>'approved')::int comp_packaging,
      (SELECT count(*) FROM planner.product_dev_size_dimensions sd JOIN planner.product_dev_sizes s ON s.id=sd.size_id WHERE s.item_id=i.id AND sd.dimension='labels'    AND sd.required AND coalesce(sd.approval_status,'pending')<>'approved')::int comp_labels,
      (SELECT count(*) FROM planner.product_dev_size_dimensions sd JOIN planner.product_dev_sizes s ON s.id=sd.size_id WHERE s.item_id=i.id AND sd.dimension='polybag'   AND sd.required AND coalesce(sd.approval_status,'pending')<>'approved')::int comp_polybag,
      (SELECT count(*) FROM planner.product_dev_size_dimensions sd JOIN planner.product_dev_sizes s ON s.id=sd.size_id WHERE s.item_id=i.id AND sd.dimension='other'     AND sd.required AND coalesce(sd.approval_status,'pending')<>'approved')::int comp_other,
      -- status misaligned: every size is approved but the item status isn't 'approved' (still in development / rejected)
      (CASE WHEN i.status<>'approved'
              AND (SELECT count(*) FROM planner.product_dev_sizes s WHERE s.item_id=i.id)>0
              AND NOT EXISTS (SELECT 1 FROM planner.product_dev_sizes s WHERE s.item_id=i.id AND coalesce(s.approval_status,'')<>'approved')
            THEN 1 ELSE 0 END)::int status_misaligned,
      (SELECT count(*) FROM planner.supplier_notes n WHERE n.po=i.ref AND n.author_kind='supplier' AND n.read_at IS NULL)::int unread_supplier,
      coalesce((SELECT json_agg(DISTINCT jsonb_build_object('ref',sr.ref,'carrier',coalesce(sr.carrier,''),'tracking',coalesce(sr.tracking_code,'')))
        FROM planner.product_dev_samples ps
        JOIN planner.sample_request_dev_samples l ON l.dev_sample_id=ps.id
        JOIN planner.sample_requests sr ON sr.id=l.sample_request_id
        WHERE ps.item_ref=i.ref),'[]'::json) shipments,
      (SELECT jsonb_build_object('id',sr.id,'ref',sr.ref,'carrier',coalesce(sr.carrier,''),'tracking',coalesce(sr.tracking_code,''))
        FROM planner.product_dev_samples ps
        JOIN planner.sample_request_dev_samples l ON l.dev_sample_id=ps.id
        JOIN planner.sample_requests sr ON sr.id=l.sample_request_id
        WHERE ps.item_ref=i.ref ORDER BY sr.created_at DESC LIMIT 1) latest_shipment
      FROM planner.product_dev_items i ORDER BY i.created_at DESC`);
    res.json(r.rows);
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// PRODUCT ▸ DASHBOARD — approval matrix: one row per product with per-component-type {required, approved} counts.
app.get('/api/product/dashboard', async (req, res) => {
  try {
    const r = await pool.query(`SELECT i.ref, coalesce(i.season,'') season, coalesce(i.category,'') category,
      coalesce(i.colour_name,'') colour_name, i.status, (i.swatch IS NOT NULL) has_swatch,
      to_char(i.updated_at,'YYYY-MM-DD HH24:MI') updated_at,
      (SELECT count(*) FROM planner.product_dev_sizes s WHERE s.item_id=i.id)::int sizes,
      coalesce((SELECT json_object_agg(dimension, json_build_object('req',req,'appr',appr)) FROM (
        SELECT sd.dimension,
               count(*) FILTER (WHERE sd.required)::int req,
               count(*) FILTER (WHERE sd.required AND coalesce(sd.approval_status,'pending')='approved')::int appr
        FROM planner.product_dev_size_dimensions sd JOIN planner.product_dev_sizes s ON s.id=sd.size_id
        WHERE s.item_id=i.id GROUP BY sd.dimension) t),'{}'::json) comps
      FROM planner.product_dev_items i ORDER BY i.category, i.ref`);
    res.json(r.rows);
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
app.get('/api/product/item/:ref', async (req, res) => {
  const ref = req.params.ref;
  try {
    // Round 1 — item + sizes + docs + samples + unread all in parallel (sizes uses a subquery so it needn't wait on item)
    const [itemR, sizesR, docsR, samplesR, unreadR] = await Promise.all([
      pool.query(`SELECT id, ref, coalesce(type,'Product Development') type, coalesce(season,'') season, coalesce(category,'') category,
        coalesce(category_code,'') category_code, coalesce(colour_name,'') colour_name, coalesce(description,'') description, coalesce(recipient_countries,'UK') recipient_countries,
        coalesce(supplier,'') supplier, coalesce(supplier_code,'') supplier_code,
        status, (swatch IS NOT NULL) has_swatch, coalesce(created_by,'') created_by,
        to_char(created_at,'YYYY-MM-DD HH24:MI') created_at, to_char(updated_at,'YYYY-MM-DD HH24:MI') updated_at,
        to_char(dev_start_override,'YYYY-MM-DD') dev_start_override, to_char(approved_at,'YYYY-MM-DD HH24:MI') approved_at,
        coalesce(approval_method,'') approval_method
        FROM planner.product_dev_items WHERE ref=$1`, [ref]),
      pool.query(`SELECT id, coalesce(size_label,'') size_label, approval_status, sort, coalesce(mapped_sku,'') mapped_sku, approved_sample_id
        FROM planner.product_dev_sizes WHERE item_id=(SELECT id FROM planner.product_dev_items WHERE ref=$1) ORDER BY sort, id`, [ref]),
      pool.query(`SELECT id, filename, mime, byte_size, coalesce(uploaded_by,'') uploaded_by, coalesce(uploader_kind,'internal') uploader_kind, to_char(uploaded_at,'YYYY-MM-DD HH24:MI') uploaded_at FROM planner.portal_attachments WHERE po=$1 AND category='product' ORDER BY uploaded_at DESC`, [ref]),
      pool.query(`SELECT ps.id, ps.version, coalesce(ps.dimension,'product') dimension,
        CASE WHEN coalesce(ps.dimension,'product')='product' THEN ps.item_ref||'_v'||ps.version ELSE ps.item_ref||'_'||ps.dimension||'_v'||ps.version END ref,
        coalesce(ps.sample_sizes,'{}') sample_sizes, coalesce(ps.sampled_aspects,'{}') sampled_aspects, coalesce(ps.admin_feedback,'') admin_feedback,
        coalesce((SELECT json_agg(jsonb_build_object('ref',sr.ref,'carrier',coalesce(sr.carrier,''),'tracking',coalesce(sr.tracking_code,'')) ORDER BY sr.ref)
          FROM planner.sample_request_dev_samples l JOIN planner.sample_requests sr ON sr.id=l.sample_request_id WHERE l.dev_sample_id=ps.id),'[]'::json) shipments
        FROM planner.product_dev_samples ps WHERE ps.item_ref=$1 ORDER BY ps.dimension, ps.version`, [ref]),
      pool.query(`SELECT count(*)::int n FROM planner.supplier_notes WHERE po=$1 AND author_kind='supplier' AND read_at IS NULL`, [ref]),
    ]);
    const item = itemR.rows[0];
    if (!item) return res.status(404).json({ error: 'not found' });
    const sizes = sizesR.rows, docs = docsR.rows, samples = samplesR.rows, unread_supplier = unreadR.rows[0].n;
    // Round 2 — sample files + component rows in parallel (each depends on round 1 ids)
    const [sfR, dimsR] = await Promise.all([
      samples.length ? pool.query(`SELECT po, id, filename, coalesce(mime,'') mime FROM planner.portal_attachments WHERE po = ANY($1) AND category='product_sample' ORDER BY uploaded_at`, [samples.map(s => 'PSAMPLE-' + s.id)]) : Promise.resolve({ rows: [] }),
      sizes.length ? pool.query(`SELECT id, size_id, dimension, required, coalesce(approval_status,'pending') approval_status, coalesce(description,'') description, coalesce(packaging_type,'') packaging_type, approved_sample_id FROM planner.product_dev_size_dimensions WHERE size_id = ANY($1)`, [sizes.map(s => s.id)]) : Promise.resolve({ rows: [] }),
    ]);
    { const byV = {}; sfR.rows.forEach(f => { (byV[f.po] = byV[f.po] || []).push({ id: f.id, filename: f.filename, mime: f.mime }); }); samples.forEach(s => { s.files = byV['PSAMPLE-' + s.id] || []; }); }
    const dims = dimsR.rows;
    if (dims.length) {   // Round 3 — component files
      const dfR = await pool.query(`SELECT po, id, filename, coalesce(mime,'') mime, version, coalesce(uploaded_by,'') uploaded_by, coalesce(uploader_kind,'internal') uploader_kind, to_char(uploaded_at,'YYYY-MM-DD HH24:MI') uploaded_at FROM planner.portal_attachments WHERE po = ANY($1) AND category='product_dim' ORDER BY version NULLS LAST, uploaded_at`, [dims.map(d => 'PDIM-' + d.id)]);
      const byDim = {}; dfR.rows.forEach(f => { const did = f.po.replace('PDIM-', ''); (byDim[did] = byDim[did] || []).push({ id: f.id, filename: f.filename, mime: f.mime, version: f.version, uploaded_by: f.uploaded_by, uploader_kind: f.uploader_kind, uploaded_at: f.uploaded_at }); });
      dims.forEach(d => { d.files = byDim[d.id] || []; });
    }
    const byS = {}; dims.forEach(d => { (byS[d.size_id] = byS[d.size_id] || []).push(d); });
    sizes.forEach(s => { s.dimensions = byS[s.id] || []; });
    res.json({ item, sizes, docs, samples, unread_supplier });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
