// DTC shipment details (supplier-entered in portal ▸ SHIPMENT). Upsert + a supplier timeline note so it shows on
// the PO timeline and lights the admin ✉ bell. entered_by/entered_at are kept from the first entry; updated_at moves.
app.post('/api/supply/dtc-shipment', async (req, res) => {
  const b = req.body || {}, po = (b.po || '').trim();
  if (!po) return res.status(400).json({ error: 'po required' });
  const num = v => (v === '' || v == null) ? null : Number(v);
  const cartons = (b.cartons === '' || b.cartons == null) ? null : parseInt(b.cartons, 10);
  const cbm = num(b.cbm), wt = num(b.gross_weight_kg), dims = (b.dimensions || '').trim() || null, by = (b.entered_by || '').trim() || null;
  try {
    const existed = (await pool.query(`SELECT 1 FROM planner.dtc_shipment_details WHERE po=$1`, [po])).rowCount > 0;
    await pool.query(`INSERT INTO planner.dtc_shipment_details (po, cartons, cbm, gross_weight_kg, dimensions, entered_by, entered_at, updated_at)
      VALUES ($1,$2,$3,$4,$5,$6,now(),now())
      ON CONFLICT (po) DO UPDATE SET cartons=excluded.cartons, cbm=excluded.cbm, gross_weight_kg=excluded.gross_weight_kg,
        dimensions=excluded.dimensions, entered_by=coalesce(planner.dtc_shipment_details.entered_by, excluded.entered_by), updated_at=now()`,
      [po, cartons, cbm, wt, dims, by]);
    const parts = [];
    if (cartons != null) parts.push(cartons + ' cartons');
    if (cbm != null) parts.push(cbm + ' CBM');
    if (wt != null) parts.push(wt + ' kg');
    if (dims) parts.push(dims);
    const noteBody = '📦 Shipment details ' + (existed ? 'updated' : 'added') + ': ' + (parts.join(' · ') || '(cleared)');
    const sr = await pool.query(`SELECT s.id FROM planner.purchase_orders po JOIN planner.suppliers s ON s.name=po.supplier_name WHERE po.po=$1`, [po]);
    const sid = (sr.rows[0] && sr.rows[0].id) || null;
    await pool.query(`INSERT INTO planner.supplier_notes (po, supplier_id, author_email, author_kind, body) VALUES ($1,$2,$3,'supplier',$4)`, [po, sid, by, noteBody]);
    res.json({ ok: true });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
app.post('/api/supply/portal-note', async (req, res) => {
  const b = req.body || {};
  if (!b.po || !String(b.body || '').trim()) return res.status(400).json({ error: 'po and body required' });
  try {
    // stamp the PO's supplier so the note shows in that supplier's portal thread (internal/PO-PLAN posts don't pass one)
    let sid = b.supplier_id || null;
    if (!sid) { const r = await pool.query(`SELECT s.id FROM planner.purchase_orders po JOIN planner.suppliers s ON s.name=po.supplier_name WHERE po.po=$1`, [b.po]); sid = (r.rows[0] && r.rows[0].id) || null; }
    const kind = b.author_kind || 'supplier';
    const email = kind === 'internal' ? internalAuthor(req, b.author_email) : (b.author_email || null);
    // Private (team-only) notes: internal notes that must NEVER reach the supplier portal. Mentions are
    // lowercased dockandbay.com emails tagged in the note; each is emailed once. Only internal notes can be private.
    const priv = kind === 'internal' && !!b.private;
    const mentions = priv && Array.isArray(b.mentions)
      ? Array.from(new Set(b.mentions.map(m => String(m || '').trim().toLowerCase()).filter(m => m.indexOf('@') > 0))) : [];
    const body = String(b.body).trim();
    await pool.query(`INSERT INTO planner.supplier_notes (po, supplier_id, author_email, author_kind, body, private, mentions) VALUES ($1,$2,$3,$4,$5,$6,$7)`,
      [b.po, sid, email, kind, body, priv, mentions.length ? mentions : null]);
    // Notify tagged teammates — one email each, immediately. Best-effort; never breaks the post.
    // `email` is returned so the UI can preview exactly what the teammate receives (essential for sandbox testing,
    // where no key means nothing is actually sent). `sandbox=true` → composed but not delivered.
    let mailed = [], preview = null;
    if (mentions.length) {
      try {
        const valid = (await pool.query(`SELECT lower(email) email FROM planner.app_permissions WHERE lower(email) = ANY($1)`, [mentions])).rows.map(r => r.email);
        const send = mentions.filter(m => valid.includes(m));
        const dropped = mentions.filter(m => !valid.includes(m));   // tagged but not a known D&B user
        if (send.length) {
          const who = email ? String(email).replace(/@dockandbay\.com$/i, '@') : 'A teammate';
          const link = PLANNER_URL + '/#/supply/purchase-orders/timeline/' + encodeURIComponent(b.po);   // deep-link straight to this PO's timeline
          const subject = who + ' tagged you on ' + b.po;
          const html = '<div style="font:14px/1.6 system-ui,-apple-system,sans-serif;color:#1a1a1a">'
            + '<p><b>' + escHtml(who) + '</b> tagged you in an internal note on <b>' + escHtml(b.po) + '</b>:</p>'
            + '<blockquote style="margin:10px 0;padding:8px 12px;border-left:3px solid #6366f1;background:#f5f3ff;color:#334155">' + escHtml(body) + '</blockquote>'
            + '<p style="margin-top:14px"><a href="' + link + '" style="color:#4f46e5">Open ' + escHtml(b.po) + ' in HORIZON &rarr;</a></p>'
            + '<p style="color:#94a3b8;font-size:12px">Internal note — not visible to the supplier. No reply needed here; respond on the PO timeline.</p></div>';
          const text = who + ' tagged you in an internal note on ' + b.po + ':\n\n' + body + '\n\nOpen ' + b.po + ' in HORIZON: ' + link
            + '\n\nInternal note — not visible to the supplier. No reply needed here; respond on the PO timeline.';
          const r = await sendResendEmail({ to: send, subject, html, kind: 'mention', ref: b.po, by: email });
          mailed = r && r.sandbox ? [] : send;
          if (r && r.sandbox) console.log('[mention] sandbox — would email ' + send.join(', '));
          preview = { to: send, subject, text, sent: !(r && r.sandbox), dropped };
        } else if (dropped.length) {
          preview = { to: [], subject: '', text: '', sent: false, dropped };
        }
      } catch (e) { console.error('[mention] email failed:', e.message); }
    }
    res.json({ ok: true, mentions, mailed, email: preview, sandbox: IS_SANDBOX });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
