// Payment run header — bank / currency / bank amount / FX for a date-grouped run (upsert).
app.post('/api/supply/run-meta/:date', async (req, res) => {
  const allowed = { bank: 'text', paid_currency: 'text', bank_amount: 'numeric', fx_rate: 'numeric' };
  const cols = ['run_date'], vals = [req.params.date], ph = ['$1::date']; let i = 2;
  for (const k of Object.keys(req.body || {})) {
    if (!allowed[k]) continue;
    cols.push(k); vals.push(req.body[k] === '' ? null : req.body[k]); ph.push(`$${i++}::${allowed[k]}`);
  }
  if (cols.length === 1) return res.status(400).json({ error: 'no fields' });
  const upd = cols.slice(1).map(c => `${c}=excluded.${c}`).join(',');
  try {
    await pool.query(`INSERT INTO planner.payment_run_meta (${cols.join(',')}) VALUES (${ph.join(',')})
      ON CONFLICT (run_date) DO UPDATE SET ${upd}, updated_at=now()`, vals);
    res.json({ ok: true });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Order-plan line qty edit — sets our planned qty and stamps proposed_at/by while it differs from
// the ERP source of truth (erp_qty). Clears the stamp if the edit returns it to the ERP value.
app.post('/api/supply/po-line/:po_sku', async (req, res) => {
  const b = req.body || {};
  if (b.qty === undefined) return res.status(400).json({ error: 'qty required' });
  const key = req.params.po_sku;
  const po = b.po || key.split('|')[0];
  const sku = b.sku || key.slice(key.indexOf('|') + 1);
  try {
    const qn = parseInt(b.qty, 10);
    // Snapshot the prior qty so we can log the exact change (SKU + old → new) on the PO timeline (record of change).
    const _prevQ = (() => { const p = req.body._prevqty; return (p === undefined || p === null || p === '') ? null : (parseInt(p, 10) || 0); })();
    const _oldQ = _prevQ != null ? _prevQ : (Number((await pool.query(`SELECT qty FROM planner.purchase_order_lines WHERE po_sku=$1`, [key])).rows[0]?.qty) || 0);
    let r;
    if (!qn) {   // qty 0 (or blank/NaN) → REMOVE the SKU from the order plan entirely (don't keep a 0-qty line)
      r = await pool.query(`DELETE FROM planner.purchase_order_lines WHERE po_sku=$1`, [key]);
    } else {
      // upsert: editing a blank cell (no existing line) creates a proposed line (erp_qty=0 → pending).
      r = await pool.query(
        `INSERT INTO planner.purchase_order_lines (po_sku, po, sku, qty, proposed_at, proposed_by)
         VALUES ($1,$2,$3,$4::int, CASE WHEN $4::int<>0 THEN now() END, CASE WHEN $4::int<>0 THEN $5 END)
         ON CONFLICT (po_sku) DO UPDATE SET qty=excluded.qty,
           proposed_at = CASE WHEN excluded.qty IS DISTINCT FROM coalesce((SELECT el.qty FROM planner.erp_purchase_order_lines el WHERE el.po=planner.purchase_order_lines.po AND el.sku=planner.purchase_order_lines.sku),0) THEN now() ELSE NULL END,
           proposed_by = CASE WHEN excluded.qty IS DISTINCT FROM coalesce((SELECT el.qty FROM planner.erp_purchase_order_lines el WHERE el.po=planner.purchase_order_lines.po AND el.sku=planner.purchase_order_lines.sku),0) THEN $5 ELSE NULL END`,
        [key, po, sku, b.qty, b.who || 'review_ui']);
    }
    // If this materially changes an order the supplier had already confirmed, invalidate that approval so they
    // must re-confirm, and drop a timeline note (deduped). approved_lines is the snapshot from their last confirm.
    try {
      const st = (await pool.query(`SELECT supplier_confirmed_at IS NOT NULL confirmed, coalesce(approved_lines->>$2,'') appr FROM planner.purchase_orders WHERE po=$1`, [po, sku])).rows[0];
      if (st && st.confirmed) {
        const newQ = String(parseInt(b.qty, 10) || 0), oldQ = String(parseInt(st.appr, 10) || 0);
        if (newQ !== oldQ) {
          await pool.query(`UPDATE planner.purchase_orders SET supplier_confirmed_at=NULL, supplier_confirmed_by=NULL WHERE po=$1`, [po]);
          await notePoEdited(pool, po, authUser(req));
        }
      }
    } catch (e) { /* confirmation reset / note is best-effort — never block the plan edit */ }
    // Record of change: log the order-plan line edit (added / removed / qty old→new) on the PO timeline.
    const _newQ = qn || 0;
    if (_oldQ !== _newQ) {
      const detail = _oldQ === 0 ? (sku + ' added — qty ' + _newQ.toLocaleString('en-GB'))
        : _newQ === 0 ? (sku + ' removed (was ' + _oldQ.toLocaleString('en-GB') + ')')
        : (sku + ' qty ' + _oldQ.toLocaleString('en-GB') + ' → ' + _newQ.toLocaleString('en-GB'));
      logPoChange(po, 'Order plan', detail, authUser(req) || b.who || null);
    }
    res.json({ updated: r.rowCount });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// ── Pallet rebalance: even a production's open POs toward 20 pallets each (one container). Pools all line
// qty across the same supplier+production's open, UNSHIPPED, non-Direct POs and first-fit packs into the
// same POs at ≤20 pallets, moving whole SKUs and splitting a SKU's qty across POs when needed. Returns a
// preview (bins + per-line deltas); apply writes the new line quantities as proposed (not-in-ERP until Upload).
async function rebalancePlan(rootPo) {
  const REBAL_MAX = 20;
  const head = (await pool.query(`SELECT coalesce(supplier_name,'') supplier_name, coalesce(prod_no,'') prod_no, coalesce(branch,'') branch FROM planner.purchase_orders WHERE po=$1`, [rootPo])).rows[0];
  if (!head) throw new Error('PO not found');
  if (!head.prod_no) throw new Error('this PO has no production (PROD#) — rebalance works within a production');
  if (!head.branch) throw new Error('this PO has no branch (destination) — rebalance needs a destination');
  // Same supplier + production + BRANCH (same destination — you can't move stock between markets), open &
  // unshipped, not Direct-to-Client. Branch is the exact destination, so a container's POs all share one.
  const group = (await pool.query(`
    SELECT po.po, upper(coalesce(nullif(po.country_code,''), b.country_code, '')) ctry
    FROM planner.purchase_orders po LEFT JOIN planner.branches b ON b.name=po.branch
    WHERE coalesce(po.supplier_name,'')=$1 AND coalesce(po.prod_no,'')=$2 AND coalesce(po.branch,'')=$3
      AND coalesce(po.status,'') NOT ILIKE '%complete%' AND coalesce(po.status,'') NOT ILIKE 'ship%'
      AND coalesce(po.status,'') NOT ILIKE '%deliver%'
    ORDER BY po.po`, [head.supplier_name, head.prod_no, head.branch])).rows.filter(r => r.ctry !== 'DIRECT');
  if (group.length < 2) throw new Error('need 2+ open, unshipped, non-Direct POs in this production + destination to rebalance');
  const pos = group.map(g => g.po);
  const lines = (await pool.query(`
    SELECT l.po, l.sku, coalesce(l.qty,0) qty, coalesce(sl.pallet_qty,0) pallet_qty
    FROM planner.purchase_order_lines l LEFT JOIN planner.v_sku_attrs sl ON sl.sku=l.sku
    WHERE l.po = ANY($1)`, [pos])).rows;
  const cur = {}; pos.forEach(p => cur[p] = {});
  const palq = {};
  lines.forEach(l => { cur[l.po][l.sku] = (cur[l.po][l.sku] || 0) + Number(l.qty); palq[l.sku] = Number(l.pallet_qty) || 0; });
  // MINIMAL-MOVE smoothing: start from the current layout and move only the EXCESS off any >20 PO into the
  // POs with spare capacity (whole or partial SKUs) — least disruption, not a full repack.
  const next = {}; pos.forEach(p => { next[p] = {}; for (const s in cur[p]) next[p][s] = cur[p][s]; });
  const EPS = 1e-6;
  const pal = (po) => { let t = 0; for (const s in next[po]) if (palq[s] > 0) t += next[po][s] / palq[s]; return t; };
  let guard = 0;
  pos.filter(p => pal(p) > REBAL_MAX + EPS).forEach(d => {
    while (pal(d) > REBAL_MAX + EPS && guard++ < 20000) {
      let r = null, best = EPS; pos.forEach(p => { if (p !== d) { const f = REBAL_MAX - pal(p); if (f > best) { best = f; r = p; } } });
      if (!r) break;                                   // no spare capacity anywhere → leave the overflow (flagged)
      const moveP = Math.min(pal(d) - REBAL_MAX, REBAL_MAX - pal(r));
      if (moveP <= EPS) break;
      let s = null, bq = 0; for (const k in next[d]) { if (next[d][k] > 0 && palq[k] > 0 && next[d][k] > bq) { bq = next[d][k]; s = k; } }
      if (!s) break;                                   // nothing measurable to move
      let mv = Math.min(Math.round(moveP * palq[s]), next[d][s]);
      if (mv <= 0) mv = Math.min(1, next[d][s]);        // rounding floor → nudge 1 unit to make progress
      next[d][s] -= mv; next[r][s] = (next[r][s] || 0) + mv;
    }
  });
  const palOf = (m) => { let t = 0; for (const s in m) if (palq[s] > 0) t += m[s] / palq[s]; return Math.round(t * 10) / 10; };
  const bins = pos.map(p => ({ po: p, was_pallets: palOf(cur[p]), pallets: palOf(next[p]),
    lines: Array.from(new Set([...Object.keys(cur[p]), ...Object.keys(next[p])])).map(s => ({ sku: s, old: cur[p][s] || 0, new: next[p][s] || 0 })).filter(x => x.old || x.new) }));
  const moves = []; bins.forEach(bn => bn.lines.forEach(l => { if (l.old !== l.new) moves.push({ po: bn.po, sku: l.sku, old: l.old, new: l.new }); }));
  return { supplier: head.supplier_name, prod_no: head.prod_no, target: REBAL_MAX, bins, moves, overflow: bins.some(bn => bn.pallets > REBAL_MAX + 1e-9) };
}
app.get('/api/supply/rebalance/:po', async (req, res) => {
  try { res.json(await rebalancePlan(req.params.po)); } catch (e) { res.status(400).json({ error: e.message }); }
});
app.post('/api/supply/rebalance-apply/:po', async (req, res) => {
  try {
    const plan = await rebalancePlan(req.params.po);
    for (const m of plan.moves) {
      await pool.query(
        `INSERT INTO planner.purchase_order_lines (po_sku, po, sku, qty, erp_qty, proposed_at, proposed_by)
         VALUES ($1,$2,$3,$4::int, 0, CASE WHEN $4::int<>0 THEN now() END, CASE WHEN $4::int<>0 THEN 'rebalance' END)
         ON CONFLICT (po_sku) DO UPDATE SET qty=excluded.qty,
           proposed_at = CASE WHEN excluded.qty IS DISTINCT FROM planner.purchase_order_lines.erp_qty THEN now() ELSE NULL END,
           proposed_by = CASE WHEN excluded.qty IS DISTINCT FROM planner.purchase_order_lines.erp_qty THEN 'rebalance' ELSE NULL END`,
        [m.po + '|' + m.sku, m.po, m.sku, m.new]);
    }
    res.json({ applied: plan.moves.length, bins: plan.bins.map(b => ({ po: b.po, pallets: b.pallets })) });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Per-SKU supplier resolution for BUY→PO: main supplier (default) + all options (multi-supplier) + pallet_qty.
// Supplier name→code via suppliers.name (exact, case-insensitive) then first-word fallback (handles "MQ Print
// (Sherry)" → MQ etc.). main_supplier_final is the default; supplier_multiple_all lists every option.
async function buyplanSkuMeta(skus) {
  const sups = (await pool.query(`SELECT code, name FROM planner.suppliers WHERE code IS NOT NULL`)).rows;
  const byName = {}, byFirst = {};
  sups.forEach(s => { const n = String(s.name || '').trim().toLowerCase(); if (!n) return; byName[n] = s.code;
    const f = n.split(/\s+/)[0]; if (!(f in byFirst)) byFirst[f] = s.code; });
  const codeOf = (name) => { if (!name) return null; const n = String(name).trim().toLowerCase(); return byName[n] || byFirst[n.split(/\s+/)[0]] || null; };
  const rows = (await pool.query(`SELECT upper(p.sku) sku, coalesce(p.main_supplier_final, p.supplier) main_name,
      p.supplier_multiple_all multi, coalesce(p.category,'') category, sl.pallet_qty, p.moq,
      nullif(p.discontinue_date_final,'') disc, nullif(p.discontinue_date_au_final,'') disc_au, nullif(p.discontinue_date_ca,'') disc_ca
    FROM planner.products p LEFT JOIN planner.v_sku_attrs sl ON upper(sl.sku)=upper(p.sku)
    WHERE upper(p.sku) = ANY($1)`, [skus])).rows;
  const map = {};
  rows.forEach(r => {
    const names = (r.multi ? String(r.multi).split(',') : []).map(x => x.trim()).filter(Boolean);
    if (r.main_name && !names.some(x => x.toLowerCase() === String(r.main_name).trim().toLowerCase())) names.unshift(r.main_name);
    const seen = {}, options = [];
    names.forEach(nm => { const c = codeOf(nm); const k = c || nm.toLowerCase(); if (!seen[k]) { seen[k] = 1; options.push({ code: c, name: nm }); } });
    map[r.sku] = { pallet_qty: Number(r.pallet_qty) || 0, category: r.category || '', main_code: codeOf(r.main_name), main_name: r.main_name || '', options,
      moq: (Number(r.moq) > 0 ? Number(r.moq) : null), disc: r.disc || '', disc_au: r.disc_au || '', disc_ca: r.disc_ca || '' };
  });
  return map;
}
// BUY PLAN → PURCHASE ORDERS. Take buy-plan items (each may carry an explicit supplier_code chosen in the UI,
// else the SKU's main supplier), group by supplier and split into proposed POs of ≤20 pallets each (pallets =
// qty ÷ sku_labels.pallet_qty — 20 ≈ a container). Reference = PO-{prod#}{COUNTRY}{supplier-code}{counter}.
// Dry-run by default (returns the split + any SKUs that can't be placed); commit:true inserts proposed lines
// (erp_qty=0, flagged 'not in ERP' until Diviyaj's Upload). Assigns prod_no + start_production + country.
app.post('/api/supply/buyplan-pos', async (req, res) => {
  const b = req.body || {}, MAXPAL = 20;
  const prod = (b.prod_no || '').trim(), country = (b.country || '').trim().toUpperCase();
  const startDate = (b.start_date || '').trim() || null;
  const batchId = (b.batch_id || '').trim() || null;   // optional buying-batch tag applied to every created PO
  const codes = (Array.isArray(b.supplier_codes) ? b.supplier_codes : []).map(c => String(c).toUpperCase()).filter(Boolean);
  const items = (Array.isArray(b.items) ? b.items : []).filter(it => it && it.sku && Number(it.qty) > 0);
  const commit = !!b.commit;
  const mode = b.mode === 'fba' ? 'fba' : '3pl';   // FBA-direct vs 3PL — drives the default branch
  // default branch by channel × destination (must match planner.branches.name)
  const FBA_BR = { UK: 'UK FBA', US: 'US FBA', CA: 'CA FBA', AU: 'AU FBA', EU: 'DE FBA' };   // EU FBA → DE FBA
  const TPL_BR = { UK: 'UK ILG', US: 'US Geneva', EU: 'EU iFulfillment', AU: 'AU Coghlans', CA: 'CA FBA' };   // CA always → CA FBA (no CA 3PL)
  const branch = (b.branch ? String(b.branch).trim() : (mode === 'fba' ? FBA_BR : TPL_BR)[country]) || null;   // explicit branch override (e.g. 'China Stock' holding-branch for the MOQ top-up PO)
  if (mode === 'fba' && country === 'EU' && !b.branch) return res.status(400).json({ error: 'FBA-direct PO creation is not available for EU yet (no DE FBA branch).' });
  if (!prod || !country || !items.length) return res.status(400).json({ error: 'prod_no, country and items required' });
  const num = (prod.match(/\d+/) || [prod])[0];   // 'P54' -> '54'
  try {
    const skus = items.map(it => String(it.sku).toUpperCase());
    const mmap = await buyplanSkuMeta(skus);
    const warn = [], bySup = {};
    for (const it of items) { const sku = String(it.sku).toUpperCase(), m = mmap[sku] || { options: [] };
      // chosen supplier: explicit per-item supplier_code from the UI, else the SKU's main supplier
      const code = (it.supplier_code ? String(it.supplier_code).toUpperCase() : (m.main_code || '')).toUpperCase();
      if (!code) { warn.push({ sku, issue: 'no supplier code (supplier "' + (m.main_name || '?') + '")' }); continue; }
      if (codes.length && !codes.includes(code)) continue;     // supplier not ticked in scope (when codes given)
      const pq = Number(m.pallet_qty) || 0;   // no pallet_qty → still included, just counts as 0 pallets in the split
      const opt = (m.options || []).find(o => o.code === code);
      const supName = opt ? opt.name : (m.main_name || '');
      (bySup[code] = bySup[code] || []).push({ sku, qty: Math.round(Number(it.qty)), pallet_qty: pq, sup_name: supName }); }
    const pos = [];
    for (const code of Object.keys(bySup).sort()) {
      const prefix = 'PO-' + num + country + code;
      const ex = (await pool.query(`SELECT po FROM planner.purchase_orders WHERE po LIKE $1`, [prefix + '%'])).rows;
      let maxc = 0; ex.forEach(r => { const m = r.po.slice(prefix.length).match(/^(\d+)/); if (m) maxc = Math.max(maxc, parseInt(m[1], 10)); });
      const bins = [];   // first-fit-decreasing; split a single SKU only if it alone exceeds 20 pallets
      const place = (sku, qty, pq) => {
        if (pq <= 0) { let bin = bins[0] || (bins[0] = { pallets: 0, lines: [] }); bin.lines.push({ sku, qty, pallets: 0 }); return; }  // no pallet_qty → ride along, 0 pallets
        let rem = qty;
        while (rem / pq > MAXPAL + 1e-9) { const take = MAXPAL * pq; bins.push({ pallets: MAXPAL, lines: [{ sku, qty: take, pallets: MAXPAL }] }); rem -= take; }
        if (rem <= 0) return;
        const lp = rem / pq; let bin = bins.find(bn => bn.pallets + lp <= MAXPAL + 1e-9);
        if (!bin) { bin = { pallets: 0, lines: [] }; bins.push(bin); }
        bin.lines.push({ sku, qty: rem, pallets: lp }); bin.pallets += lp; };
      const palOf = l => l.pallet_qty > 0 ? l.qty / l.pallet_qty : 0;
      bySup[code].slice().sort((a, b) => palOf(b) - palOf(a)).forEach(l => place(l.sku, l.qty, l.pallet_qty));
      const supName = bySup[code][0].sup_name;
      bins.forEach((bin, i) => pos.push({ po: prefix + (maxc + i + 1), supplier_code: code, supplier_name: supName,
        country, branch, prod_no: prod, start_production: startDate, pallets: Math.round(bin.pallets * 10) / 10,
        lines: bin.lines.map(x => ({ sku: x.sku, qty: x.qty, pallets: Math.round(x.pallets * 10) / 10 })) }));
    }
    if (!commit) return res.json({ preview: true, mode, branch, target_pallets: MAXPAL, pos, warnings: warn });
    // Resolve supplier_id (by code, fall back to name) so buy-plan POs land LINKED to the supplier. Without
    // this they carried only the name → no supplier lead time → no computable ETA → the inbound never showed
    // in the buy plan (e.g. PO-57UKLX5). The manual po-create path already did this; the buy-plan split didn't.
    const supRows = (await pool.query(`SELECT id, upper(coalesce(code,'')) code, lower(trim(coalesce(name,''))) name FROM planner.suppliers`)).rows;
    const supByCode = {}, supByName = {};
    supRows.forEach(s => { if (s.code) supByCode[s.code] = s.id; if (s.name) supByName[s.name] = s.id; });
    const supIdOf = (code, name) => supByCode[String(code || '').toUpperCase()] || supByName[String(name || '').trim().toLowerCase()] || null;
    let created = 0;
    for (const p of pos) {
      const insPo = await pool.query(`INSERT INTO planner.purchase_orders (po, supplier_name, supplier_id, prod_no, batch_id, country_code, branch, start_production, status)
        VALUES ($1,$2,$3,$4,$5,$6,$7,$8,'FUTURE') ON CONFLICT (po) DO NOTHING RETURNING po`, [p.po, p.supplier_name, supIdOf(p.supplier_code, p.supplier_name), prod, batchId, country, branch, startDate]);
      if (insPo.rowCount) await notePoCreated(pool, p.po, authUser(req));
      // China Stock top-up PO → flag the move on the PO timeline (units held un-allocated to meet MOQ; allocated manually later).
      if (insPo.rowCount && /china stock/i.test(String(branch || ''))) {
        const _u = p.lines.reduce((a, l) => a + (Number(l.qty) || 0), 0);
        try { await pool.query(`INSERT INTO planner.supplier_notes (po, supplier_id, author_email, author_kind, body) VALUES ($1,$2,$3,'internal',$4)`,
          [p.po, supIdOf(p.supplier_code, p.supplier_name), authUser(req) || null, '🏭 China Stock move — ' + _u.toLocaleString() + ' units held un-allocated to meet supplier MOQ; allocate to a market / order later']); } catch (e) { /* best-effort */ }
      }
      for (const l of p.lines)
        await pool.query(`INSERT INTO planner.purchase_order_lines (po_sku, po, sku, qty, erp_qty, proposed_at, proposed_by)
          VALUES ($1,$2,$3,$4::int,0,now(),'buyplan') ON CONFLICT (po_sku) DO UPDATE SET qty=excluded.qty, proposed_at=now(), proposed_by='buyplan'`,
          [p.po + '|' + l.sku, p.po, l.sku, l.qty]);
      created++;
    }
    invalidateSupplyCaches();   // new POs written → bump the epoch so the cached PO-rows / order-plan build rebuilds; otherwise the new POs don't show in Order Plan until the TTL / a hard refresh
    res.json({ committed: true, created, pos, warnings: warn });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Per-SKU supplier options for the BUY→PO dialog: each SKU's qty, pallet_qty, main supplier (default) and the
// full option list (multi-supplier). The UI shows a tick + supplier picker per SKU.
app.post('/api/supply/buyplan-skus', async (req, res) => {
  const items = (Array.isArray(req.body && req.body.items) ? req.body.items : []).filter(it => it && it.sku && Number(it.qty) > 0);
  if (!items.length) return res.json({ skus: [] });
  try {
    const map = await buyplanSkuMeta(items.map(it => String(it.sku).toUpperCase()));
    const ctry = String((req.body && req.body.country) || '').toUpperCase();
    const discFor = m => ctry === 'AU' ? (m.disc_au || m.disc || '') : ctry === 'CA' ? (m.disc_ca || m.disc || '') : (m.disc || '');
    res.json({ skus: items.map(it => { const sku = String(it.sku).toUpperCase(), m = map[sku] || { options: [] };
      return { sku, qty: Math.round(Number(it.qty)), pallet_qty: m.pallet_qty || 0, category: m.category || '', main_code: m.main_code || null,
        main_name: m.main_name || '', options: (m.options || []).map(o => ({ code: o.code, name: o.name })), moq: (m.moq || null), discontinue: discFor(m) }; }) });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Approve an order-plan exception on a line. field selects which: partial (default) → partial_carton_approved,
// supplier → supplier_risk_approved, discontinue → discontinue_approved.
app.post('/api/supply/po-line/:po_sku/approve', (req, res) => {
  const field = (req.body && req.body.field) || 'partial';
  const col = { partial: 'partial_carton_approved', supplier: 'supplier_risk_approved', discontinue: 'discontinue_approved', country: 'country_risk_approved' }[field];
  if (!col) return res.status(400).json({ error: 'unknown approve field' });
  const val = req.body && req.body.approved;
  return patch(res, 'planner.purchase_order_lines', 'po_sku', req.params.po_sku, { [col]: 'boolean' }, { [col]: val });
});
// "Upload changes" — push a PO's planned qtys to the ERP (Cin7/Fulfil). The actual ERP API write
// is a gated Diviyaj integration; here we record the push (erp_qty := qty) and log it, clearing the
// mismatch. Returns how many lines changed.
app.post('/api/supply/po/:po/upload', async (req, res) => {
  try {
    const r = await pool.query(
      `UPDATE planner.purchase_order_lines SET erp_qty=qty, erp_cost=cost_price, proposed_at=NULL, proposed_by=NULL
       WHERE po=$1 AND (erp_qty IS DISTINCT FROM qty OR cost_price IS DISTINCT FROM erp_cost)`,
      [req.params.po]);
    await pool.query(`INSERT INTO planner.etl_runs (job, status, rows_affected, message)
       VALUES ('supply_erp_push','pending',$1,$2)`,
      [r.rowCount, `${r.rowCount} line(s) staged to push to ERP (qty + cost) for ${req.params.po}`]);
    res.json({ uploaded: r.rowCount });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Delete a Purchase Order and its owned children (Master Data tab). Gated/confirmed in the UI.
app.post('/api/supply/po/:po/delete', async (req, res) => {
  const po = req.params.po;
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    // Never orphan children: a master PO can only be deleted once all its child POs are removed (Child PO tab).
    const kids = (await client.query(`SELECT count(*)::int n FROM planner.purchase_orders WHERE master_po=$1`, [po])).rows[0].n;
    if (kids > 0) { await client.query('ROLLBACK'); return res.status(409).json({ error: 'Cannot delete a master PO while ' + kids + ' child PO' + (kids > 1 ? 's are' : ' is') + ' assigned — remove them on the Child PO tab first' }); }
    await client.query('DELETE FROM planner.purchase_order_lines WHERE po=$1', [po]);
    await client.query('DELETE FROM planner.erp_purchase_order_lines WHERE po=$1', [po]);
    await client.query('DELETE FROM planner.erp_purchase_orders WHERE po=$1', [po]);
    await client.query('DELETE FROM planner.portal_attachments WHERE po=$1', [po]);
    await client.query('DELETE FROM planner.supplier_submissions WHERE po=$1', [po]);
    await client.query('DELETE FROM planner.supplier_notes WHERE po=$1', [po]);
    const r = await client.query('DELETE FROM planner.purchase_orders WHERE po=$1', [po]);
    await client.query('COMMIT');
    res.json({ deleted: r.rowCount });
  } catch (e) { await client.query('ROLLBACK'); log500(e); res.status(500).json({ error: e.message }); }
  finally { client.release(); }
});
// Resolve the Cin7 Authorization header from env — accepts EITHER form, so it's flexible:
//   • CIN7_AUTH = full header   → "Basic <base64>"      (used as-is)
//   • CIN7_AUTH = bare base64   → "<base64 of user:key>" (we prepend "Basic ")
//   • CIN7_USERNAME + CIN7_KEY  → we base64-encode "user:key" ourselves
// Returns null when nothing is configured (endpoints then no-op with 501).
function cin7Auth() {
  const a = (process.env.CIN7_AUTH || '').trim();
  if (a) return /^basic\s/i.test(a) ? a : ('Basic ' + a);
  const u = process.env.CIN7_USERNAME, k = process.env.CIN7_KEY;
  if (u && k) return 'Basic ' + Buffer.from(u + ':' + k).toString('base64');
  return null;
}
// Throttle + auto-retry for the Cin7 Omni API (rate limit ~3 req/sec). Every Cin7 call goes through here:
// calls are serialised with a minimum gap, and 429s are retried with backoff (honouring Retry-After). This
// keeps bulk pushes/lookups under Cin7's limit instead of getting rejected.
let _cin7LastCall = 0, _cin7Chain = Promise.resolve();
// Append one Cin7 call (request + response) to cin7-calls.jsonl for later analysis. Reads the response body
// from a CLONE so the caller's body is untouched. Best-effort — never throws into the request path.
function logCin7(url, opts, resp) {
  try {
    resp.clone().text().then(body => {
      const entry = { ts: new Date().toISOString(), method: (opts && opts.method) || 'GET', url,
        status: resp.status, req: (opts && opts.body) ? String(opts.body).slice(0, 4000) : undefined,
        resp: String(body || '').slice(0, 4000) };
      appendFile('cin7-calls.jsonl', JSON.stringify(entry) + '\n', () => {});
      console.log('[cin7] ' + entry.method + ' ' + resp.status + ' ' + String(url).replace('https://api.cin7.com/api/v1', '').slice(0, 90));
    }).catch(() => {});
  } catch (e) { /* never break the push over logging */ }
}
function cin7Fetch(url, opts) {
  const MIN_GAP = 400;   // ms between Cin7 calls → ~2.5/sec, safely under the 3/sec cap
  const run = async () => {
    const gap = MIN_GAP - (Date.now() - _cin7LastCall);
    if (gap > 0) await new Promise(r => setTimeout(r, gap));
    for (let attempt = 0; ; attempt++) {
      _cin7LastCall = Date.now();
      const resp = await fetch(url, opts);
      if (resp.status !== 429 || attempt >= 4) { logCin7(url, opts, resp); return resp; }
      logCin7(url, opts, resp);   // log the 429 too, then back off + retry
      const ra = Number(resp.headers.get('retry-after'));
      await new Promise(r => setTimeout(r, ra > 0 ? ra * 1000 : 1000 * (attempt + 1)));
    }
  };
  const p = _cin7Chain.then(run, run);   // chain so concurrent requests are serialised (single-instance server)
  _cin7Chain = p.catch(() => {});
  return p;
}
// Update the Cin7 PO's EstimatedDeliveryDate to the planner's Completion date (#14). LIVE write to Cin7 —
// gated: requires Cin7 creds (see cin7Auth). Safe no-op (501) when the credential is absent.
// MERGE PO 2 (from) into PO 1 (into): fold PO 2's SKU lines into PO 1 (matching SKUs sum their qty, new SKUs
// copy across with their cost), then delete PO 2 entirely (mirrors /delete). Only SKU + qty (+cost so the line
// stays valued) merge — supplier / dates / client / crossdock etc. are NOT merged. Guarded by `confirm`.
app.post('/api/supply/po/merge', async (req, res) => {
  const b = req.body || {}, into = (b.into || '').trim(), from = (b.from || '').trim();
  if (!into || !from) return res.status(400).json({ error: 'into + from PO required' });
  if (into === from) return res.status(400).json({ error: 'choose two different POs' });
  if (!b.confirm) return res.status(400).json({ error: 'confirmation required' });
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const chk = await client.query('SELECT po FROM planner.purchase_orders WHERE po = ANY($1)', [[into, from]]);
    const have = new Set(chk.rows.map(r => r.po));
    if (!have.has(into)) { await client.query('ROLLBACK'); return res.status(404).json({ error: `PO 1 (${into}) not found` }); }
    if (!have.has(from)) { await client.query('ROLLBACK'); return res.status(404).json({ error: `PO 2 (${from}) not found` }); }
    const fromLines = (await client.query('SELECT sku, coalesce(qty,0) qty, cost_price FROM planner.purchase_order_lines WHERE po=$1', [from])).rows;
    let summed = 0, copied = 0;
    for (const l of fromLines) {
      const key = into + '|' + l.sku;
      const upd = await client.query('UPDATE planner.purchase_order_lines SET qty = coalesce(qty,0) + $2, proposed_at = now() WHERE po_sku=$1', [key, l.qty]);
      if (upd.rowCount > 0) { summed++; }
      else {
        await client.query(`INSERT INTO planner.purchase_order_lines (po_sku, po, sku, qty, cost_price, proposed_at)
          VALUES ($1,$2,$3,$4,$5, now())
          ON CONFLICT (po_sku) DO UPDATE SET qty = coalesce(planner.purchase_order_lines.qty,0) + excluded.qty, proposed_at = now()`,
          [key, into, l.sku, l.qty, l.cost_price]);
        copied++;
      }
    }
    // delete PO 2 (same set of tables as /api/supply/po/:po/delete)
    await client.query('DELETE FROM planner.purchase_order_lines WHERE po=$1', [from]);
    await client.query('DELETE FROM planner.erp_purchase_order_lines WHERE po=$1', [from]);
    await client.query('DELETE FROM planner.erp_purchase_orders WHERE po=$1', [from]);
    await client.query('DELETE FROM planner.portal_attachments WHERE po=$1', [from]);
    await client.query('DELETE FROM planner.supplier_submissions WHERE po=$1', [from]);
    await client.query('DELETE FROM planner.supplier_notes WHERE po=$1', [from]);
    await client.query('DELETE FROM planner.purchase_orders WHERE po=$1', [from]);
    await client.query('COMMIT');
    res.json({ ok: true, into, from, lines: fromLines.length, summed, copied });
  } catch (e) { await client.query('ROLLBACK'); log500(e); res.status(500).json({ error: e.message }); }
  finally { client.release(); }
});
// BULK paste SKU/qty rows into a PO's order plan (Excel / Sheets paste). Each row is validated against our SKU
// list (planner.products ∪ sku_labels, case-insensitive → canonical SKU). Unknown SKUs are skipped. Existing
// SKUs on the PO have their qty overridden; new valid SKUs are added (proposed). qty 0 removes the line.
app.post('/api/supply/po-lines-paste', async (req, res) => {
  const b = req.body || {}, po = (b.po || '').trim(), rows = Array.isArray(b.rows) ? b.rows : [];
  const who = b.who || authUser(req) || 'PO PLAN paste';
  if (!po) return res.status(400).json({ error: 'po required' });
  if (!rows.length) return res.status(400).json({ error: 'no rows to import' });
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    if (!(await client.query('SELECT 1 FROM planner.purchase_orders WHERE po=$1', [po])).rowCount) {
      await client.query('ROLLBACK'); return res.status(404).json({ error: `PO ${po} not found` });
    }
    let added = 0, updated = 0; const skipped = [], badQty = [];
    for (const r of rows) {
      const raw = String(r.sku || '').trim();
      if (!raw) continue;
      const qty = parseInt(String(r.qty == null ? '' : r.qty).replace(/[^0-9-]/g, ''), 10);
      if (isNaN(qty)) { badQty.push(raw); continue; }
      const m = await client.query(
        `SELECT sku FROM planner.products WHERE upper(sku)=upper($1)
         UNION SELECT sku FROM planner.v_sku_attrs WHERE upper(sku)=upper($1) LIMIT 1`, [raw]);
      if (!m.rowCount) { skipped.push(raw); continue; }
      const sku = m.rows[0].sku, key = po + '|' + sku;
      const exists = (await client.query('SELECT 1 FROM planner.purchase_order_lines WHERE po_sku=$1', [key])).rowCount;
      if (qty === 0) { if (exists) { await client.query('DELETE FROM planner.purchase_order_lines WHERE po_sku=$1', [key]); updated++; } continue; }
      await client.query(
        `INSERT INTO planner.purchase_order_lines (po_sku, po, sku, qty, proposed_at, proposed_by)
         VALUES ($1,$2,$3,$4, now(), $5)
         ON CONFLICT (po_sku) DO UPDATE SET qty=excluded.qty, proposed_at=now(), proposed_by=excluded.proposed_by`,
        [key, po, sku, qty, who]);
      if (exists) updated++; else added++;
    }
    await client.query('COMMIT');
    res.json({ ok: true, po, added, updated, skipped, badQty });
  } catch (e) { await client.query('ROLLBACK'); log500(e); res.status(500).json({ error: e.message }); }
  finally { client.release(); }
});
app.post('/api/supply/po/:po/cin7-date', async (req, res) => {
  const po = req.params.po;
  const completion = ((req.body && req.body.completion_date) || '').trim();
  if (!completion) return res.status(400).json({ error: 'completion_date required' });
  if (await activeErp() === 'fulfil') {   // same process, Fulfil target
    try { const out = await fulfilSyncDate(po, completion);
      if (out.ok) { logPoChange(po, 'Uploaded to ERP', 'delivery date → ' + completion + ' (Fulfil)', authUser(req)); return res.json(out); }
      return res.status(out.missing ? 404 : 502).json({ error: out.error }); }
    catch (e) { return res.status(e.code === 'NO_FULFIL_CFG' ? 501 : 502).json({ error: e.message }); }
  }
  try {
    const row = (await pool.query('SELECT erp_po_id FROM planner.erp_purchase_orders WHERE po=$1', [po])).rows[0];
    const cin7Id = row && row.erp_po_id;
    if (!cin7Id) return res.status(404).json({ error: 'No Cin7 PO id (erp_po_id) found for ' + po + ' — sync the ERP mirror first.' });
    const auth = cin7Auth();
    if (!auth) return res.status(501).json({ error: 'Cin7 API credentials not configured (set CIN7_AUTH). No write performed.' });
    const edd = /T/.test(completion) ? completion : (completion + 'T00:00:00Z');
    // preserve the PO's CURRENT approval state — read isApproved first and echo it, so a date update never
    // flips a draft to approved. If we can't read it, omit isApproved entirely (Cin7 leaves it unchanged on PUT).
    let curApproved;
    try {
      const g = await cin7Fetch('https://api.cin7.com/api/v1/PurchaseOrders?rows=1&fields=id,isApproved&where=' + encodeURIComponent('id=' + cin7Id),
        { headers: { Authorization: auth, 'content-type': 'application/json' } });
      if (g.ok) { const arr = await g.json(); if (Array.isArray(arr) && arr[0] && typeof arr[0].isApproved === 'boolean') curApproved = arr[0].isApproved; }
    } catch (e) { /* fall through — omit isApproved */ }
    const upd = { id: Number(cin7Id) || cin7Id, estimatedDeliveryDate: edd };
    if (curApproved !== undefined) upd.isApproved = curApproved;
    const body = [upd];
    const r = await cin7Fetch('https://api.cin7.com/api/v1/PurchaseOrders?loadboms=false',
      { method: 'PUT', headers: { Authorization: auth, 'content-type': 'application/json' }, body: JSON.stringify(body) });
    const txt = await r.text();
    if (!r.ok) return res.status(502).json({ error: 'Cin7 API error ' + r.status + ': ' + txt.slice(0, 300) });
    // optimistically sync the local ERP mirror so the "Date ≠ ERP" flag clears immediately (n8n re-confirms later)
    let mirrored = false;
    try { const u = await pool.query(`UPDATE planner.erp_purchase_orders SET final_delivery_date=$2::date, synced_at=now() WHERE po=$1`, [po, completion]); mirrored = u.rowCount > 0; } catch (e) { /* non-fatal — Cin7 write already succeeded */ }
    logPoChange(po, 'Uploaded to ERP', 'delivery date → ' + (completion || edd || ''), authUser(req));   // audit trail
    res.json({ ok: true, cin7_id: cin7Id, estimatedDeliveryDate: edd, erp_mirror_updated: mirrored,
      approval_preserved: curApproved === undefined ? 'unchanged' : (curApproved ? 'approved' : 'draft'),
      link: 'https://go.cin7.com/Cloud/TransactionEntry/TransactionEntry.aspx?idCustomerAppsLink=951111&OrderId=' + encodeURIComponent(cin7Id) });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Push a PO's line items (SKU / qty / price) to Cin7 (#14b). Price = the approved supplier final cost where
// there is one (portal_line_costs.final_cost, confirmed), else the standard plan cost (cost_price).
// LIVE write to Cin7 — gated on CIN7_AUTH; safe no-op (501) when absent.
app.post('/api/supply/po/:po/cin7-lines', async (req, res) => {
  const po = req.params.po;
  const completion = ((req.body && req.body.completion_date) || '').trim();
  if (await activeErp() === 'fulfil') {   // same process, Fulfil target (create-if-absent) — DRY-RUN until FULFIL_LINES_SEND
    try { return res.json(await fulfilPushLines(po, completion)); }
    catch (e) { return res.status(e.code === 'NO_FULFIL_CFG' ? 501 : 502).json({ error: e.message }); }
  }
  try {
    const erpRow = (await pool.query('SELECT erp_po_id FROM planner.erp_purchase_orders WHERE po=$1', [po])).rows[0];
    let cin7Id = erpRow && erpRow.erp_po_id;            // present → update; absent → create a new Cin7 PO (nulled below if the mirrored id turns out to be voided/gone)
    // Pull the supplier's default_currency (join by id first, else by name; default USD). The Cin7 PO is
    // created in this currency so line costs (held in the supplier's currency) are labelled correctly.
    const poRow = (await pool.query(
      `SELECT coalesce(po.supplier_name,'') supplier_name, coalesce(po.branch,'') branch,
              coalesce(s.default_currency, sn.default_currency, 'USD') currency,
              coalesce(s.cin7_member_id, sn.cin7_member_id) cin7_member_id
       FROM planner.purchase_orders po
       LEFT JOIN planner.suppliers s  ON s.id = po.supplier_id
       LEFT JOIN planner.suppliers sn ON lower(sn.name) = lower(po.supplier_name)
       WHERE po.po = $1`, [po])).rows[0];
    if (!poRow) return res.status(404).json({ error: 'PO ' + po + ' not found in the planner.' });
    const lines = (await pool.query(
      `SELECT l.sku, l.qty,
              coalesce(
                (SELECT plc.final_cost FROM planner.portal_line_costs plc
                 WHERE plc.po=l.po AND plc.sku=l.sku AND plc.confirmed_at IS NOT NULL AND plc.final_cost IS NOT NULL),
                l.cost_price) price,
              ((SELECT plc.final_cost FROM planner.portal_line_costs plc
                 WHERE plc.po=l.po AND plc.sku=l.sku AND plc.confirmed_at IS NOT NULL AND plc.final_cost IS NOT NULL) IS NOT NULL) approved_price
       FROM planner.purchase_order_lines l WHERE l.po=$1 AND coalesce(l.qty,0)>0 ORDER BY l.sku`, [po])).rows;
    // Crossdock SKUs carried by the shipment this PO is master of upload to ERP at $0 ONCE the master is
    // shipped (they're physical contents of the master shipment, not a cost to it). qty = supplier-entered
    // shipped (crossdock_shipments); only lines with qty>0 are pushed.
    {
      const st = (await pool.query(`SELECT coalesce(status,'') s FROM planner.purchase_orders WHERE po=$1`, [po])).rows[0];
      if (st && /shipped|shipping|deliver|complete/i.test(st.s)) {
        const xd = (await pool.query(`
          SELECT trim(s.sku) sku, coalesce(cs.qty,0)::int qty
          FROM planner.purchase_orders po2
          CROSS JOIN LATERAL unnest(string_to_array(coalesce(po2.crossdock_skus,''),',')) AS s(sku)
          LEFT JOIN planner.crossdock_shipments cs ON cs.po=po2.po AND cs.sku=trim(s.sku)
          WHERE po2.shipment_ref IN (SELECT shipment_ref FROM planner.shipments WHERE master_po=$1)
            AND coalesce(po2.status,'') NOT ILIKE '%complete%'
            AND trim(s.sku)<>''`, [po])).rows;
        const have = new Set(lines.map(l => l.sku));
        xd.forEach(x => { if (x.sku && x.qty > 0 && !have.has(x.sku)) { lines.push({ sku: x.sku, qty: x.qty, price: 0, approved_price: true, crossdock: true }); have.add(x.sku); } });
      }
    }
    if (!lines.length) return res.status(400).json({ error: 'No order-plan lines with qty for ' + po + '.' });
    let mode = cin7Id ? 'updated' : 'created';
    const auth = cin7Auth();
    if (!auth) return res.status(501).json({ error: 'Cin7 API credentials not configured (set CIN7_AUTH). No write performed.', lines: lines.length, mode });
    const edd = completion ? (/T/.test(completion) ? completion : completion + 'T00:00:00Z') : undefined;
    let newId = cin7Id, r, txt, memberId, branchId, curApproved, rate = null;
    const trace = [];   // Cin7 API-call trace, returned to the UI popup for debugging
    const traceResp = t => { try { return JSON.parse(t); } catch (e) { return String(t || '').slice(0, 400); } };
    // Cin7 PO line COST field is `unitPrice` (there is NO unitCost on a PO line — the API ignores it and defaults
    // to the product's cost). unitPrice is in the order's BASE currency, so convert: unitPrice = planUSD / currencyRate.
    // For an existing PO read its currencyRate (and approval) first; for a new PO the rate is looked up on create,
    // then reconciled by the price validation below.
    if (cin7Id) {
      try {
        const g = await cin7Fetch('https://api.cin7.com/api/v1/PurchaseOrders?rows=1&fields=id,isApproved,currencyRate,isVoid,status&where=' + encodeURIComponent('id=' + cin7Id),
          { headers: { Authorization: auth, 'content-type': 'application/json' } });
        if (g.ok) { const arr = await g.json(); const o = Array.isArray(arr) ? arr[0] : null;
          const voided = o && (o.isVoid === true || /void/i.test(String(o.status || '')));
          if (!o || voided) {
            // The mirrored Cin7 id no longer points at a live PO (voided in Cin7, or deleted). Do NOT PUT to it —
            // that would resurrect / re-approve the voided order (and if it was mis-filed as a sale, poke a dead
            // record). Drop the stale mapping and fall through to CREATE a fresh PO instead.
            await pool.query('DELETE FROM planner.erp_purchase_orders WHERE po=$1', [po]).catch(() => {});
            cin7Id = null; newId = null; mode = 'created';
          } else {
            if (typeof o.isApproved === 'boolean') curApproved = o.isApproved;
            if (Number(o.currencyRate)) rate = Number(o.currencyRate);
          }
        }
      } catch (e) { /* fall through — omit isApproved / rate */ }
    }
    // Resolve the Cin7 supplier link (memberId) ONCE — prefer the stored suppliers.cin7_member_id, else look it
    // up by company name. Sent on BOTH create and update so the order is always tied to the supplier (a missing
    // supplier link is what makes Cin7 mis-file an order as a sales order).
    async function cin7IdByCompany(resource, company) {
      if (!company) return null;
      const g = await cin7Fetch('https://api.cin7.com/api/v1/' + resource + "?rows=1&fields=id,company&where=" +
        encodeURIComponent("company='" + String(company).replace(/'/g, "''") + "'"),
        { headers: { Authorization: auth, 'content-type': 'application/json' } });
      if (!g.ok) return null;
      const arr = await g.json(); return (Array.isArray(arr) && arr[0] && arr[0].id) ? arr[0].id : null;
    }
    memberId = poRow.cin7_member_id ? Number(poRow.cin7_member_id) : await cin7IdByCompany('Contacts', poRow.supplier_name);
    branchId = poRow.branch ? await cin7IdByCompany('Branches', poRow.branch) : null;
    // The fields that anchor an order as a PURCHASE order in Cin7 (supplier member + branch + company). Sent on
    // BOTH create AND update — an update that omits company/branchId flips the order into a SALES ORDER. Always
    // pushed as a draft (isApproved:false) so a person approves it in Cin7.
    const poFields = { company: poRow.supplier_name || '', isApproved: false };
    if (memberId) poFields.memberId = Number(memberId);
    if (branchId) poFields.branchId = Number(branchId);
    if (edd) poFields.estimatedDeliveryDate = edd;   // completion date — kept on create, update AND the corrective PUT
    // Find any existing Cin7 order (PO or SO, incl. voided) with this reference — Cin7 matches by reference and
    // will SILENTLY reject creating a duplicate, even against a voided order.
    async function cin7FindOrderByRef(reference) {
      const w = encodeURIComponent("reference='" + String(reference).replace(/'/g, "''") + "'");
      for (const [resource, kind] of [['PurchaseOrders', 'PO'], ['SalesOrders', 'SO']]) {
        const g = await cin7Fetch('https://api.cin7.com/api/v1/' + resource + '?rows=1&fields=id,isVoid,isApproved&where=' + w,
          { headers: { Authorization: auth, 'content-type': 'application/json' } });
        if (!g.ok) continue;
        const arr = await g.json();
        if (Array.isArray(arr) && arr[0] && arr[0].id) return { id: arr[0].id, kind, isVoid: !!arr[0].isVoid, isApproved: arr[0].isApproved };
      }
      return null;
    }
    // No mirrored id → we'd CREATE. But Cin7 won't create against an existing reference. Reconnect to a live PO
    // if one exists; if a voided order / sales order holds the reference, stop with a clear error (not a silent fail).
    if (!cin7Id) {
      const dup = await cin7FindOrderByRef(po);
      trace.push({ step: 'reference-precheck', reference: po, found: dup || null });
      if (dup && dup.kind === 'PO' && !dup.isVoid) {
        cin7Id = dup.id; newId = dup.id; mode = 'updated';   // orphaned live PO (mirror lost) → update it
        if (typeof dup.isApproved === 'boolean') curApproved = dup.isApproved;
      } else if (dup) {
        return res.status(409).json({ error: 'Cin7 already has a ' + (dup.isVoid ? 'voided ' : '') + (dup.kind === 'SO' ? 'sales order' : 'purchase order') + ' with reference "' + po + '" (Cin7 id ' + dup.id + '). Cin7 reserves that reference permanently — orders can only be voided, not deleted, and a voided order still blocks the reference. Push this PO under a unique reference (e.g. add a suffix) to create it.', lines: lines.length, mode: 'created', cin7_conflict: dup, cin7_trace: trace });
      }
    }
    // Cin7 expects the line unitPrice in the ORDER currency (USD) on write and converts to base itself — send planUSD as-is.
    const lineItems = lines.map(l => ({ code: l.sku, qty: Number(l.qty), unitPrice: Number(l.price) || 0 }));
    if (cin7Id) {
      // UPDATE existing Cin7 PO — re-assert the SAME PO-anchoring fields as create (memberId/company/branchId +
      // draft). Sending only id+lines (as before) let Cin7 reclassify the order as a sales order.
      const upd = Object.assign({ id: Number(cin7Id) || cin7Id, lineItems }, poFields);
      const body = [upd];
      r = await cin7Fetch('https://api.cin7.com/api/v1/PurchaseOrders?loadboms=false',
        { method: 'PUT', headers: { Authorization: auth, 'content-type': 'application/json' }, body: JSON.stringify(body) });
      txt = await r.text();
      trace.push({ step: 'update', method: 'PUT', endpoint: '/v1/PurchaseOrders', request: body, http: r.status, response: traceResp(txt) });
      if (!r.ok) return res.status(502).json({ error: 'Cin7 API error ' + r.status + ': ' + txt.slice(0, 300), cin7_trace: trace });
    } else {
      // CREATE a new Cin7 PO (the planner PO isn't in Cin7 yet). It MUST carry the supplier memberId (resolved
      // above) + a branchId — without the supplier link Cin7 mis-files the order as a SALES ORDER. Fail the
      // create (no write) if either can't be resolved, so we never silently create a malformed order again.
      if (!memberId) return res.status(422).json({ error: 'Supplier "' + (poRow.supplier_name || '(none)') + '" was not found as a Cin7 contact — cannot create the PO. Set the supplier\'s Cin7 member id (or spell-match the name in Cin7), then retry.', lines: lines.length, mode });
      if (poRow.branch && !branchId) return res.status(422).json({ error: 'Branch "' + poRow.branch + '" was not found in Cin7 Branches — cannot create the PO. Make the planner branch name match the Cin7 branch exactly, then retry.', lines: lines.length, mode });
      // Do NOT send `stage` — let Cin7 apply the account's default PO stage. currencyCode = the supplier's
      // default_currency (USD today); Cin7 looks up the rate. poFields carries memberId/company/branchId + draft.
      const create = Object.assign({ reference: po, currencyCode: poRow.currency || 'USD', lineItems }, poFields);
      r = await cin7Fetch('https://api.cin7.com/api/v1/PurchaseOrders?loadboms=false',
        { method: 'POST', headers: { Authorization: auth, 'content-type': 'application/json' }, body: JSON.stringify([create]) });
      txt = await r.text();
      trace.push({ step: 'create', method: 'POST', endpoint: '/v1/PurchaseOrders', request: [create], http: r.status, response: traceResp(txt) });
      if (!r.ok) return res.status(502).json({ error: 'Cin7 create error ' + r.status + ': ' + txt.slice(0, 300), cin7_trace: trace });
      try { const j = JSON.parse(txt); const o = Array.isArray(j) ? j[0] : j; newId = (o && (o.id || o.orderId)) || null; } catch (e) { newId = null; }
      // Cin7 can return HTTP 200 with no id when it rejects the create (e.g. a duplicate reference). Surface it
      // rather than silently reporting success with no PO.
      if (!newId) return res.status(502).json({ error: 'Cin7 accepted the request but returned no PO id — the create was rejected (usually a reference that already exists in Cin7, incl. a voided order). Response: ' + txt.slice(0, 300), lines: lines.length, mode: 'created', cin7_trace: trace });
      // mirror the new Cin7 id back into the ERP mirror so future pushes UPDATE rather than re-create
      if (newId) {
        await pool.query('DELETE FROM planner.erp_purchase_orders WHERE po=$1', [po]);
        await pool.query('INSERT INTO planner.erp_purchase_orders (po, erp_po_id, supplier_name, status, synced_at) VALUES ($1,$2,$3,$4,now())',
          [po, String(newId), poRow.supplier_name || null, 'open']);
      }
    }
    // VALIDATE: read the Cin7 PO back and confirm it matches what we sent. If Cin7 kept lines we didn't send
    // (e.g. a removed SKU — happens if the PUT merged rather than replaced), re-PUT with those extras at qty 0
    // to force exact alignment. Qty is compared (not unitCost — Cin7 may hold it in a different currency).
    let validation = null;
    try {
      const sentByCode = {}; lineItems.forEach(li => { sentByCode[String(li.code).toUpperCase()] = li; });
      const planUsdBy = {}; lines.forEach(l => { planUsdBy[String(l.sku).toUpperCase()] = Number(l.price); });   // plan cost in USD, for price validation
      const validateId = newId || cin7Id;
      async function getCin7Data() {
        const g = await cin7Fetch('https://api.cin7.com/api/v1/PurchaseOrders?rows=1&fields=id,currencyCode,currencyRate,lineItems&where=' + encodeURIComponent('id=' + validateId),
          { headers: { Authorization: auth, 'content-type': 'application/json' } });
        if (!g.ok) return null;
        const arr = await g.json(); const o = Array.isArray(arr) ? arr[0] : arr;
        return { items: (o && Array.isArray(o.lineItems)) ? o.lineItems : [], rate: Number(o && o.currencyRate) || null, cur: (o && o.currencyCode) || null };
      }
      // Line unitPrice reads back in the ORDER currency, which equals the supplier's currency — the same
      // currency the plan cost is held in. So compare directly (no rate conversion), uniform for every currency
      // (a GBP order just has currencyRate=1 against the GBP account base — same calculation).
      function priceOff(items, rate, cur) {
        const factor = 1;
        const by = {}; items.forEach(li => { if (li && li.code) by[String(li.code).toUpperCase()] = li; });
        const out = []; Object.keys(sentByCode).forEach(c => { const li = by[c]; if (!li || li.unitPrice == null) return;
          const cin = Math.round(Number(li.unitPrice) * factor * 100) / 100, plan = Math.round((Number(planUsdBy[c]) || 0) * 100) / 100;
          if (Math.abs(cin - plan) >= 0.01) out.push({ sku: sentByCode[c].code, plan: plan, cin7: cin }); });
        return out; }
      if (validateId) {
        const d = await getCin7Data();
        if (d) {
          const byCode = {}; d.items.forEach(li => { if (li && li.code) byCode[String(li.code).toUpperCase()] = li; });
          const extras = Object.keys(byCode).filter(c => !sentByCode[c] && Number(byCode[c].qty) > 0);   // in Cin7, not in plan
          const qtyOff = Object.keys(sentByCode).filter(c => !byCode[c] || Number(byCode[c].qty) !== Number(sentByCode[c].qty));
          const pOff = priceOff(d.items, d.rate, d.cur);
          validation = { checked: true, currency: d.cur, currency_rate: d.rate, extras: extras.length, qty_off: qtyOff.length, price_off: pOff.length, price_off_detail: pOff.slice(0, 60), corrected: false, aligned: (!extras.length && !qtyOff.length && !pOff.length) };
          if (extras.length || qtyOff.length || pOff.length) {
            // corrective PUT: re-send EVERY line at its plan USD cost (the order is USD, so unitPrice = planUSD
            // directly) — self-heals any qty/price drift — plus any Cin7-only extras zeroed out.
            const fixItems = lines.map(l => ({ code: l.sku, qty: Number(l.qty), unitPrice: Number(l.price) || 0 }));
            const fix = fixItems.concat(extras.map(c => ({ code: byCode[c].code, qty: 0, unitPrice: Number(byCode[c].unitPrice) || 0 })));
            const body2 = [Object.assign({ id: Number(validateId) || validateId, lineItems: fix }, poFields)];   // keep the PO-anchoring fields so the corrective PUT doesn't reclassify it
            const r2 = await cin7Fetch('https://api.cin7.com/api/v1/PurchaseOrders?loadboms=false',
              { method: 'PUT', headers: { Authorization: auth, 'content-type': 'application/json' }, body: JSON.stringify(body2) });
            trace.push({ step: 'correct', method: 'PUT', endpoint: '/v1/PurchaseOrders', request: body2, http: r2.status });
            validation.corrected = true; validation.correction_ok = r2.ok;
            const d2 = r2.ok ? await getCin7Data() : null;
            if (d2) { const b2 = {}; d2.items.forEach(li => { if (li && li.code) b2[String(li.code).toUpperCase()] = li; });
              validation.extras_after = Object.keys(b2).filter(c => !sentByCode[c] && Number(b2[c].qty) > 0).length;
              validation.qty_off_after = Object.keys(sentByCode).filter(c => !b2[c] || Number(b2[c].qty) !== Number(sentByCode[c].qty)).length;
              const pOff2 = priceOff(d2.items, d2.rate, d2.cur); validation.price_off_after = pOff2.length; validation.price_off_detail = pOff2.slice(0, 60);
              validation.aligned = (!validation.extras_after && !validation.qty_off_after && !validation.price_off_after); }
          }
        }
      }
    } catch (e) { validation = { checked: false, error: e.message }; }
    // optimistically sync the local ERP mirror (lines + delivery date) so the "Update ERP" drift flags clear
    // immediately — reflects what Cin7 now holds; n8n re-confirms on its next sync. Non-fatal if it fails.
    let mirrored = false;
    try {
      for (const l of lines) {
        await pool.query(`INSERT INTO planner.erp_purchase_order_lines (po, sku, qty, cost, synced_at)
          VALUES ($1,$2,$3,$4,now()) ON CONFLICT (po,sku) DO UPDATE SET qty=excluded.qty, cost=excluded.cost, synced_at=now()`,
          [po, l.sku, Number(l.qty), Number(l.price) || 0]);
      }
      // drop mirror rows for SKUs no longer on the pushed order (zeroed / removed) — Cin7 no longer holds them,
      // so the mirror must match exactly or the "Update ERP" drift flag would persist against stale rows.
      await pool.query(`DELETE FROM planner.erp_purchase_order_lines WHERE po=$1 AND NOT (sku = ANY($2))`, [po, lines.map(l => l.sku)]);
      if (edd) await pool.query(`UPDATE planner.erp_purchase_orders SET final_delivery_date=$2::date, synced_at=now() WHERE po=$1`, [po, completion]);
      mirrored = true;
    } catch (e) { /* non-fatal — Cin7 write already succeeded */ }
    // PO totals for the UI (the PO's own order-plan lines — excludes the $0 crossdock extras carried on a master).
    const ownLines = lines.filter(l => !l.crossdock);
    const total_units = ownLines.reduce((s, l) => s + (Number(l.qty) || 0), 0);
    const total_cost = ownLines.reduce((s, l) => s + (Number(l.qty) || 0) * (Number(l.price) || 0), 0);
    logPoChange(po, 'Uploaded to ERP', lines.length + ' line' + (lines.length === 1 ? '' : 's') + ' (' + mode + ')', authUser(req));   // audit trail
    res.json({ ok: true, mode, cin7_id: newId, cin7_member_id: memberId || null, cin7_branch_id: branchId || null, lines: lines.length, approved: lines.filter(l => l.approved_price).length, erp_mirror_updated: mirrored, validation, cin7_trace: trace,
      total_units, total_cost: Math.round(total_cost * 100) / 100, currency: poRow.currency || 'USD',
      link: newId ? 'https://go.cin7.com/Cloud/TransactionEntry/TransactionEntry.aspx?idCustomerAppsLink=951111&OrderId=' + encodeURIComponent(newId) : null });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// READ-ONLY verify: GET the Cin7 PO's line items and compare to the planner order plan (qty AND price).
// No write. price = approved supplier final cost, else cost_price (same as the push). ratio = cin7/plan
// (≈1.0 → USD match; ≈0.75 → Cin7 is showing GBP; anything else → didn't take).
app.get('/api/supply/po/:po/cin7-verify', async (req, res) => {
  const po = req.params.po;
  try {
    const erpRow = (await pool.query('SELECT erp_po_id FROM planner.erp_purchase_orders WHERE po=$1', [po])).rows[0];
    const cin7Id = erpRow && erpRow.erp_po_id;
    if (!cin7Id) return res.status(404).json({ error: 'No Cin7 PO id for ' + po });
    const auth = cin7Auth();
    if (!auth) return res.status(501).json({ error: 'Cin7 credentials not configured' });
    const plan = (await pool.query(
      `SELECT l.sku, l.qty::numeric qty,
              coalesce((SELECT plc.final_cost FROM planner.portal_line_costs plc WHERE plc.po=l.po AND plc.sku=l.sku AND plc.confirmed_at IS NOT NULL AND plc.final_cost IS NOT NULL), l.cost_price)::numeric price
       FROM planner.purchase_order_lines l WHERE l.po=$1 AND coalesce(l.qty,0)>0`, [po])).rows;
    const planBy = {}; plan.forEach(l => { planBy[String(l.sku).toUpperCase()] = l; });
    const g = await cin7Fetch('https://api.cin7.com/api/v1/PurchaseOrders?rows=1&fields=id,currencyRate,lineItems&where=' + encodeURIComponent('id=' + cin7Id),
      { headers: { Authorization: auth, 'content-type': 'application/json' } });
    if (!g.ok) return res.status(502).json({ error: 'Cin7 read error ' + g.status });
    const arr = await g.json(); const o = Array.isArray(arr) ? arr[0] : arr;
    // Cin7 line unitPrice is in the order's BASE currency; USD = unitPrice / currencyRate (Ben). Match to 0.01.
    const rate = Number(o && o.currencyRate) || null;
    const cin = (o && Array.isArray(o.lineItems)) ? o.lineItems : [];
    const cinBy = {}; cin.forEach(li => { if (li && li.code) cinBy[String(li.code).toUpperCase()] = li; });
    const rows = plan.map(l => { const c = cinBy[String(l.sku).toUpperCase()];
      const pq = Number(l.qty), pp = Number(l.price);
      const cq = c ? Number(c.qty) : null, raw = c ? Number(c.unitPrice) : null;
      const usd = (raw != null && rate) ? Math.round((raw * rate) * 10000) / 10000 : null;   // base→USD (rate is USD per base unit)
      return { sku: l.sku, plan_qty: pq, cin7_qty: cq, plan_price: pp, cin7_unitprice: raw, cin7_usd: usd,
        created: c ? c.createdDate : null, qtyShipped: c ? Number(c.qtyShipped) : null, holdingQty: c ? Number(c.holdingQty) : null,
        qty_ok: c ? cq === pq : false,
        price_ok: (usd != null && pp != null) ? Math.abs(usd - pp) < 0.01 : false }; });
    const extras = Object.keys(cinBy).filter(c => !planBy[c] && Number(cinBy[c].qty) > 0);
    res.json({ ok: true, cin7_id: cin7Id, currency_rate: rate, lines: rows.length,
      qty_ok: rows.filter(r => r.qty_ok).length, price_ok: rows.filter(r => r.price_ok).length,
      qty_off: rows.filter(r => !r.qty_ok).map(r => r.sku),
      price_off: rows.filter(r => !r.price_ok).map(r => ({ sku: r.sku, plan_usd: r.plan_price, cin7_usd: r.cin7_usd, created: r.created, qtyShipped: r.qtyShipped, holdingQty: r.holdingQty })),
      extras_in_cin7: extras });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// BULK "Update Cin7 Date" — push the planner completion date to Cin7 EstimatedDeliveryDate for every supplied PO.
// body: { pos: [{ po, completion_date }] }. Server RE-VALIDATES: only ACTIVE (non-complete) POs that exist in Cin7
// are touched (a complete PO is skipped — its date no longer needs pushing). Each PO's CURRENT approval state is
// read and echoed so the bulk update never flips a draft to approved. One batched PUT. LIVE write — gated on creds.
app.post('/api/supply/cin7-dates-sync', async (req, res) => {
  if (await activeErp() === 'fulfil') return res.status(501).json({ error: 'Fulfil is the active ERP — the Fulfil push is not wired yet, so no write was performed. Switch Active ERP to Cin7 in CONFIG ▸ General settings to push to Cin7.' });
  const auth = cin7Auth();
  if (!auth) return res.status(501).json({ error: 'Cin7 API credentials not configured (set CIN7_AUTH). No write performed.' });
  const items = Array.isArray(req.body && req.body.pos) ? req.body.pos.filter(x => x && x.po) : [];
  if (!items.length) return res.json({ ok: true, updated: 0, skipped: 0, message: 'no POs supplied' });
  try {
    // authoritative guard: status + Cin7 id straight from the DB (don't trust the client on complete-vs-active)
    const meta = {};
    (await pool.query(`SELECT p.po, coalesce(p.status,'') status, e.erp_po_id
      FROM planner.purchase_orders p JOIN planner.erp_purchase_orders e ON e.po=p.po
      WHERE p.po = ANY($1)`, [items.map(x => x.po)])).rows.forEach(r => { meta[r.po] = r; });
    // 1) validate (active-only, in-Cin7, has date) → build the to-do list
    const todo = [], skipped = [];
    for (const it of items) {
      const m = meta[it.po];
      if (!m || !m.erp_po_id) { skipped.push({ po: it.po, reason: 'not in Cin7' }); continue; }
      if (/complete/i.test(m.status)) { skipped.push({ po: it.po, reason: 'complete — skipped' }); continue; }
      const c = (it.completion_date || '').trim();
      if (!c) { skipped.push({ po: it.po, reason: 'no completion date' }); continue; }
      todo.push({ po: it.po, id: Number(m.erp_po_id) || m.erp_po_id, date: c, edd: /T/.test(c) ? c : (c + 'T00:00:00Z') });
    }
    if (!todo.length) return res.json({ ok: true, updated: 0, skipped: skipped.length, skippedDetail: skipped });
    // 2) read current approval state for all ids in chunks (id IN (...)) so the update preserves draft/approved
    const approvedById = {}; const ids = todo.map(t => t.id);
    for (let i = 0; i < ids.length; i += 100) {
      const chunk = ids.slice(i, i + 100);
      try {
        const g = await cin7Fetch('https://api.cin7.com/api/v1/PurchaseOrders?rows=250&fields=id,isApproved&where=' + encodeURIComponent('id IN (' + chunk.join(',') + ')'),
          { headers: { Authorization: auth, 'content-type': 'application/json' } });
        if (g.ok) { const arr = await g.json(); if (Array.isArray(arr)) arr.forEach(o => { if (o && typeof o.isApproved === 'boolean') approvedById[o.id] = o.isApproved; }); }
      } catch (e) { /* unread → isApproved omitted, Cin7 leaves it unchanged */ }
    }
    // 3) one batched PUT, echoing each PO's current approval state
    const batch = todo.map(t => { const upd = { id: t.id, estimatedDeliveryDate: t.edd };
      if (approvedById[t.id] !== undefined) upd.isApproved = approvedById[t.id]; return upd; });
    const r = await cin7Fetch('https://api.cin7.com/api/v1/PurchaseOrders?loadboms=false',
      { method: 'PUT', headers: { Authorization: auth, 'content-type': 'application/json' }, body: JSON.stringify(batch) });
    const txt = await r.text();
    if (!r.ok) return res.status(502).json({ error: 'Cin7 API error ' + r.status + ': ' + txt.slice(0, 300) });
    // optimistically sync the local ERP mirror so the "Date ≠ ERP" flags clear immediately (n8n re-confirms later)
    let mirrored = 0;
    for (const t of todo) { try { const u = await pool.query(`UPDATE planner.erp_purchase_orders SET final_delivery_date=$2::date, synced_at=now() WHERE po=$1`, [t.po, t.date]); mirrored += u.rowCount; } catch (e) { /* non-fatal */ } }
    res.json({ ok: true, updated: batch.length, erp_mirror_updated: mirrored, skipped: skipped.length, skippedDetail: skipped });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Rename a PO (Master Data tab) — cascades the key across all owned tables + shipment pointers.
app.post('/api/supply/po/:po/rename', async (req, res) => {
  const oldpo = req.params.po, newpo = ((req.body && req.body.new_po) || '').trim();
  if (!newpo) return res.status(400).json({ error: 'new_po required' });
  if (newpo === oldpo) return res.json({ ok: true });
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const ex = await client.query('SELECT 1 FROM planner.purchase_orders WHERE po=$1', [newpo]);
    if (ex.rowCount) { await client.query('ROLLBACK'); return res.status(409).json({ error: 'PO ' + newpo + ' already exists' }); }
    await client.query('UPDATE planner.purchase_orders SET po=$1 WHERE po=$2', [newpo, oldpo]);
    await client.query("UPDATE planner.purchase_order_lines SET po=$1, po_sku=$1||'|'||sku WHERE po=$2", [newpo, oldpo]);
    await client.query('UPDATE planner.erp_purchase_order_lines SET po=$1 WHERE po=$2', [newpo, oldpo]);
    await client.query('UPDATE planner.erp_purchase_orders SET po=$1 WHERE po=$2', [newpo, oldpo]);
    await client.query('UPDATE planner.portal_attachments SET po=$1 WHERE po=$2', [newpo, oldpo]);
    await client.query('UPDATE planner.supplier_submissions SET po=$1 WHERE po=$2', [newpo, oldpo]);
    await client.query('UPDATE planner.supplier_notes SET po=$1 WHERE po=$2', [newpo, oldpo]);
    await client.query('UPDATE planner.purchase_orders SET shipment_ref=$1 WHERE shipment_ref=$2', [newpo, oldpo]);
    await client.query('UPDATE planner.shipments SET shipment_ref=$1 WHERE shipment_ref=$2', [newpo, oldpo]).catch(() => {});
    await client.query('UPDATE planner.shipments SET master_po=$1 WHERE master_po=$2', [newpo, oldpo]).catch(() => {});
    await client.query('COMMIT');
    res.json({ ok: true });
  } catch (e) { await client.query('ROLLBACK'); log500(e); res.status(500).json({ error: e.message }); }
  finally { client.release(); }
});
// PO management engine — inline edits on the purchase_orders inputs/overrides.
app.post('/api/supply/po/:po', async (req, res) => {
  const body = req.body || {};
  // editing anything shown in the "Direct to Client details" (packing/labelling OR the client sales ref /
  // PO number / notes) invalidates a prior supplier approval → re-approve
  const DTC_FIELDS = ['sales_order_ref', 'client_po_ref', 'client_requirements'];
  if (Object.keys(body).some(k => k.indexOf('pack_') === 0 || DTC_FIELDS.indexOf(k) >= 0)) {
    try { await pool.query(`UPDATE planner.purchase_orders SET dtc_accepted_at=NULL, dtc_accepted_by=NULL WHERE po=$1`, [req.params.po]); } catch (e) {}
  }
  // Assigning/changing the branch re-populates the branch delivery notes: clear the PO override so it falls back
  // to the new branch's delivery_notes (unless the caller is explicitly editing branch_delivery_notes itself).
  if (body.branch !== undefined && body.branch_delivery_notes === undefined) {
    try { await pool.query(`UPDATE planner.purchase_orders SET branch_delivery_notes=NULL WHERE po=$1`, [req.params.po]); } catch (e) {}
  }
  // Deposit assignment guards: (1) region — AU deposits pair only with AU POs and vice-versa; (2) supplier —
  // a deposit can only go on a PO from the same supplier (a Lixin deposit only onto Lixin POs). Prevents
  // accidental cross-region / cross-supplier assignment.
  if (body.deposit_ref && String(body.deposit_ref).trim() && String(body.deposit_ref).trim().toUpperCase() !== 'NO DEPOSIT') {
    try {
      const ref = String(body.deposit_ref).trim();
      const dep = (await pool.query(`SELECT coalesce(country,'') country, coalesce(supplier_name,'') supplier FROM planner.deposits WHERE reference=$1 AND is_deposit LIMIT 1`, [ref])).rows[0];
      const poc = (await pool.query(`SELECT upper(coalesce(nullif(po.country_code,''),(SELECT b.country_code FROM planner.branches b WHERE b.name=po.branch),'')) ctry, coalesce(po.supplier_name,'') supplier FROM planner.purchase_orders po WHERE po.po=$1`, [req.params.po])).rows[0];
      if (dep && poc) {
        const depAU = /^AU$/i.test((dep.country || '').trim()), poAU = /^AU$/.test(poc.ctry || '');
        if (depAU !== poAU) return res.status(400).json({ error: 'Region mismatch — ' + (depAU ? 'an AU deposit' : 'a non-AU deposit') + ' cannot be assigned to ' + (poAU ? 'an AU purchase order' : 'a non-AU purchase order') + '.' });
        const norm = s => String(s || '').trim().toLowerCase();
        if (norm(dep.supplier) && norm(poc.supplier) && norm(dep.supplier) !== norm(poc.supplier))
          return res.status(400).json({ error: 'Supplier mismatch — deposit ' + ref + ' belongs to ' + dep.supplier + ', but this PO is ' + poc.supplier + '. A deposit can only be assigned to a PO from the same supplier.' });
      }
    } catch (e) { /* non-fatal — fall through */ }
  }
  // Audit log: snapshot the prior values of any tracked fields in this edit, so the post-update callback can
  // record exactly what changed (old → new) on the PO timeline.
  const _trackKeys = Object.keys(body).filter(k => PO_TRACK[k]);
  let _trackOld = {};
  if (_trackKeys.length) { try { _trackOld = (await pool.query(
    `SELECT ${_trackKeys.map(k => `${k}::text AS ${k}`).join(',')} FROM planner.purchase_orders WHERE po=$1`, [req.params.po])).rows[0] || {}; } catch (e) {} }
  const _trackBy = authUser(req) || null;
  patch(res, 'planner.purchase_orders', 'po', req.params.po, {
    status: 'text', ship_type: 'text', deposit_ref: 'text', shipment_ref: 'text', prod_no: 'text',
    starred: 'boolean',   // ⭐ Focus / favourite toggle (migration 082)
    preship_not_required: 'boolean',   // "not required" tick suppresses the pre-shipment-docs action (migration 107)
    confirmed_in_3pl: 'boolean',   // PO ▸ Shipments tick — this PO is entered in the 3PL's system (migration 236); shows ✅3pl on the pipeline card
    batch_id: 'text', branch: 'text', erp_po: 'text', notes: 'text', container_size: 'text',
    country_code: 'text', client: 'text', client_requirements: 'text', sales_order_ref: 'text', client_deadline_date: 'date', asn_numbers: 'text',
    client_po_ref: 'text', dispatch_order_ref: 'text', final_delivery_address: 'text', crossdock_skus: 'text', branch_delivery_notes: 'text',
    // Packing & Labelling (Client/FBA tab → supplier portal "Direct to Client details") — migration 086
    pack_polybags: 'boolean', pack_polybags_notes: 'text', pack_dnb_barcodes: 'boolean', pack_dnb_barcodes_notes: 'text',
    pack_rfid_barcodes: 'boolean', pack_rfid_barcodes_notes: 'text', pack_dnb_carton: 'boolean', pack_dnb_carton_notes: 'text',
    pack_client_carton: 'boolean', pack_client_carton_notes: 'text', pack_pallet_notes: 'text', pack_other_notes: 'text',
    dtc_custom: 'boolean', dtc_key_account: 'boolean', custom_dev_ref: 'text',   // custom_dev_ref = comma-separated product_dev_items.ref list (custom order → its product developments)
    order_value_estimation: 'numeric', supplier_invoice_total: 'numeric',
    start_production: 'date', end_production_overide: 'date', landing_date_overide: 'date',
    delivery_date_overide: 'date', balance_due_date_overide: 'date', supplier_ship_date: 'date',
    // payment-plan overrides (PLAN panel): % terms, assigned amounts, payment dates
    start_deposit_pct_override: 'numeric', completion_pct_override: 'numeric',
    pay_start_deposit_assigned: 'numeric', pay_start_deposit_date: 'date',
    pay_completion_assigned: 'numeric', pay_completion_date: 'date',
    pay_balance_1_amount: 'numeric', pay_balance_1_date: 'date',
    pay_balance_2_amount: 'numeric', pay_balance_2_date: 'date',
    credit_amount: 'numeric',
    pallets_override: 'numeric',   // #A per-PO pallet override (SHIPMENTS tab) — feeds freight/cash-flow; timeline-logged via PO_TRACK
  }, body,
  undefined,
  // Step 1+2: hand back the recomputed grid row so the client repaints WITHOUT a second fetch — but only when the
  // edit can move a value shown in the grid. Purely detail-panel / cosmetic fields (client text, refs, packing,
  // notes) skip the ~0.4s row query entirely: the client just repaints the cell it already changed.
  ((Object.keys(body).some(k => !PO_COSMETIC_FIELDS.has(k)) || _trackKeys.length)
    ? async () => { if (_trackKeys.length) await logPoFieldChanges(req.params.po, _trackKeys, _trackOld, body, _trackBy);
        // return the recomputed grid row ONLY for non-cosmetic edits (drives the client repaint). A cosmetic-but-tracked
        // edit (e.g. the confirmed_in_3pl tickbox) logs the change but returns NO row → no panel re-render → the box stays ticked.
        return Object.keys(body).some(k => !PO_COSMETIC_FIELDS.has(k))
          ? { row: (await queryCapped(PO_ROWS_SQL + ' WHERE calc4.po = $1', [req.params.po])).rows[0] || null } : {}; }
    : undefined));
});
// Advance a PO (and every PO on the same master shipment still in PRODUCTION) to SHIPPING. Offered on the
// grid when the shipment has departed but the PO status still says PRODUCTION. Only touches PRODUCTION POs
// (never re-opens completed/delivered ones); scoped to the PO's shipment_ref so "ships-with" POs move together.
app.post('/api/supply/po/:po/set-shipping', async (req, res) => {
  try {
    const r = (await pool.query(`SELECT coalesce(shipment_ref,'') shipment_ref FROM planner.purchase_orders WHERE po=$1`, [req.params.po])).rows[0];
    if (!r) return res.status(404).json({ error: 'PO not found' });
    let rows;
    // SHIPPING implies production is done + shipped → default production_status to 'shipped' (stamped)
    if (r.shipment_ref) rows = (await pool.query(
      `UPDATE planner.purchase_orders SET status='SHIPPING', production_status='shipped', production_confirmed_at=coalesce(production_confirmed_at,now()), updated_at=now()
        WHERE shipment_ref=$1 AND status ILIKE '%production%' RETURNING po`, [r.shipment_ref])).rows;
    else rows = (await pool.query(
      `UPDATE planner.purchase_orders SET status='SHIPPING', production_status='shipped', production_confirmed_at=coalesce(production_confirmed_at,now()), updated_at=now()
        WHERE po=$1 AND status ILIKE '%production%' RETURNING po`, [req.params.po])).rows;
    res.json({ updated: rows.length, pos: rows.map(x => x.po), shipment: r.shipment_ref || null });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// "Shipped to master": a rider PO the supplier shipped to the consolidator, but the master hasn't sailed. OUR
// side stays upstream (≈ ready to ship) — set the single PO to SHIPPED TO MASTER. When the master departs, the
// existing set-shipping / propagateShipping flow flips it (and the rest of the shipment) to SHIPPING.
app.post('/api/supply/po/:po/set-shipped-to-master', async (req, res) => {
  try {
    const rows = (await pool.query(
      `UPDATE planner.purchase_orders SET status='SHIPPED TO MASTER', updated_at=now()
        WHERE po=$1 AND coalesce(status,'') NOT ILIKE '%complete%'
          AND upper(coalesce(status,'')) NOT IN ('SHIPPING','DELIVERED','SHIPPED TO MASTER')
        RETURNING po`, [req.params.po])).rows;
    if (!rows.length) return res.status(409).json({ error: 'PO not eligible (already shipped/complete, or not found)' });
    res.json({ updated: rows.length, po: req.params.po });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Shared: advance every PO on a shipment still in PRODUCTION to SHIPPING + production_status 'shipped'.
// Matches the shipment's children (shipment_ref=ref), the ref itself (self-master), and the shipment's
// master_po (a master PO whose own shipment_ref is blank). Never re-opens completed/delivered POs.
// If `po` is the MASTER PO of a shipment, advance that shipment to Shipping (unless already Completed).
// Used when a supplier marks the master PO's production status 'shipped'. Only fires for a master PO —
// a child/consolidated PO returns no row and leaves the shipment untouched. `q` = pool or a txn client.
async function shipmentShippingFromMasterPO(q, po) {
  if (!po) return null;
  const r = (await q.query(`SELECT shipment_ref FROM planner.shipments
    WHERE (master_po=$1 OR (coalesce(master_po,'')='' AND shipment_ref=$1))
      AND coalesce(status,'') NOT ILIKE '%complete%' LIMIT 1`, [po])).rows[0];
  if (r) await q.query(`UPDATE planner.shipments SET status='Shipping', updated_at=now() WHERE shipment_ref=$1`, [r.shipment_ref]);
  return r ? r.shipment_ref : null;
}
async function propagateShippingToPOs(ref) {
  if (!ref) return 0;
  return (await pool.query(`UPDATE planner.purchase_orders SET status='SHIPPING', production_status='shipped',
    production_confirmed_at=coalesce(production_confirmed_at,now()),
    end_production_overide=coalesce(end_production_overide, current_date),   -- completion date → today if blank
    updated_at=now()
    WHERE (shipment_ref=$1 OR po=$1 OR po=(SELECT master_po FROM planner.shipments WHERE shipment_ref=$1 LIMIT 1))
      AND status ILIKE '%production%'`, [ref])).rowCount;
}
// Supplier edit — sets the name AND resolves supplier_id so payment terms / production lead apply.
app.post('/api/supply/po/:po/supplier', async (req, res) => {
  const name = (req.body && req.body.supplier_name || '').trim() || null;
  try {
    await pool.query(`UPDATE planner.purchase_orders
      SET supplier_name=$2, supplier_id=(SELECT id FROM planner.suppliers WHERE name=$2 LIMIT 1)
      WHERE po=$1`, [req.params.po, name]);
    // back-fill any PO notes that were created before the supplier was assigned (e.g. the "created new PO"
    // note) so they land in this supplier's portal thread + raise the unread badge
    await pool.query(`UPDATE planner.supplier_notes
      SET supplier_id=(SELECT id FROM planner.suppliers WHERE name=$2 LIMIT 1)
      WHERE po=$1 AND supplier_id IS NULL`, [req.params.po, name]);
    res.json({ ok: true });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Supplier production-confidence: set the confirmed production status and stamp the confirmation time
// (now). Clearing the status clears the stamp. Drives the "Production unconfirmed" action.
const PROD_STATUSES = ['not_started','in_production','ready_to_ship','shipped'];
app.post('/api/supply/po/:po/prod-status', async (req, res) => {
  const st = (req.body && req.body.production_status || '').trim();
  if (st && !PROD_STATUSES.includes(st)) return res.status(400).json({ error: 'bad status' });
  try {
    await pool.query(`UPDATE planner.purchase_orders
      SET production_status=$2, production_confirmed_at=CASE WHEN $2='' THEN NULL ELSE now() END WHERE po=$1`,
      [req.params.po, st]);
    res.json({ ok: true });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Create / input a new purchase order. Minimal header; the rest is filled inline + in the PLAN panel.
// supplier_id is resolved from the supplier name so payment terms / production lead apply immediately.
app.post('/api/supply/po-create', async (req, res) => {
  const b = req.body || {}, po = (b.po || '').trim();
  if (!po) return res.status(400).json({ error: 'PO number required' });
  try {
    const dup = await pool.query(`SELECT 1 FROM planner.purchase_orders WHERE po=$1`, [po]);
    if (dup.rowCount) return res.status(409).json({ error: 'PO ' + po + ' already exists' });
    let supId = null;
    if (b.supplier_name) {
      const s = await pool.query(`SELECT id FROM planner.suppliers WHERE name=$1 LIMIT 1`, [b.supplier_name]);
      supId = s.rows[0] ? s.rows[0].id : null;
    }
    await pool.query(`INSERT INTO planner.purchase_orders
      (po, supplier_name, supplier_id, country_code, branch, status, start_production, prod_no, batch_id)
      VALUES ($1,$2,$3,$4,$5,coalesce($6,'FUTURE'),$7,$8,$9)`,
      [po, b.supplier_name || null, supId, b.country_code || null, b.branch || null,
       b.status || null, b.start_production || null, b.prod_no || null, b.batch_id || null]);
    await notePoCreated(pool, po, authUser(req));
    invalidateSupplyCaches();   // new PO written → rebuild cached PO-rows / order-plan so it shows without a hard refresh
    res.json({ ok: true, po });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Import a purchase order FROM Cin7 into the planner (reverse of the push). Provide a Cin7 PO reference; we
// read it from Cin7, map the supplier (via suppliers.cin7_member_id, else the Cin7 company name) and branch
// (via branchId → Cin7 branch name), and bring in the line SKUs/quantities as-is. confirm=false → preview only;
// confirm=true → write (overwrite the PO's lines from Cin7) + mirror the Cin7 id so future pushes update it.
app.post('/api/supply/po-import-cin7', async (req, res) => {
  const b = req.body || {}, reference = (b.reference || '').trim(), confirm = !!b.confirm;
  if (!reference) return res.status(400).json({ error: 'PO reference required' });
  const auth = cin7Auth();
  if (!auth) return res.status(501).json({ error: 'Cin7 API credentials not configured (set CIN7_AUTH).' });
  try {
    const w = encodeURIComponent("reference='" + reference.replace(/'/g, "''") + "'");
    const g = await cin7Fetch('https://api.cin7.com/api/v1/PurchaseOrders?rows=1&fields=id,reference,memberId,branchId,company,currencyCode,estimatedDeliveryDate,isVoid,lineItems&where=' + w,
      { headers: { Authorization: auth, 'content-type': 'application/json' } });
    if (!g.ok) return res.status(502).json({ error: 'Cin7 read error ' + g.status });
    const arr = await g.json(); const o = Array.isArray(arr) ? arr[0] : null;
    if (!o || !o.id) return res.status(404).json({ error: 'No Cin7 purchase order found with reference "' + reference + '".' });
    // supplier: reverse-map memberId → planner supplier; fall back to the Cin7 company name
    let supplier_name = o.company || null, supplier_id = null;
    if (o.memberId) { const s = await pool.query('SELECT id,name FROM planner.suppliers WHERE cin7_member_id=$1 LIMIT 1', [o.memberId]); if (s.rows[0]) { supplier_id = s.rows[0].id; supplier_name = s.rows[0].name; } }
    // branch: Cin7 branchId → branch name
    let branch = null;
    if (o.branchId) { const bg = await cin7Fetch('https://api.cin7.com/api/v1/Branches?rows=1&fields=id,company&where=' + encodeURIComponent('id=' + o.branchId), { headers: { Authorization: auth, 'content-type': 'application/json' } }); if (bg.ok) { const ba = await bg.json(); if (Array.isArray(ba) && ba[0]) branch = ba[0].company; } }
    const delivery = o.estimatedDeliveryDate ? String(o.estimatedDeliveryDate).slice(0, 10) : null;
    const lines = (o.lineItems || []).filter(l => l && l.code).map(l => ({ sku: String(l.code), qty: Math.round(Number(l.qty) || 0), cost: Number(l.unitCost != null ? l.unitCost : (l.unitPrice != null ? l.unitPrice : l.price)) || 0 }));
    const exists = (await pool.query('SELECT 1 FROM planner.purchase_orders WHERE po=$1', [o.reference])).rowCount > 0;
    const preview = { cin7_id: o.id, po: o.reference, supplier_name, supplier_id, branch, currency: o.currencyCode || null, delivery, isVoid: !!o.isVoid, lines, line_count: lines.length, exists };
    if (!confirm) return res.json({ found: true, preview });
    // IMPORT (overwrite): upsert header, replace lines from Cin7, mirror the Cin7 id
    if (exists) {
      await pool.query('UPDATE planner.purchase_orders SET supplier_name=$2, supplier_id=$3, branch=$4, delivery_date_overide=coalesce($5::date, delivery_date_overide), updated_at=now() WHERE po=$1', [o.reference, supplier_name, supplier_id, branch, delivery]);
    } else {
      await pool.query("INSERT INTO planner.purchase_orders (po, supplier_name, supplier_id, branch, status, delivery_date_overide) VALUES ($1,$2,$3,$4,'PRODUCTION',$5::date)", [o.reference, supplier_name, supplier_id, branch, delivery]);   // imported POs land as PRODUCTION so they show under the default In-progress filter
    }
    // Replace the planner lines with Cin7's, and mirror the SAME values into the ERP mirror
    // (erp_purchase_order_lines) so an imported PO reads as fully in-sync — no phantom drift. The
    // import IS the ERP truth, so qty=erp_qty and cost_price=erp_cost=el.cost; nothing is "proposed".
    await pool.query('DELETE FROM planner.purchase_order_lines WHERE po=$1', [o.reference]);
    await pool.query('DELETE FROM planner.erp_purchase_order_lines WHERE po=$1', [o.reference]);
    for (const l of lines) {
      await pool.query("INSERT INTO planner.purchase_order_lines (po_sku, po, sku, qty, erp_qty, cost_price, erp_cost, proposed_at, proposed_by) VALUES ($1,$2,$3,$4::int,$4::int,$5::numeric,$5::numeric,NULL,NULL) ON CONFLICT (po_sku) DO UPDATE SET qty=excluded.qty, erp_qty=excluded.erp_qty, cost_price=excluded.cost_price, erp_cost=excluded.erp_cost, proposed_at=NULL, proposed_by=NULL", [o.reference + '|' + l.sku, o.reference, l.sku, l.qty, l.cost]);
      await pool.query("INSERT INTO planner.erp_purchase_order_lines (po, sku, qty, cost, synced_at) VALUES ($1,$2,$3::int,$4::numeric,now()) ON CONFLICT (po,sku) DO UPDATE SET qty=excluded.qty, cost=excluded.cost, synced_at=now()", [o.reference, l.sku, l.qty, l.cost]);
    }
    await pool.query('DELETE FROM planner.erp_purchase_orders WHERE po=$1', [o.reference]);
    await pool.query("INSERT INTO planner.erp_purchase_orders (po, erp_po_id, supplier_name, status, synced_at) VALUES ($1,$2,$3,'open',now())", [o.reference, String(o.id), supplier_name]);
    if (!exists) await notePoCreated(pool, o.reference, authUser(req));
    res.json({ ok: true, imported: true, po: o.reference, lines: lines.length, supplier_name, branch, currency: o.currencyCode || null, cin7_id: o.id });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Bulk-upload POs from a pasted/uploaded list. Each row: PO (+ optional supplier/ship-to/branch/status/start
// + optional SKU/Qty). Rows are grouped by PO — a NEW PO is created from its header fields; an EXISTING PO is
// kept as-is (its details aren't overwritten). Any row carrying a SKU adds/updates an order-plan line
// (proposed, erp_qty=0 → shows as "not in ERP" until pushed). Repeat the PO across lines for multiple SKUs.
app.post('/api/supply/po-bulk', async (req, res) => {
  const rows = (req.body && req.body.rows) || [];
  if (!Array.isArray(rows) || !rows.length) return res.status(400).json({ error: 'no rows' });
  // group by PO, merging header fields (first non-empty wins) and collecting SKU/qty lines
  const byPo = {};
  for (const r of rows) {
    const po = (r.po || '').trim(); if (!po) continue;
    const g = byPo[po] || (byPo[po] = { po, supplier_name: '', country_code: '', branch: '', status: '', start_production: '', lines: [] });
    ['supplier_name', 'country_code', 'branch', 'status', 'start_production'].forEach(k => { if (!g[k] && r[k]) g[k] = String(r[k]).trim(); });
    const sku = (r.sku || '').toString().trim();
    if (sku) { const q = (r.qty === '' || r.qty == null) ? 0 : Math.round(Number(r.qty)); g.lines.push({ sku: sku.toUpperCase(), qty: isNaN(q) ? 0 : q }); }
  }
  let created = 0, existing = 0, lines = 0; const errors = [];
  for (const po of Object.keys(byPo)) {
    const g = byPo[po];
    try {
      const dup = await pool.query(`SELECT 1 FROM planner.purchase_orders WHERE po=$1`, [po]);
      if (!dup.rowCount) {
        let supId = null;
        if (g.supplier_name) { const s = await pool.query(`SELECT id FROM planner.suppliers WHERE name=$1 LIMIT 1`, [g.supplier_name]); supId = s.rows[0] ? s.rows[0].id : null; }
        await pool.query(`INSERT INTO planner.purchase_orders
          (po, supplier_name, supplier_id, country_code, branch, status, start_production)
          VALUES ($1,$2,$3,$4,$5,coalesce($6,'FUTURE'),$7)`,
          [po, g.supplier_name || null, supId, g.country_code || null, g.branch || null, g.status || null, g.start_production || null]);
        created++;
        await notePoCreated(pool, po, authUser(req));
      } else { existing++; }   // keep existing PO's details; only add its lines
      for (const l of g.lines) {
        if (!l.sku) continue;
        await pool.query(`INSERT INTO planner.purchase_order_lines (po_sku, po, sku, qty, erp_qty, proposed_at, proposed_by)
          VALUES ($1,$2,$3,$4::int,0,now(),'upload') ON CONFLICT (po_sku) DO UPDATE SET qty=excluded.qty, proposed_at=now(), proposed_by='upload'`,
          [po + '|' + l.sku, po, l.sku, l.qty]);
        lines++;
      }
    } catch (e) { errors.push(po + ': ' + e.message); }
  }
  if (created || existing || lines) invalidateSupplyCaches();   // POs written/updated → rebuild cached grids so they show without a hard refresh
  res.json({ created, existing, lines, errors });
});
// PO detail — the linked records across tables (lines, deposit, payments, flexport) for one PO.
// The shipment a PO rides on (its own self-shipment, or a master it's assigned to) + the FINAL calculated dates
// (override ▸ calc), mirroring the SHIPMENTS grid. Shared by po-detail and the mode-gate so both return eff dates.
async function poShipObj(po) {
  return (await pool.query(`
    SELECT coalesce(lower(s.mode),'') mode, coalesce(s.carrier,'') carrier, coalesce(s.carrier_ref,'') carrier_ref,
           coalesce(s.status,'') status,
           to_char(s.departure_date,'YYYY-MM-DD') departure_date, to_char(s.landing_date,'YYYY-MM-DD') landing_date,
           to_char(s.arrival_date,'YYYY-MM-DD') arrival_date, to_char(s.delivery_date,'YYYY-MM-DD') delivery_date,
           to_char(coalesce(s.departure_date, c.dep_calc),'YYYY-MM-DD') eff_departure,
           to_char(coalesce(s.landing_date, c.land_calc),'YYYY-MM-DD') eff_landing,
           to_char(coalesce(s.arrival_date, s.landing_date, c.land_calc),'YYYY-MM-DD') eff_arrival,
           to_char(coalesce(s.delivery_date, c.comp_calc),'YYYY-MM-DD') eff_completion,
           s.cost_manual, coalesce(s.branch,'') branch, coalesce(s.country_code,'') country_code,
           (s.shipment_ref = p.po) is_self,
           (SELECT count(*)::int FROM planner.purchase_orders x WHERE x.shipment_ref=s.shipment_ref AND x.po<>p.po) other_pos
    FROM planner.purchase_orders p JOIN planner.shipments s
      ON s.shipment_ref = coalesce(nullif(p.shipment_ref,''), (SELECT ss.shipment_ref FROM planner.shipments ss WHERE ss.master_po=p.po LIMIT 1))
    LEFT JOIN LATERAL (
      SELECT (pe + interval '7 days')::date dep_calc,
             (pe + interval '7 days' + ((CASE WHEN coalesce(lower(s.mode),'sea')='air' THEN coalesce(mb.air_lead_time_days,0) ELSE coalesce(mb.sea_lead_time_days,0) END)||' days')::interval)::date land_calc,
             (pe + interval '7 days' + ((CASE WHEN coalesce(lower(s.mode),'sea')='air' THEN coalesce(mb.air_lead_time_days,0) ELSE coalesce(mb.sea_lead_time_days,0) END)||' days')::interval + interval '7 days')::date comp_calc
      FROM planner.purchase_orders m
      LEFT JOIN planner.suppliers ms ON ms.id=m.supplier_id
      LEFT JOIN planner.branches mb ON mb.name=m.branch
      CROSS JOIN LATERAL (SELECT coalesce(m.end_production_overide, (m.start_production + (coalesce(ms.production_days,0)||' days')::interval)::date) pe) pec
      WHERE m.po = coalesce(nullif(s.master_po,''), s.shipment_ref) LIMIT 1
    ) c ON true
    WHERE p.po=$1`, [po])).rows[0] || null;
}
app.get('/api/supply/po-detail/:po', async (req, res) => {
  const po = req.params.po;
  try {
    const [lines, deposit, payments, flexport, supInv, supDocs, notes, subs, lineCosts, supComp, xdShip, addCosts, poMeta] = await Promise.all([
      pool.query(`SELECT l.sku,l.qty,l.carton_qty,l.full_carton_check,l.cost_price,
                    el.qty erp_qty, el.cost erp_cost,
                    (coalesce(l.qty,0) IS DISTINCT FROM coalesce(el.qty,0)) qty_pending,   -- 0 plan == absent from ERP → not a deviation
                    (l.cost_price IS DISTINCT FROM el.cost) cost_pending,
                    -- EXCEPTION: SKU not RELEASED in this PO's market (availability authoritative; launch ignored).
                    -- Direct-to-Client POs are excluded — a bespoke client order doesn't depend on retail-market availability.
                    (EXISTS (SELECT 1 FROM planner.purchase_orders pp LEFT JOIN planner.branches bb ON bb.name=pp.branch
                       WHERE pp.po=l.po AND coalesce(pp.branch,'') NOT ILIKE '%direct to client%'
                         AND upper(coalesce(nullif(pp.country_code,''), bb.country_code,'')) IN ('UK','US','EU','AU','CA')
                         AND NOT EXISTS (SELECT 1 FROM planner.v_product_availability va
                            WHERE va.sku=l.sku AND upper(va.country)=upper(coalesce(nullif(pp.country_code,''), bb.country_code,'')) AND va.is_available))) not_avail_market,
                    coalesce(pol.partial_carton_approved,false) partial_carton_approved,
                    coalesce(pol.supplier_risk_approved,false) supplier_risk_approved,
                    coalesce(pol.discontinue_approved,false) discontinue_approved,
                    coalesce(pol.country_risk_approved,false) country_risk_approved,
                    coalesce(sl.supplier_multiple_all,'') sm,
                    nullif(sl.discontinue_date_final,'') dis, nullif(sl.discontinue_date_au_final,'') dis_au, nullif(sl.discontinue_date_ca,'') dis_ca,
                    -- default unit cost from planner.products for the PO's supplier (cost_<lowercased supplier code>,
                    -- e.g. LX to cost_lx, XR to cost_xr), falling back to the general cost. Used as the order-plan Est.
                    -- cost when the line itself has no cost_price. (New suppliers auto-map via their code.)
                    coalesce(
                      CASE lower((SELECT s.code FROM planner.suppliers s JOIN planner.purchase_orders pp
                                    ON (s.id=pp.supplier_id OR s.name=pp.supplier_name) WHERE pp.po=l.po LIMIT 1))
                        WHEN 'lx' THEN sl.cost_lx WHEN 'xr' THEN sl.cost_xr END,
                      sl.cost) sku_cost
                  FROM planner.v_purchase_order_lines l
                  LEFT JOIN planner.erp_purchase_order_lines el ON el.po=l.po AND el.sku=l.sku
                  LEFT JOIN planner.purchase_order_lines pol ON pol.po_sku=l.po_sku
                  LEFT JOIN planner.products sl ON sl.sku=l.sku
                  WHERE l.po=$1 ORDER BY l.sku`, [po]),
      pool.query(`SELECT d.reference,d.supplier_name,d.amount,d.xero_fx,
                    to_char(d.date_paid,'YYYY-MM-DD') date_paid,d.deposit_used,d.deposit_remaining
                  FROM planner.deposits d JOIN planner.purchase_orders p ON p.deposit_ref=d.reference
                  WHERE p.po=$1`, [po]),
      pool.query(`SELECT to_char(payment_date,'YYYY-MM-DD') payment_date,transaction_type,
                    transaction_amount,transaction_supplier
                  FROM planner.payment_transactions
                  WHERE po_completion=$1 OR po_balance_1=$1 OR po_balance_2=$1 OR po_balance_3=$1
                  ORDER BY payment_date`, [po]),
      pool.query(`SELECT flex_id,mode,status_description status,
                    to_char(departure_date,'YYYY-MM-DD') departure,
                    to_char(landing_date,'YYYY-MM-DD') landing,
                    to_char(arrival_date,'YYYY-MM-DD') arrival,container_numbers,total_freight_cost
                  FROM planner.flexport_shipments
                  WHERE shipment_name=$1
                     OR shipment_name=(SELECT shipment_ref FROM planner.purchase_orders WHERE po=$1)`, [po]),
      // supplier-portal: latest submitted invoice value (+ id, status, doc) and all uploaded invoice docs
      pool.query(`SELECT id, value, status, submitted_by, to_char(submitted_at,'YYYY-MM-DD') submitted_at, attachment_id
                  FROM planner.supplier_submissions WHERE po=$1 AND kind='invoice_value' ORDER BY id DESC LIMIT 1`, [po]).catch(() => ({ rows: [] })),
      pool.query(`SELECT id, filename, coalesce(category,'invoice') category, coalesce(uploaded_by,'') uploaded_by, byte_size,
                    to_char(uploaded_at,'YYYY-MM-DD HH24:MI') uploaded_at,
                    coalesce(approval_status,'draft') approval_status, coalesce(review_notes,'') review_notes,
                    coalesce(submitted_by,'') submitted_by, to_char(submitted_at,'YYYY-MM-DD') submitted_at,
                    coalesce(reviewed_by,'') reviewed_by, to_char(reviewed_at,'YYYY-MM-DD') reviewed_at
                  FROM planner.portal_attachments WHERE po=$1 ORDER BY uploaded_at DESC`, [po]).catch(() => ({ rows: [] })),
      // PO PLAN Timeline: notes (supplier + internal) + submission status. supplier_name lets the timeline show
      // the exact submitting user AND their supplier (e.g. "XR Textile · yw11@xrtextile.com").
      pool.query(`SELECT n.id, n.author_kind, coalesce(n.author_email,'') author_email, n.body,
                    to_char(n.created_at,'DD-Mon-YY HH24:MI') created_at, n.read_at IS NOT NULL read,
                    coalesce(n.private,false) private, coalesce(n.mentions,'{}') mentions,
                    coalesce(s.name,'') supplier_name
                  FROM planner.supplier_notes n LEFT JOIN planner.suppliers s ON s.id=n.supplier_id
                  WHERE n.po=$1 ORDER BY n.created_at`, [po]).catch(() => ({ rows: [] })),
      pool.query(`SELECT kind, value, status, coalesce(submitted_by,'') submitted_by, to_char(submitted_at,'YYYY-MM-DD') submitted_at, attachment_id
                  FROM planner.supplier_submissions WHERE po=$1 ORDER BY submitted_at`, [po]).catch(() => ({ rows: [] })),
      // PO PLAN order plan: supplier-submitted actual cost + amended qty + added SKUs + D&B final cost per line
      pool.query(`SELECT plc.sku, plc.actual_cost, plc.final_cost, plc.amended_qty, coalesce(plc.is_added,false) is_added,
                    coalesce(pr.product_name,'') product_name,
                    coalesce(plc.submitted_by,'') submitted_by, to_char(plc.submitted_at,'YYYY-MM-DD') submitted_at,
                    plc.confirmed_at IS NOT NULL AND plc.confirmed_at >= plc.submitted_at confirmed,
                    (plc.actual_cost IS NOT NULL OR plc.amended_qty IS NOT NULL OR plc.is_added=true)
                      AND (plc.confirmed_at IS NULL OR plc.confirmed_at < plc.submitted_at) unconfirmed
                  FROM planner.portal_line_costs plc LEFT JOIN planner.products pr ON pr.sku=plc.sku WHERE plc.po=$1`, [po]).catch(() => ({ rows: [] })),
      // PO PLAN DATES: latest supplier-submitted completion date (+ id/status for approve/reject)
      pool.query(`SELECT id, value, status, coalesce(submitted_by,'') submitted_by, to_char(submitted_at,'YYYY-MM-DD') submitted_at
                  FROM planner.supplier_submissions WHERE po=$1 AND kind='completion_date' ORDER BY id DESC LIMIT 1`, [po]).catch(() => ({ rows: [] })),
      // CLIENT tab: supplier-entered crossdock shipped quantities for this PO
      pool.query(`SELECT sku, qty FROM planner.crossdock_shipments WHERE po=$1`, [po]).catch(() => ({ rows: [] })),
      // ORDER PLAN: supplier-entered additional cost lines for this PO
      pool.query(`SELECT id, coalesce(description,'') description, qty, price, coalesce(approved,false) approved FROM planner.portal_additional_costs WHERE po=$1 ORDER BY id`, [po]).catch(() => ({ rows: [] })),
      // ERP-deviation gate for THIS PO: only COMPLETE matters (deviations are quantity-only; price is never
      // an exception, so no cost-trigger signal is needed).
      pool.query(`SELECT coalesce(p.status,'') ILIKE '%complete%' AS is_complete
                  FROM planner.purchase_orders p WHERE p.po=$1`, [po]).catch(() => ({ rows: [] })),
    ]);
    // Crossdock SKUs across the shipment THIS PO is the master of (every PO on the shipment, incl. this one),
    // with supplier-entered shipped qty -> shown as derived rows in the master PO's ORDER PLAN.
    const xdMaster = await pool.query(`
      SELECT po.po, coalesce(po.supplier_name,'') supplier, coalesce(po.client,'') client,
             coalesce(po.sales_order_ref,'') sales_order_ref, trim(s.sku) sku, coalesce(cs.qty,0)::int qty
      FROM planner.purchase_orders po
      CROSS JOIN LATERAL unnest(string_to_array(coalesce(po.crossdock_skus,''),',')) AS s(sku)
      LEFT JOIN planner.crossdock_shipments cs ON cs.po=po.po AND cs.sku=trim(s.sku)
      WHERE po.shipment_ref IN (SELECT shipment_ref FROM planner.shipments WHERE master_po=$1)
        AND coalesce(po.status,'') NOT ILIKE '%complete%'
        AND trim(s.sku)<>'' ORDER BY po.po, sku`, [po]).catch(() => ({ rows: [] }));
    const lc = {}; lineCosts.rows.forEach(r => { lc[r.sku] = r; });
    const dtc = (await pool.query(`SELECT cartons, cbm, gross_weight_kg, dimensions, coalesce(entered_by,'') entered_by,
      to_char(updated_at,'YYYY-MM-DD HH24:MI') updated_at FROM planner.dtc_shipment_details WHERE po=$1`, [po])).rows[0] || null;
    const ship = await poShipObj(po);
    // Record-of-change audit trail (migration 158) — shown inline in the timeline, newest first. Defensive: empty if the table isn't there yet.
    const changes = await pool.query(`SELECT event, detail, coalesce(changed_by,'') changed_by,
      to_char(changed_at,'YYYY-MM-DD HH24:MI') created_at FROM planner.po_change_log WHERE po=$1 ORDER BY changed_at DESC LIMIT 200`, [po]).catch(() => ({ rows: [] }));
    // Quality-control docs shared across this PO's production / batch (same supplier), + any mapped directly to the PO. Migration 160.
    const qdocs = await pool.query(`SELECT qd.id, qd.doc_type, qd.filename, coalesce(qd.prod_no,'') prod_no, coalesce(qd.batch_id,'') batch_id,
        coalesce(qd.po,'') po, coalesce(qd.uploader_kind,'') uploader_kind, to_char(qd.created_at,'YYYY-MM-DD HH24:MI') created_at
      FROM planner.quality_docs qd JOIN planner.purchase_orders o ON o.po=$1
      WHERE (qd.po=o.po
             OR (coalesce(qd.prod_no,'')<>'' AND qd.prod_no=coalesce(o.prod_no,''))
             OR (coalesce(qd.batch_id,'')<>'' AND qd.batch_id=coalesce(o.batch_id,'')))
        AND (coalesce(qd.supplier_name,'')='' OR lower(qd.supplier_name)=lower(coalesce(o.supplier_name,'')))
      ORDER BY qd.created_at DESC LIMIT 200`, [po]).catch(() => ({ rows: [] }));
    // Child POs, if this PO is a consolidated master (drives the PO ▸ CHILD PO tab).
    const children = await pool.query(`SELECT p.po, coalesce(p.branch,'') branch, coalesce(p.client,'') client, coalesce(p.status,'') status,
        coalesce(f.value_est,0)::numeric value_est FROM planner.purchase_orders p JOIN planner.v_po_finance f ON f.po=p.po
      WHERE p.master_po=$1 ORDER BY p.po`, [po]).catch(() => ({ rows: [] }));
    // Price-list estimate → override each line's Est. cost (sku_cost) for this PO's supplier / production / qty
    try { const pl = await priceListEstIndex(); const _pm = (await pool.query(`SELECT coalesce(supplier_name,'') supplier_name, coalesce(prod_no,'') prod_no FROM planner.purchase_orders WHERE po=$1`, [po])).rows[0] || {}; const _pn = plProdNum(_pm.prod_no); lines.rows.forEach((l) => { const est = plEstimate(pl, _pm.supplier_name, l.sku, l.qty, _pn); if (est != null) l.sku_cost = est; }); } catch (e) { /* price list optional */ }
    res.json({ ship, lines: lines.rows, deposit: deposit.rows, payments: payments.rows, flexport: flexport.rows, dtc,
      children: children.rows,
      changes: changes.rows, quality_docs: qdocs.rows,
      crossdock_lines: xdMaster.rows,
      sup_invoice: supInv.rows[0] || null,
      sup_docs: supDocs.rows.filter(x => x.category !== 'client'),
      client_docs: supDocs.rows.filter(x => x.category === 'client'),
      all_docs: supDocs.rows,   // every document held for this PO (all categories) — PO ▸ DOCUMENTS tab
      notes: notes.rows, subs: subs.rows, line_costs: lc,
      sup_completion: supComp.rows[0] || null, crossdock_shipped: xdShip.rows, additional_costs: addCosts.rows,
      erp_complete: !!(poMeta.rows[0] && poMeta.rows[0].is_complete) });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// SHIPS-WITH master label fields for one PO. source supplier + production ref = this PO; ships-with supplier + PO
// = the supplier/ref of the master shipment this PO rides on (sh.master_po, fallback shipment_ref); plus dest + client.
app.get('/api/supply/ships-with/:po', async (req, res) => {
  try {
    const r = await pool.query(`
      SELECT po.po production_ref, coalesce(po.supplier_name,'') source_supplier,
             coalesce(po.shipment_ref,'') ships_with_po,
             coalesce(po.branch,'') dest_branch,
             coalesce(nullif(po.country_code,''), b.country_code, '') dest_country,
             coalesce(po.client,'') client, coalesce(po.sales_order_ref,'') sales_order_ref,
             coalesce(mpo.supplier_name,'') ships_with_supplier
      FROM planner.purchase_orders po
      LEFT JOIN planner.branches b ON b.name=po.branch
      LEFT JOIN planner.shipments sh ON sh.shipment_ref=po.shipment_ref
      LEFT JOIN planner.purchase_orders mpo ON mpo.po = coalesce(nullif(sh.master_po,''), sh.shipment_ref)
      WHERE po.po=$1`, [req.params.po]);
    res.json(r.rows[0] || {});
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Production detail (a prod_no × supplier): SKU × total qty, the POs, and assigned deposits.
app.get('/api/supply/production-detail/:prod', async (req, res) => {
  const prod = req.params.prod;
  const supplier = (req.query.supplier === '(no supplier)' ? '' : (req.query.supplier || ''));
  const supMatch = `coalesce(po.supplier_name,'')=$2`;
  try {
    const [skus, pos, deps] = await Promise.all([
      pool.query(`SELECT l.sku, coalesce(pr.product_name,'') name, coalesce(pr.category,'(uncategorised)') category,
          coalesce(sl.product_barcode,'') ean, sum(l.qty)::int qty, round(sum(l.qty*l.cost_price)) value
        FROM planner.purchase_order_lines l
        JOIN planner.purchase_orders po ON po.po=l.po
        LEFT JOIN planner.products pr ON pr.sku=l.sku
        LEFT JOIN planner.v_sku_attrs sl ON sl.sku=l.sku
        WHERE po.prod_no=$1 AND ${supMatch} GROUP BY l.sku, pr.product_name, pr.category, sl.product_barcode
        HAVING sum(l.qty) <> 0 ORDER BY category, l.sku`, [prod, supplier]),
      pool.query(`SELECT po.po, coalesce(po.supplier_name,'') supplier_name, coalesce(po.status,'') status,
          coalesce(po.country_code,'') country, coalesce(po.deposit_ref,'') deposit_ref,
          coalesce((SELECT sum(l.qty) FROM planner.purchase_order_lines l WHERE l.po=po.po),0)::int units
        FROM planner.purchase_orders po WHERE po.prod_no=$1 AND ${supMatch} ORDER BY po.po`, [prod, supplier]),
      pool.query(`SELECT pd.deposit_ref, coalesce(d.amount,0) amount, to_char(d.date_paid,'YYYY-MM-DD') date_paid,
          coalesce(d.supplier_name,'') dep_supplier
        FROM planner.production_deposits pd LEFT JOIN planner.deposits d ON d.reference=pd.deposit_ref
        WHERE pd.prod_no=$1 AND coalesce(pd.supplier_name,'')=$2 ORDER BY pd.deposit_ref`, [prod, supplier]),
    ]);
    res.json({ skus: skus.rows, pos: pos.rows, deposits: deps.rows });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Assign / unassign a deposit to a production (prod_no × supplier).
app.post('/api/supply/production-deposit', async (req, res) => {
  const b = req.body || {}; const sup = (b.supplier_name === '(no supplier)' ? '' : (b.supplier_name || ''));
  if (!b.prod_no || !b.deposit_ref) return res.status(400).json({ error: 'prod_no + deposit_ref required' });
  try {
    if (b.assign === false) {
      await pool.query(`DELETE FROM planner.production_deposits WHERE prod_no=$1 AND coalesce(supplier_name,'')=$2 AND deposit_ref=$3`, [b.prod_no, sup, b.deposit_ref]);
    } else {
      await pool.query(`INSERT INTO planner.production_deposits (prod_no, supplier_name, deposit_ref)
        VALUES ($1,$2,$3) ON CONFLICT DO NOTHING`, [b.prod_no, sup, b.deposit_ref]);
    }
    res.json({ ok: true });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Create a deposit FOR a production (prod_no × supplier) and assign it. Reference auto-formats as
// {prod_no}-{supplier 2-digit code}-{n}; amount defaults to 30% of the production value LESS deposits
// already assigned to it; date defaults to today. All editable afterwards in the deposits table.
app.post('/api/supply/production-deposit-create', async (req, res) => {
  const b = req.body || {}; const prod = b.prod_no;
  const sup = (b.supplier_name === '(no supplier)' ? '' : (b.supplier_name || ''));
  if (!prod) return res.status(400).json({ error: 'prod_no required' });
  try {
    const codeRow = (await pool.query(`SELECT coalesce(nullif(code,''), upper(left(name,2))) c FROM planner.suppliers WHERE name=$1 LIMIT 1`, [sup])).rows[0];
    const sc = (codeRow && codeRow.c) || (sup ? sup.replace(/[^A-Za-z]/g, '').slice(0, 2).toUpperCase() : 'NA');
    const val = Number((await pool.query(`SELECT coalesce(sum(l.qty*l.cost_price),0) v
      FROM planner.purchase_order_lines l JOIN planner.purchase_orders po ON po.po=l.po
      WHERE po.prod_no=$1 AND coalesce(po.supplier_name,'')=$2`, [prod, sup])).rows[0].v);
    const assigned = Number((await pool.query(`SELECT coalesce(sum(d.amount),0) a
      FROM planner.production_deposits pd JOIN planner.deposits d ON d.reference=pd.deposit_ref
      WHERE pd.prod_no=$1 AND coalesce(pd.supplier_name,'')=$2`, [prod, sup])).rows[0].a);
    const amount = Math.max(0, Math.round(0.30 * val - assigned));
    let n = 1 + Number((await pool.query(`SELECT count(*) c FROM planner.production_deposits WHERE prod_no=$1 AND coalesce(supplier_name,'')=$2`, [prod, sup])).rows[0].c);
    let ref;
    for (;;) { ref = `${prod}-${sc}-${n}`;
      const exists = await pool.query(`SELECT 1 FROM planner.deposits WHERE reference=$1`, [ref]);
      if (!exists.rowCount) break; n++; }
    await pool.query(`INSERT INTO planner.deposits (reference, is_deposit, supplier_name, prod_no, amount, date_paid)
      VALUES ($1,true,$2,$3,$4,CURRENT_DATE)`, [ref, sup || null, prod, amount]);
    await pool.query(`INSERT INTO planner.production_deposits (prod_no, supplier_name, deposit_ref)
      VALUES ($1,$2,$3) ON CONFLICT DO NOTHING`, [prod, sup, ref]);
    res.json({ ok: true, reference: ref, amount });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Record the actual paid currency + amount for a payment (date × supplier) — alt to the USD legs.
app.post('/api/supply/payment-fx', async (req, res) => {
  const b = req.body || {};
  if (!b.run_date || !b.supplier) return res.status(400).json({ error: 'run_date + supplier required' });
  try {
    // A run is "confirmed paid" once it has BOTH a bank amount and a bank currency. Capture the prior state so we
    // only notify on the transition unconfirmed → confirmed (editing an already-confirmed run won't re-email).
    const prev = (await pool.query(`SELECT paid_amount, coalesce(paid_currency,'') paid_currency FROM planner.payment_fx WHERE run_date=$1 AND supplier=$2`, [b.run_date, b.supplier])).rows[0];
    const wasConfirmed = !!(prev && prev.paid_amount != null && prev.paid_currency);
    const newAmt = (b.paid_amount === '' || b.paid_amount == null) ? null : b.paid_amount;
    const newCcy = b.paid_currency || null;
    await pool.query(`INSERT INTO planner.payment_fx (run_date, supplier, paid_currency, paid_amount)
      VALUES ($1,$2,$3,$4) ON CONFLICT (run_date, supplier) DO UPDATE
      SET paid_currency=excluded.paid_currency, paid_amount=excluded.paid_amount, updated_at=now()`,
      [b.run_date, b.supplier, newCcy, newAmt]);
    const nowConfirmed = (newAmt != null && newCcy && String(newCcy).trim() !== '');
    let emailPreview;
    if (nowConfirmed && !wasConfirmed) {   // fire the supplier payment-confirmed notification ONCE, on transition — IMMEDIATELY (no delay)
      const runKey = b.run_date + '|' + b.supplier;
      try { const em = await emailPaymentConfirmed(b.run_date, b.supplier, newAmt, newCcy);
        // sandbox (no RESEND key) → hand the rendered email back so the UI can pop it up for testing; prod sends silently
        if (!process.env.RESEND_API_KEY && em && em.preview) emailPreview = em.preview;
        // record the outcome so the Payments Report shows "✉ emailed" (or skipped when no recipient opted in). Best-effort.
        const to = (em && em.preview && em.preview.to) || [];
        if (to.length) { try { await pool.query(`INSERT INTO planner.payment_emails (run_key, supplier_name, to_emails, amount, currency, pay_date, send_after, status, sent_at, created_by)
          VALUES ($1,$2,$3,$4,$5,$6::date,now(),'sent',now(),$7)`, [runKey, b.supplier, to.join(', '), newAmt, newCcy, b.run_date, authUser(req) || 'system']); } catch (e2) {} }
      } catch (e) { console.error('[payment-confirmed email]', e.message);
        try { await pool.query(`INSERT INTO planner.payment_emails (run_key, supplier_name, to_emails, amount, currency, pay_date, send_after, status, error, created_by)
          VALUES ($1,$2,'',$3,$4,$5::date,now(),'failed',$6,$7)`, [runKey, b.supplier, newAmt, newCcy, b.run_date, String(e.message || e).slice(0, 300), authUser(req) || 'system']); } catch (e2) {} }
    }
    res.json({ ok: true, confirmed: nowConfirmed, emailPreview });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Shipment detail — the POs aboard a shipment (master first).
app.get('/api/supply/shipment-detail/:ref', async (req, res) => {
  try {
    const { rows } = await pool.query(`
      SELECT po.po, po.supplier_name, coalesce(po.status,'') status,
        coalesce(po.client,'') client, coalesce(po.sales_order_ref,'') sales_order_ref, coalesce(po.branch,'') branch,
        (po.po = coalesce((SELECT master_po FROM planner.shipments WHERE shipment_ref=$1), $1)) is_master,
        coalesce((SELECT sum(l.qty) FROM planner.purchase_order_lines l WHERE l.po=po.po),0)::int units,
        round(coalesce((SELECT sum(l.qty*l.cost_price) FROM planner.purchase_order_lines l WHERE l.po=po.po),0)) value
      FROM planner.purchase_orders po WHERE po.shipment_ref=$1
      ORDER BY is_master DESC, po.po`, [req.params.ref]);
    res.json(rows);
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Shipment edit (upsert) — carrier/ref/master/status/notes + the date OVERRIDES that win over the
// POs aboard. Row may not exist yet (a shipment_ref freshly typed onto a PO), so insert-on-conflict.
const SHIP_FIELDS = {
  master_po: 'text', carrier: 'text', carrier_ref: 'text', status: 'text', notes: 'text', mode: 'text',
  starred: 'boolean',   // ⭐ Focus / favourite toggle (migration 082)
  cost_manual: 'numeric', tracked_delivery_date: 'date', tracked_source: 'text',
  departure_date: 'date', landing_date: 'date', delivery_date: 'date', arrival_date: 'date',
  branch: 'text', country_code: 'text',   // shipment-level destination override (inherits from master PO)
  export_port: 'text',   // override; blank = inherit the master PO supplier's export_port
  delivery_notes: 'text',   // shipment-level branch delivery notes override (inherits from the master PO)
};
// Shipment record-of-change: which fields are worth logging on the shipment timeline (mirrors PO_TRACK).
const SHIP_TRACK = { master_po: 'Master PO', carrier: 'Carrier', carrier_ref: 'Carrier ref', status: 'Status', mode: 'Mode',
  cost_manual: 'Freight cost', departure_date: 'Ship / departure date', landing_date: 'Landing date',
  delivery_date: 'Delivery date', arrival_date: 'Arrival date', tracked_delivery_date: 'Tracked delivery date',
  branch: 'Destination branch', export_port: 'Export port' };
async function logShipChange(ref, event, detail, by) {
  try { await pool.query(`INSERT INTO planner.shipment_change_log (shipment_ref, event, detail, changed_by) VALUES ($1,$2,$3,$4)`, [ref, event, detail || null, by || null]); }
  catch (e) { /* table absent pre-migration 165 — non-fatal */ }
}
async function logShipFieldChanges(ref, oldRow, body, by) {
  const numish = (s) => s !== '' && s != null && !isNaN(Number(s));
  for (const k of Object.keys(SHIP_TRACK)) {
    if (body[k] === undefined) continue;
    let nv = (body[k] === '' || body[k] == null) ? '' : String(body[k]).trim();
    let ov = (oldRow[k] == null) ? '' : String(oldRow[k]).trim();
    const isDate = /_date$/.test(k);
    if (isDate) { ov = ov.slice(0, 10); nv = nv.slice(0, 10); }
    if (numish(ov) && numish(nv)) { if (Number(ov) === Number(nv)) continue; } else if (ov === nv) continue;
    let fov = ov, fnv = nv;
    if (isDate) { fov = ov ? ddMonYy(ov) : ''; fnv = nv ? ddMonYy(nv) : ''; const dl = dateDeltaLabel(ov, nv); if (dl) fnv = fnv + ' ' + dl; }
    else if (k === 'cost_manual') { const m = (v) => Number(v).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); if (numish(ov)) fov = m(ov); if (numish(nv)) fnv = m(nv); }
    const f = (v) => v === '' ? '(blank)' : v;
    await logShipChange(ref, SHIP_TRACK[k], f(fov) + ' → ' + f(fnv), by);
  }
}
app.post('/api/supply/shipment/:ref', async (req, res) => {
  const ref = req.params.ref;
  const cols = ['shipment_ref'], vals = [ref], ph = ['$1::text']; let i = 2;
  for (const k of Object.keys(req.body || {})) {
    if (!SHIP_FIELDS[k]) continue;
    cols.push(k); vals.push(req.body[k] === '' ? null : req.body[k]); ph.push(`$${i++}::${SHIP_FIELDS[k]}`);
  }
  const upd = cols.slice(1).map(c => `${c}=excluded.${c}`).join(',') || 'updated_at=now()';
  // Snapshot (pre-change) the shipment's dates + each aboard PO's effective completion (checkin), so we can log the
  // cascade on every PO whose inherited date shifts (record of change extends to shipment-driven date recalcs).
  let _oldShip = null, _preCheckin = {}, _oldShipFull = null;
  try {
    _oldShip = (await pool.query(`SELECT departure_date::text dep, landing_date::text land, delivery_date::text del, arrival_date::text arr, tracked_delivery_date::text trk FROM planner.shipments WHERE shipment_ref=$1`, [ref])).rows[0] || null;
    _oldShipFull = (await pool.query(`SELECT master_po, carrier, carrier_ref, status, mode, cost_manual::text, departure_date::text, landing_date::text, delivery_date::text, arrival_date::text, tracked_delivery_date::text, branch, export_port FROM planner.shipments WHERE shipment_ref=$1`, [ref])).rows[0] || null;
    const _pa = (await pool.query(`SELECT po FROM planner.purchase_orders WHERE shipment_ref=$1 UNION SELECT master_po FROM planner.shipments WHERE shipment_ref=$1 AND coalesce(master_po,'')<>''`, [ref])).rows.map(x => x.po);
    if (_pa.length) (await queryCapped(PO_ROWS_SQL + ' WHERE calc4.po = ANY($1)', [_pa])).rows.forEach(r => { _preCheckin[r.po] = r.checkin ? String(r.checkin).slice(0, 10) : ''; });
  } catch (e) { /* snapshot best-effort */ }
  try {
    const up = await pool.query(`INSERT INTO planner.shipments (${cols.join(',')}) VALUES (${ph.join(',')})
      ON CONFLICT (shipment_ref) DO UPDATE SET ${upd}, updated_at=now() RETURNING (xmax = 0) AS inserted`, vals);
    if (up.rows[0] && up.rows[0].inserted) await noteShipmentCreated(pool, ref, authUser(req));
    // status → Shipping advances the POs on board (same as the "→ set shipping" action / supplier portal)
    if ((req.body || {}).status === 'Shipping') await propagateShippingToPOs(ref);
    // Step 3: a shipment date change cascades to every PO aboard (they inherit the master's effective dates).
    // Return all affected rows recomputed in ONE response so the client repaints them without N separate fetches.
    let rows = [];
    try {
      const aboard = (await pool.query(
        `SELECT po FROM planner.purchase_orders WHERE shipment_ref=$1
         UNION SELECT master_po FROM planner.shipments WHERE shipment_ref=$1 AND coalesce(master_po,'')<>''`, [ref])).rows.map(x => x.po);
      if (aboard.length) rows = (await queryCapped(PO_ROWS_SQL + ' WHERE calc4.po = ANY($1)', [aboard])).rows;
    } catch (e) { /* non-fatal — client falls back to per-PO refresh */ }
    // Record of change: for every aboard PO whose effective completion shifted from the shipment date edit, log it.
    try {
      const DL = { dep: 'ship date', del: 'delivery date', land: 'landing date', arr: 'arrival date', trk: 'tracked delivery date' };
      const FK = { dep: 'departure_date', del: 'delivery_date', land: 'landing_date', arr: 'arrival_date', trk: 'tracked_delivery_date' };
      const changed = _oldShip ? Object.keys(DL).filter(k => (req.body || {})[FK[k]] !== undefined && String(_oldShip[k] || '').slice(0, 10) !== String((req.body[FK[k]] || '')).slice(0, 10)) : [];
      if (changed.length && rows.length) {
        const shipMaster = (await pool.query(`SELECT coalesce(nullif(master_po,''),shipment_ref) m FROM planner.shipments WHERE shipment_ref=$1`, [ref])).rows[0]?.m || ref;
        const dateBits = changed.map(k => DL[k] + ' → ' + (req.body[FK[k]] ? ddMonYy(String(req.body[FK[k]]).slice(0, 10)) : '(cleared)')).join(', ');
        const by = authUser(req);
        for (const r of rows) {
          const oldC = _preCheckin[r.po] || '', newC = r.checkin ? String(r.checkin).slice(0, 10) : '';
          if (oldC !== newC) {
            const delta = dateDeltaLabel(oldC, newC);
            logPoChange(r.po, 'Shipment date', 'Shipment ' + shipMaster + ' ' + dateBits + '. Completion recalculated to ' + (newC ? ddMonYy(newC) : '(none)') + (delta ? ' ' + delta : ''), by);
          }
        }
      }
    } catch (e) { /* cascade log best-effort */ }
    // Record of change on the SHIPMENT's own timeline (field edits: carrier / status / mode / freight / dates).
    try { if (_oldShipFull) await logShipFieldChanges(ref, _oldShipFull, req.body, authUser(req)); } catch (e) { /* best-effort */ }
    res.json({ ok: true, rows });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Create a new shipment (header only; POs are assigned separately). master_po defaults to the ref.
app.post('/api/supply/shipment-create', async (req, res) => {
  const ref = (req.body && req.body.shipment_ref || '').trim();
  if (!ref) return res.status(400).json({ error: 'shipment_ref required' });
  try {
    const ins = await pool.query(`INSERT INTO planner.shipments (shipment_ref, master_po, carrier, carrier_ref)
      VALUES ($1,$2,$3,$4) ON CONFLICT (shipment_ref) DO NOTHING RETURNING shipment_ref`,
      [ref, (req.body.master_po || ref), req.body.carrier || null, req.body.carrier_ref || null]);
    if (ins.rowCount) await noteShipmentCreated(pool, ref, authUser(req));
    res.json({ ok: true, shipment_ref: ref });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Delete a now-empty SELF-shipment (its master IS itself) left orphaned when its only PO was reassigned away.
// Guarded: only when no POs reference it AND it has no supplier charges (protects money/claim data). Notes are removed with it.
async function pruneEmptySelfShipment(db, ref) {
  if (!ref) return false;
  const ok = (await db.query(`SELECT 1 FROM planner.shipments s
    WHERE s.shipment_ref=$1 AND coalesce(nullif(s.master_po,''), s.shipment_ref)=s.shipment_ref
      AND NOT EXISTS (SELECT 1 FROM planner.purchase_orders p WHERE p.shipment_ref=$1)
      AND NOT EXISTS (SELECT 1 FROM planner.supplier_charges c WHERE c.source_type='shipment' AND c.source_ref=$1)`, [ref])).rows[0];
  if (!ok) return false;
  await db.query(`DELETE FROM planner.shipment_notes WHERE shipment_ref=$1`, [ref]);
  await db.query(`DELETE FROM planner.shipments WHERE shipment_ref=$1`, [ref]);
  return true;
}
// Assign / unassign a PO to a shipment, and optionally mark it the master (consolidation) PO.
// body: { po, assign:true|false, master:true }. Unassign clears purchase_orders.shipment_ref.
app.post('/api/supply/shipment/:ref/assign', async (req, res) => {
  const ref = req.params.ref, b = req.body || {};
  if (!b.po) return res.status(400).json({ error: 'po required' });
  try {
    const prior = ((await pool.query(`SELECT shipment_ref FROM planner.purchase_orders WHERE po=$1`, [b.po])).rows[0] || {}).shipment_ref;
    if (b.assign === false) {
      await pool.query(`UPDATE planner.purchase_orders SET shipment_ref=NULL WHERE po=$1`, [b.po]);
      await pool.query(`UPDATE planner.shipments SET master_po=NULL, updated_at=now()
        WHERE shipment_ref=$1 AND master_po=$2`, [ref, b.po]);
    } else {
      const ins = await pool.query(`INSERT INTO planner.shipments (shipment_ref, master_po) VALUES ($1,$1)
        ON CONFLICT (shipment_ref) DO NOTHING RETURNING shipment_ref`, [ref]);
      if (ins.rowCount) await noteShipmentCreated(pool, ref, authUser(req));
      await pool.query(`UPDATE planner.purchase_orders SET shipment_ref=$2 WHERE po=$1`, [b.po, ref]);
      if (b.master) await pool.query(`UPDATE planner.shipments SET master_po=$2, updated_at=now()
        WHERE shipment_ref=$1`, [ref, b.po]);
    }
    // the PO's PRIOR shipment may now be an empty self-shipment → clean it up
    if (prior) await pruneEmptySelfShipment(pool, prior);
    res.json({ ok: true });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});
// Delete a shipment. Unassigns every PO aboard (clears their shipment_ref), removes its timeline notes,
// then deletes the shipment row. POs themselves are left intact.
app.post('/api/supply/shipment/:ref/delete', async (req, res) => {
  const ref = req.params.ref;
  const client = await pool.connect();
  try {
    await client.query('BEGIN');
    const unassigned = await client.query(`UPDATE planner.purchase_orders SET shipment_ref=NULL WHERE shipment_ref=$1`, [ref]);
    await client.query(`DELETE FROM planner.shipment_notes WHERE shipment_ref=$1`, [ref]);
    const r = await client.query(`DELETE FROM planner.shipments WHERE shipment_ref=$1`, [ref]);
    await client.query('COMMIT');
    res.json({ deleted: r.rowCount, unassigned_pos: unassigned.rowCount });
  } catch (e) { await client.query('ROLLBACK'); log500(e); res.status(500).json({ error: e.message }); }
  finally { client.release(); }
});
// SELF-SHIPMENT mode gate (PO ▸ SHIPMENTS). Picking a mode turns the PO into its own shipment (a planner.shipments
// row whose shipment_ref = the PO, master_po = the PO) so it flows through all the existing shipment machinery
// (portal, freight/duty calc, timeline). Clearing the mode tears the self-shipment down. branch=Manufacturing is
// always FOB. Only applies to the PO's OWN shipment — if it's assigned to a different master, mode is inherited.
app.post('/api/supply/po/:po/ship-mode', async (req, res) => {
  const po = req.params.po;
  let mode = String((req.body || {}).mode || '').trim().toLowerCase();
  if (mode && !['sea', 'air', 'fob'].includes(mode)) return res.status(400).json({ error: 'mode must be sea, air, fob or blank' });
  const client = await pool.connect();
  try {
    const p = (await client.query(`SELECT coalesce(branch,'') branch, coalesce(country_code,'') country_code, shipment_ref FROM planner.purchase_orders WHERE po=$1`, [po])).rows[0];
    if (!p) return res.status(404).json({ error: 'PO ' + po + ' not found' });
    if (p.shipment_ref && p.shipment_ref !== po) return res.status(409).json({ error: 'PO is assigned to shipment ' + p.shipment_ref + ' — its mode is inherited from that shipment, not set here.' });
    const manufacturing = /manufactur/i.test(p.branch);
    if (mode && manufacturing) mode = 'fob';   // Manufacturing branch is always FOB (factory pickup, no transit detail)
    await client.query('BEGIN');
    if (!mode) {
      const others = (await client.query(`SELECT count(*)::int n FROM planner.purchase_orders WHERE shipment_ref=$1 AND po<>$1`, [po])).rows[0].n;
      if (others > 0) { await client.query('ROLLBACK'); return res.status(409).json({ error: 'This shipment has ' + others + ' other PO(s) aboard — manage it as a master shipment instead of clearing the mode here.' }); }
      await client.query(`UPDATE planner.purchase_orders SET shipment_ref=NULL WHERE po=$1 AND shipment_ref=$1`, [po]);
      await client.query(`DELETE FROM planner.shipment_notes WHERE shipment_ref=$1`, [po]);
      await client.query(`DELETE FROM planner.shipments WHERE shipment_ref=$1`, [po]);
      await client.query('COMMIT');
      const row0 = (await queryCapped(PO_ROWS_SQL + ' WHERE calc4.po=$1', [po])).rows[0] || null;
      return res.json({ ok: true, mode: '', is_shipment: false, ship: null, row: row0 });
    }
    const ins = await client.query(`INSERT INTO planner.shipments (shipment_ref, master_po, mode, branch, country_code)
      VALUES ($1,$1,$2,NULLIF($3,''),NULLIF($4,''))
      ON CONFLICT (shipment_ref) DO UPDATE SET mode=$2,
        branch=coalesce(planner.shipments.branch, NULLIF($3,'')),
        country_code=coalesce(planner.shipments.country_code, NULLIF($4,'')),
        updated_at=now()
      RETURNING (xmax=0) created`, [po, mode, p.branch, p.country_code]);
    if (ins.rows[0] && ins.rows[0].created) await noteShipmentCreated(client, po, authUser(req));
    await client.query(`UPDATE planner.purchase_orders SET shipment_ref=$1 WHERE po=$1`, [po]);
    await client.query('COMMIT');
    const ship = await poShipObj(po);   // includes the FINAL calculated dates so the client can fill them silently
    const row1 = (await queryCapped(PO_ROWS_SQL + ' WHERE calc4.po=$1', [po])).rows[0] || null;   // recomputed grid row (ship/landing/delivery dates) so the main PO grid stays bound
    res.json({ ok: true, mode, is_shipment: true, manufacturing, ship, row: row1 });
  } catch (e) { try { await client.query('ROLLBACK'); } catch (_) {} res.status(500).json({ error: e.message }); }
  finally { client.release(); }
});

// ── SCENARIO PLANNER ───────────────────────────────────────────────────────
// Prime Day: inventory by SKU split into FBA / 3PL / AWD per the selected market(s).
// v_product_inventory warehouses are '{country}_{type}' (uk_3pl, us_fba, …), sourced from
// planner.products.inventory_*. AWD (inventory_us_awd) is a separate US pool, added on below.
// SALES PLANNING — per SKU for a country + channel (3pl|fba) + month: current on-hand, projected stock at
// the start of that month, weeks of cover at that date, and whether it's discontinued by then. Numbers come
// from the latest committed SKU-level forecast run. FBA cover pool = FBA + AWD (US); 3PL is returned as a
// separate transferable figure (shown as its own column, NOT in the FBA cover math). Projected = pool
// on-hand + inbound landing before the month − forecast sell-through before the month. Cover = projected
// ÷ (selected month's forecast ÷ 4.33).
app.post('/api/scenario/sales-planning', async (req, res) => {
  const b = req.body || {};
  const country = String(b.country || '').toUpperCase();
  const channel = String(b.channel || '3pl').toLowerCase() === 'fba' ? 'fba' : '3pl';
  const month = String(b.month || '').slice(0, 7);
  if (!/^[A-Z]{2}$/.test(country) || !/^\d{4}-\d{2}$/.test(month)) return res.status(400).json({ error: 'country + month (YYYY-MM) required' });
  const co = country.toLowerCase(), monthStart = month + '-01', isUS = country === 'US';
  const wh3 = co + '_3pl', whF = co + '_fba';
  const pools = channel === 'fba' ? [whF] : [wh3];            // projection pool: FBA (+AWD) for fba, 3PL for 3pl. 3PL is shown as a separate transferable column on the FBA report, not in the cover math.
  const fchs = channel === 'fba' ? ['FBA'] : ['DTC', 'B2B', 'TIK'];  // sales channels the warehouse fulfils (TIK folds into the 3PL pool like DTC)
  const discCol = country === 'AU' ? 'discontinue_date_au_final' : country === 'CA' ? 'discontinue_date_ca' : 'discontinue_date_final';
  try {
    const run = (await pool.query(`SELECT max(run_id) mx FROM planner.forecasts WHERE level='sku'`)).rows[0].mx;
    // SKUs available in this country + channel (3pl ↔ DTC/B2B, fba ↔ FBA)
    const availSkus = (await pool.query(`SELECT DISTINCT sku FROM planner.v_product_availability
        WHERE upper(country)=$1 AND channel = ANY($2) AND is_available`, [country, fchs])).rows.map(r => r.sku);
    if (!availSkus.length) return res.json({ rows: [], country, channel, month });
    // inventory for the pooled warehouses
    const inv = {}; (await pool.query(`SELECT sku, warehouse, available FROM planner.v_product_inventory WHERE warehouse = ANY($1)`, [[wh3, whF]])).rows
      .forEach(r => { (inv[r.sku] || (inv[r.sku] = {}))[r.warehouse] = Number(r.available) || 0; });
    // product meta: name, per-country discontinue, AWD (US)
    const meta = {}; (await pool.query(`SELECT sku, coalesce(product_name,'') name,
        nullif(${discCol},'') disc, coalesce(inventory_us_awd,0)::int awd FROM planner.products WHERE in_planning_scope`)).rows
      .forEach(r => { meta[r.sku] = r; });
    // inbound landing BEFORE the month (real inbound feed + open POs with the same calc ETA as the SUPPLY view)
    const inbBefore = {}; (await pool.query(`SELECT sku, sum(qty)::int q FROM (
        SELECT sku, (quantity-coalesce(received_quantity,0)) qty FROM planner.inbound_shipments
          WHERE coalesce(received_quantity,0) < quantity AND destination_warehouse = ANY($1)
            AND estimated_delivery_date IS NOT NULL AND to_char(estimated_delivery_date,'YYYY-MM-DD') < $2
        UNION ALL
        SELECT l.sku, l.qty FROM planner.purchase_order_lines l
          JOIN planner.purchase_orders po ON po.po=l.po
          LEFT JOIN planner.branches b ON b.name=po.branch
          LEFT JOIN planner.suppliers s ON s.id=po.supplier_id
          WHERE coalesce(l.qty,0)>0 AND coalesce(po.status,'') NOT ILIKE '%complete%'
            AND (lower(coalesce(nullif(po.country_code,''), b.country_code)) || '_' || (CASE WHEN po.branch ILIKE '%fba%' THEN 'fba' ELSE '3pl' END)) = ANY($1)
            AND NOT EXISTS (SELECT 1 FROM planner.inbound_shipments i WHERE i.reference=po.po)
            AND to_char((coalesce(po.end_production_overide, CASE WHEN po.start_production IS NOT NULL AND s.production_days IS NOT NULL
                  THEN (po.start_production + (s.production_days||' days')::interval)::date END)
                + interval '7 days' + (b.sea_lead_time_days||' days')::interval)::date,'YYYY-MM-DD') < $2
      ) z GROUP BY sku`, [pools, monthStart])).rows.forEach(r => { inbBefore[r.sku] = Number(r.q) || 0; });
    // forecast: demand before the month + the selected month's demand (for the weekly cover rate)
    const fc = {}; (await pool.query(`SELECT sku,
        coalesce(sum(units) FILTER (WHERE to_char(month,'YYYY-MM') >= to_char(CURRENT_DATE,'YYYY-MM') AND to_char(month,'YYYY-MM') < $3),0)::int dem_before,
        coalesce(sum(units) FILTER (WHERE to_char(month,'YYYY-MM') = $3),0)::int dem_month
      FROM planner.forecasts WHERE level='sku' AND run_id=$1 AND upper(country)=$2 AND channel = ANY($4)
      GROUP BY sku`, [run, country, month, fchs])).rows.forEach(r => { fc[r.sku] = r; });
    // trailing velocity + last sale for slow-moving / clearance flags (same basis as the Slow Moving report:
    // units sold in the channel(s) over the last ~13 weeks). SLOW = >26wk trailing cover (or no recent sales);
    // CLEARANCE = discontinued with stock that won't clear by the month, OR a badly overstocked slow mover.
    const VEL_WEEKS = 13, SLOW_WKS = 26, CLR_WKS = 52;
    const vel = {}; (await pool.query(`SELECT sku,
        coalesce(sum(units) FILTER (WHERE month > (SELECT max(month) FROM planner.sales_actuals) - interval '3 months'),0)::numeric sold3,
        to_char(max(month) FILTER (WHERE units>0),'YYYY-MM-DD') last_m
      FROM planner.sales_actuals WHERE upper(country)=$1 AND channel = ANY($2) GROUP BY sku`, [country, fchs]))
      .rows.forEach(r => { vel[r.sku] = r; });
    const nowMs = Date.now();
    const rows = availSkus.map(sku => {
      const m = meta[sku] || {}, iv = inv[sku] || {}, f = fc[sku] || { dem_before: 0, dem_month: 0 }, vv = vel[sku] || {};
      const oh3 = iv[wh3] || 0, ohF = channel === 'fba' ? (iv[whF] || 0) : 0, ohAwd = (channel === 'fba' && isUS) ? (m.awd || 0) : 0;
      const ohTotal = channel === 'fba' ? (ohF + ohAwd) : oh3;   // FBA cover pool = FBA + AWD; 3PL is separate/transferable
      const inb = inbBefore[sku] || 0, demB = Number(f.dem_before) || 0, demM = Number(f.dem_month) || 0;
      const projected = ohTotal + inb - demB;
      const rate = demM / 4.33;   // weekly sell-through in the selected month
      const weeks = rate > 0 ? Math.round(Math.max(0, projected) / rate * 10) / 10 : null;  // null = no forecast → infinite cover
      const discontinued = !!(m.disc && m.disc < monthStart);
      const trailVel = (Number(vv.sold3) || 0) / VEL_WEEKS;
      const trailCover = ohTotal > 0 ? (trailVel > 0 ? Math.round(ohTotal / trailVel) : null) : 0;  // null = has stock, no trailing sales
      const daysSince = vv.last_m ? Math.round((nowMs - Date.parse(vv.last_m)) / 864e5) : null;
      const slowMoving = ohTotal > 0 && (trailVel === 0 || (trailCover != null && trailCover > SLOW_WKS));
      const recClearance = (discontinued && projected > 0) || (slowMoving && (trailVel === 0 || (trailCover != null && trailCover > CLR_WKS)));
      return { sku, name: m.name || '', oh_fba: ohF, oh_awd: ohAwd, oh_3pl: oh3, oh_total: ohTotal,
        inbound_before: inb, dem_before: demB, projected, dem_month: demM, weeks, discontinued,
        trail_cover: trailCover, days_since: daysSince, slow_moving: slowMoving, rec_clearance: recClearance };
    });
    res.json({ rows, country, channel, month, isUS, forecast_run: run });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});

app.post('/api/scenario/prime-day', async (req, res) => {
  const b = req.body || {};
  const skus = Array.isArray(b.skus) ? b.skus.filter(Boolean).map(s => s.trim().toUpperCase()) : [];
  const country = (b.country || '').toLowerCase(); // '' = all markets
  const category = b.category || '';
  const where = [], vals = []; let i = 1;
  if (skus.length) { where.push(`upper(p.sku) = ANY($${i++})`); vals.push(skus); }
  if (category) { where.push(`p.category = $${i++}`); vals.push(category); }
  if (country) { where.push(`pi.warehouse LIKE $${i++}`); vals.push(country + '\\_%'); }
  const wsql = where.length ? 'WHERE ' + where.join(' AND ') : '';
  const awdApplies = (country === '' || country === 'us'); // AWD is a US warehouse
  const pAwd = i++, pSkuFlag = i; // param indexes for awdApplies + "skus listed" flag
  try {
    const { rows } = await pool.query(`
      SELECT p.sku, coalesce(p.product_name,'') name, coalesce(p.category,'') category,
        coalesce(sum(pi.available) FILTER (WHERE pi.warehouse LIKE '%\\_fba'),0)::int fba,
        coalesce(sum(pi.available) FILTER (WHERE pi.warehouse LIKE '%\\_3pl'),0)::int three_pl,
        (CASE WHEN $${pAwd} THEN coalesce(p.inventory_us_awd,0)::int ELSE 0 END)::int awd,
        (coalesce(sum(pi.available),0) + CASE WHEN $${pAwd} THEN coalesce(p.inventory_us_awd,0)::int ELSE 0 END)::int total
      FROM planner.products p
      JOIN planner.v_product_inventory pi ON pi.sku=p.sku
      ${wsql}
      GROUP BY p.sku, p.product_name, p.category, p.inventory_us_awd
      HAVING coalesce(sum(pi.available),0) > 0 OR coalesce(p.inventory_us_awd,0)::int > 0 OR $${pSkuFlag} = true
      ORDER BY total DESC`, [...vals, awdApplies, skus.length > 0]);
    const tot = rows.reduce((a, r) => { a.fba += r.fba; a.three_pl += r.three_pl; a.awd += r.awd; a.total += r.total; return a; }, { fba: 0, three_pl: 0, awd: 0, total: 0 });
    res.json({ rows, totals: tot, sku_count: rows.length, awd_available: awdApplies });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});

// Buy-plan extra stock pools per SKU: AWD (US upstream, inventory_us_awd) + NonGRS on-hand (UK/US). The buy
// plan pools AWD into FBA cover and shows it in its own column; NonGRS is shown as a sub-line under SOH 3PL
// (display only). Defensive on the NonGRS columns so it works if those columns are absent (returns 0 until then).
app.get('/api/buy-extra-stock', async (req, res) => {
  try {
    const cols = (await pool.query(`SELECT column_name FROM information_schema.columns
      WHERE table_schema='planner' AND table_name='products'
        AND column_name IN ('inventory_uk_nongrs','inventory_us_nongrs')`)).rows.map(r => r.column_name);
    const ukn = cols.includes('inventory_uk_nongrs') ? 'coalesce(inventory_uk_nongrs,0)' : '0';
    const usn = cols.includes('inventory_us_nongrs') ? 'coalesce(inventory_us_nongrs,0)' : '0';
    const rows = (await pool.query(`SELECT sku, coalesce(inventory_us_awd,0)::int awd, ${ukn}::int nuk, ${usn}::int nus
      FROM planner.products WHERE in_planning_scope`)).rows;
    const stock = {};
    rows.forEach(r => { if (r.awd || r.nuk || r.nus) stock[r.sku] = { awd: r.awd, nuk: r.nuk, nus: r.nus }; });
    res.json({ stock, has_nongrs: cols.length === 2 });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});

// B2B Allocation — per requested SKU: available stock in the market, recent velocity (cover),
// per-unit weight (airfreight rush), wholesale price (50% of ex-VAT retail) and avg cost (margin).
app.post('/api/scenario/b2b', async (req, res) => {
  const b = req.body || {};
  const skus = (Array.isArray(b.skus) ? b.skus : []).filter(Boolean).map(s => s.trim().toUpperCase());
  const market = (b.market || 'UK').toLowerCase();
  const date = (b.date && /^\d{4}-\d{2}-\d{2}$/.test(b.date)) ? b.date : null;   // required-by date for the B2B order
  if (!skus.length) return res.json({ rows: [] });
  try {
    const { rows } = await pool.query(`
      SELECT p.sku, coalesce(p.product_name,'') name, coalesce(p.category,'') category,
        (coalesce((SELECT sum(available) FROM planner.v_product_inventory pi WHERE pi.sku=p.sku AND pi.warehouse LIKE $2||'\\_%'),0)
         + CASE WHEN $2='us' THEN coalesce(p.inventory_us_awd,0)::int ELSE 0 END)::int available,
        coalesce((SELECT sum(units) FROM planner.sales_actuals sa WHERE sa.sku=p.sku AND lower(sa.country)=$2
                  AND sa.month > (SELECT max(month) FROM planner.sales_actuals) - interval '3 months'),0)::int recent_units,
        p.prod_weight_uk weight,
        (CASE $2 WHEN 'uk' THEN p.uk_rt WHEN 'us' THEN p.us_rt WHEN 'eu' THEN p.eu_rt
                 WHEN 'au' THEN p.au_rt WHEN 'ca' THEN p.ca_rt END) retail,
        (CASE $2 WHEN 'uk' THEN p.cogs_uk_3pl_final WHEN 'us' THEN p.cogs_us_3pl_final WHEN 'eu' THEN p.cogs_eu_3pl_final
                 WHEN 'au' THEN p.cogs_au_3pl_final WHEN 'ca' THEN p.cogs_ca_3pl_final END) cogs,
        (SELECT round(avg(cost_price),2) FROM planner.purchase_order_lines l WHERE l.sku=p.sku AND coalesce(cost_price,0) > 0) avg_cost,
        -- inbound for this market: landing on/before the order date (only when a date is given), plus the next inbound
        coalesce((SELECT sum(ib.quantity - coalesce(ib.received_quantity,0)) FROM planner.inbound_shipments ib
           WHERE ib.sku=p.sku AND ib.destination_warehouse LIKE $2||'\\_%' AND ib.quantity > coalesce(ib.received_quantity,0)
             AND $3::date IS NOT NULL AND ib.estimated_delivery_date <= $3::date),0)::int inbound_by_date,
        coalesce((SELECT sum(ib.quantity - coalesce(ib.received_quantity,0)) FROM planner.inbound_shipments ib
           WHERE ib.sku=p.sku AND ib.destination_warehouse LIKE $2||'\\_%' AND ib.quantity > coalesce(ib.received_quantity,0)),0)::int inbound_total,
        to_char((SELECT min(ib.estimated_delivery_date) FROM planner.inbound_shipments ib
           WHERE ib.sku=p.sku AND ib.destination_warehouse LIKE $2||'\\_%' AND ib.quantity > coalesce(ib.received_quantity,0)
             AND ib.estimated_delivery_date >= CURRENT_DATE),'YYYY-MM-DD') next_inbound_date,
        coalesce((SELECT sum(ib.quantity - coalesce(ib.received_quantity,0)) FROM planner.inbound_shipments ib
           WHERE ib.sku=p.sku AND ib.destination_warehouse LIKE $2||'\\_%' AND ib.quantity > coalesce(ib.received_quantity,0)
             AND ib.estimated_delivery_date = (SELECT min(ib2.estimated_delivery_date) FROM planner.inbound_shipments ib2
                WHERE ib2.sku=p.sku AND ib2.destination_warehouse LIKE $2||'\\_%' AND ib2.quantity > coalesce(ib2.received_quantity,0) AND ib2.estimated_delivery_date >= CURRENT_DATE)),0)::int next_inbound_qty,
        -- in-production stock that could be pulled/expedited: OPEN Production-status POs carrying this SKU, EXCLUDING
        -- Direct-to-Client POs (their units are already committed). Any market — branch shown so a redirect is visible.
        coalesce((SELECT json_agg(json_build_object('po',po2.po,'qty',l2.qty::int,'branch',coalesce(po2.branch,''),
             'supplier',coalesce(po2.supplier_name,''),'prod_no',coalesce(po2.prod_no,''),
             'date', to_char(coalesce(po2.delivery_date_overide,po2.landing_date_overide,po2.end_production_overide),'YYYY-MM-DD'))
             ORDER BY coalesce(po2.delivery_date_overide,po2.landing_date_overide,po2.end_production_overide) NULLS LAST)
           FROM planner.purchase_order_lines l2 JOIN planner.purchase_orders po2 ON po2.po=l2.po
           WHERE l2.sku=p.sku AND coalesce(l2.qty,0)>0 AND coalesce(po2.status,'') ILIKE 'production%'
             AND coalesce(po2.branch,'') NOT ILIKE '%direct to client%'
             AND coalesce(po2.branch,'') NOT ILIKE '%jlew%' AND coalesce(po2.branch,'') NOT ILIKE '%next%'), '[]'::json) production
      FROM planner.products p WHERE upper(p.sku) = ANY($1)`, [skus, market, date]);
    res.json({ market: market.toUpperCase(), date, rows });
  } catch (e) { log500(e); res.status(500).json({ error: e.message }); }
});

